class _AnimatedScoreRing extends StatelessWidget {
  final double? targetScore;
  final bool isDark;
  final Color activeColor;
  final Object? animationKey;

  const _AnimatedScoreRing({
    required this.targetScore,
    required this.isDark,
    required this.activeColor,
    this.animationKey,
  });

  @override
  Widget build(BuildContext context) {
    if (targetScore == null) {
      return Stack(
        alignment: Alignment.center,
        children: [
          CustomPaint(
            size: const Size(76, 76),
            painter: _NeonScoreRingPainter(
              scorePercent: 0,
              isDark: isDark,
              activeColor: activeColor,
            ),
          ),
          Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                '--',
                style: TextStyle(
                  fontSize: 17,
                  fontWeight: FontWeight.w900,
                  letterSpacing: -0.5,
                  color: isDark ? Colors.white38 : const Color(0xff94A3B8),
                ),
              ),
              Text(
                'SAFETY SCORE',
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontSize: 6.5,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 0.5,
                  color: isDark ? Colors.white38 : const Color(0xff94A3B8),
                ),
              ),
            ],
          ),
        ],
      );
    }

    return TweenAnimationBuilder<double>(
      key: ValueKey('score_ring_${targetScore}_${animationKey ?? key ?? ""}'),
      tween: Tween<double>(begin: 0.0, end: targetScore!),
      duration: const Duration(milliseconds: 800),
      curve: Curves.easeOutCubic,
      builder: (context, animatedScore, child) {
        final isComplete = targetScore != null && animatedScore >= (targetScore! - 0.5);
        return Stack(
          alignment: Alignment.center,
          children: [
            if (isComplete)
              Container(
                width: 72,
                height: 72,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  boxShadow: [
                    BoxShadow(
                      color: activeColor.withValues(alpha: 0.18),
                      blurRadius: 12,
                      spreadRadius: 1,
                    ),
                  ],
                ),
              ),
            CustomPaint(
              size: const Size(76, 76),
              painter: _NeonScoreRingPainter(
                scorePercent: animatedScore,
                isDark: isDark,
                activeColor: activeColor,
              ),
            ),
            Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  '${animatedScore.round()}%',
                  style: TextStyle(
                    fontSize: 17,
                    fontWeight: FontWeight.w900,
                    letterSpacing: -0.5,
                    color: isDark ? Colors.white : const Color(0xff0F172A),
                  ),
                ),
                Text(
                  'SAFETY SCORE',
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    fontSize: 6.5,
                    fontWeight: FontWeight.w800,
                    letterSpacing: 0.5,
                    color: isDark ? _NeonTheme.neonCyan : const Color(0xff0D5BD8),
                  ),
                ),
              ],
            ),
          ],
        );
      },
    );
  }
}

class _StaggeredEntrance extends StatelessWidget {
  final Widget child;
  final int delayMs;
  final Offset slideOffset;
  final bool animateScale;
  final Object? trigger;

  const _StaggeredEntrance({
    super.key,
    required this.child,
    this.delayMs = 0,
    this.slideOffset = const Offset(0, 16.0),
    this.animateScale = false,
    this.trigger,
  });

  static const Duration _duration = Duration(milliseconds: 360);

  @override
  Widget build(BuildContext context) {
    return TweenAnimationBuilder<double>(
      key: ValueKey('stagger_${trigger ?? key ?? ""}_$delayMs'),
      tween: Tween<double>(begin: 0.0, end: 1.0),
      duration: _duration + Duration(milliseconds: delayMs),
      curve: Curves.easeOutCubic,
      builder: (context, progress, childWidget) {
        final totalMs = _duration.inMilliseconds + delayMs;
        final startFrac = totalMs > 0 ? (delayMs / totalMs) : 0.0;
        final effectiveFrac = progress <= startFrac
            ? 0.0
            : ((progress - startFrac) / (1.0 - startFrac)).clamp(0.0, 1.0);
        final curvedVal = Curves.easeOutCubic.transform(effectiveFrac);

        final dyPixels = slideOffset.dy.abs() <= 1.0
            ? slideOffset.dy * 450.0
            : slideOffset.dy;
        final dxPixels = slideOffset.dx.abs() <= 1.0
            ? slideOffset.dx * 450.0
            : slideOffset.dx;

        Widget result = Opacity(
          opacity: curvedVal,
          child: Transform.translate(
            offset: Offset(
              dxPixels * (1.0 - curvedVal),
              dyPixels * (1.0 - curvedVal),
            ),
            child: childWidget,
          ),
        );
        if (animateScale) {
          result = Transform.scale(
            scale: 0.97 + (0.03 * curvedVal),
            child: result,
          );
        }
        return result;
      },
      child: child,
    );
  }
}

class _InteractivePressButton extends StatefulWidget {
  final Widget child;
  final VoidCallback? onPressed;

  const _InteractivePressButton({
    required this.child,
    this.onPressed,
  });

  @override
  State<_InteractivePressButton> createState() => _InteractivePressButtonState();
}

class _InteractivePressButtonState extends State<_InteractivePressButton> {
  bool _isPressed = false;
  bool _isHovered = false;

  @override
  Widget build(BuildContext context) {
    final double targetScale = _isPressed
        ? 0.97
        : (_isHovered ? 1.01 : 1.0);

    return MouseRegion(
      cursor: SystemMouseCursors.click,
      onEnter: (_) => setState(() => _isHovered = true),
      onExit: (_) => setState(() => _isHovered = false),
      child: GestureDetector(
        onTapDown: (_) => setState(() => _isPressed = true),
        onTapUp: (_) {
          setState(() => _isPressed = false);
          widget.onPressed?.call();
        },
        onTapCancel: () => setState(() => _isPressed = false),
        child: AnimatedScale(
          scale: targetScale,
          duration: Duration(milliseconds: _isPressed ? 100 : 160),
          curve: Curves.easeOutCubic,
          child: widget.child,
        ),
      ),
    );
  }
}

