enum _RouteFacilityGroup {
  hospitals,
  police,
  petrolEv,
  pharmacies,
  restaurants,
  other,
  all;

  String get label => switch (this) {
    _RouteFacilityGroup.hospitals => 'Hospitals',
    _RouteFacilityGroup.police => 'Police Stations',
    _RouteFacilityGroup.petrolEv => 'Petrol / EV',
    _RouteFacilityGroup.pharmacies => 'Pharmacies',
    _RouteFacilityGroup.restaurants => 'Restaurants',
    _RouteFacilityGroup.other => 'Other Facilities',
    _RouteFacilityGroup.all => 'Show All',
  };

  IconData get icon => switch (this) {
    _RouteFacilityGroup.hospitals => Icons.local_hospital_rounded,
    _RouteFacilityGroup.police => Icons.shield_rounded,
    _RouteFacilityGroup.petrolEv => Icons.local_gas_station_rounded,
    _RouteFacilityGroup.pharmacies => Icons.medication_rounded,
    _RouteFacilityGroup.restaurants => Icons.restaurant_rounded,
    _RouteFacilityGroup.other => Icons.place_rounded,
    _RouteFacilityGroup.all => Icons.layers_rounded,
  };

  Color get color => switch (this) {
    _RouteFacilityGroup.hospitals => const Color(0xffE11D48),
    _RouteFacilityGroup.police => const Color(0xff2563EB),
    _RouteFacilityGroup.petrolEv => const Color(0xffD97706),
    _RouteFacilityGroup.pharmacies => const Color(0xff059669),
    _RouteFacilityGroup.restaurants => const Color(0xffEA580C),
    _RouteFacilityGroup.other => const Color(0xff7C3AED),
    _RouteFacilityGroup.all => _NeonTheme.neonCyan,
  };

  bool matches(Facility f) {
    return switch (this) {
      _RouteFacilityGroup.hospitals => f.categoryId == 'hospital',
      _RouteFacilityGroup.police => f.categoryId == 'police',
      _RouteFacilityGroup.petrolEv =>
        f.categoryId == 'petrol' || f.categoryId == 'fuel' || f.categoryId == 'ev',
      _RouteFacilityGroup.pharmacies => f.categoryId == 'pharmacy',
      _RouteFacilityGroup.restaurants =>
        f.categoryId == 'restaurant' ||
        f.categoryId == 'cafe' ||
        f.categoryId == 'fast_food' ||
        f.categoryId == 'food_court',
      _RouteFacilityGroup.other =>
        f.categoryId != 'hospital' &&
        f.categoryId != 'police' &&
        f.categoryId != 'petrol' &&
        f.categoryId != 'fuel' &&
        f.categoryId != 'ev' &&
        f.categoryId != 'pharmacy' &&
        f.categoryId != 'restaurant' &&
        f.categoryId != 'cafe' &&
        f.categoryId != 'fast_food' &&
        f.categoryId != 'food_court',
      _RouteFacilityGroup.all => true,
    };
  }

  List<_FacilityCategory> getCategories(List<_FacilityCategory> allCategories) {
    return switch (this) {
      _RouteFacilityGroup.hospitals =>
        allCategories.where((c) => c.id == 'hospital').toList(growable: false),
      _RouteFacilityGroup.police =>
        allCategories.where((c) => c.id == 'police').toList(growable: false),
      _RouteFacilityGroup.petrolEv =>
        allCategories
            .where((c) => c.id == 'petrol' || c.id == 'ev')
            .toList(growable: false),
      _RouteFacilityGroup.pharmacies =>
        allCategories.where((c) => c.id == 'pharmacy').toList(growable: false),
      _RouteFacilityGroup.restaurants =>
        allCategories.where((c) => c.id == 'restaurant').toList(growable: false),
      _RouteFacilityGroup.other =>
        allCategories
            .where(
              (c) =>
                  c.id != 'hospital' &&
                  c.id != 'police' &&
                  c.id != 'petrol' &&
                  c.id != 'ev' &&
                  c.id != 'pharmacy' &&
                  c.id != 'restaurant',
            )
            .toList(growable: false),
      _RouteFacilityGroup.all => allCategories,
    };
  }

  String get searchLabel => switch (this) {
    _RouteFacilityGroup.hospitals => 'hospitals',
    _RouteFacilityGroup.police => 'police stations',
    _RouteFacilityGroup.petrolEv => 'petrol / EV stations',
    _RouteFacilityGroup.pharmacies => 'pharmacies',
    _RouteFacilityGroup.restaurants => 'restaurants',
    _RouteFacilityGroup.other => 'facilities',
    _RouteFacilityGroup.all => 'facilities',
  };
}

