  final String confidence; // 'Verified', 'Partial', 'Limited', 'Unavailable'

  const SafetyFactorEvidence({
    required this.name,
    required this.score,
    required this.available,
    required this.source,
    required this.evidence,
    required this.freshness,
    required this.confidence,
  });
}

class SafetyFactor {
  final String title;
  final IconData icon;
  final double? score;
  final String scoreLabel;
  final double weight;
  final bool relevant;
  final String? unavailableReason;
  final String? status;
  final String? source;
  final String? evidence;
  final String? freshness;
  final String? confidence;

  SafetyFactor({
    required this.title,
    required this.icon,
    required this.score,
    this.scoreLabel = 'score',
    required this.weight,
    this.relevant = true,
    this.unavailableReason,
    this.status,
    this.source,
    this.evidence,
    this.freshness,
    this.confidence,
  });

  SafetyFactorEvidence get evidenceDetails => SafetyFactorEvidence(
    name: title,
    score: score,
    available: score != null && relevant,
    source: source ?? 'Telemetry sensor',
    evidence: evidence ?? scoreLabel,
    freshness: freshness ??
        ((status == 'Daylight' || title == 'Weather' || title == 'Traffic')
            ? 'Live'
            : 'Verified OSM/NHAI'),
    confidence: confidence ??
        (score == null
            ? 'Unavailable'
            : (status == 'Clear' ||
                    status == 'Daylight' ||
                    (title == 'Weather' && score != null))
                ? 'Verified'
                : (status == 'Unmapped' || status == 'Limited evidence'
                    ? 'Limited'
                    : 'Partial')),
  );
}

class PersonalizedSafetyResult {
  final double? score;
  final List<SafetyFactor> factors;
  final List<SafetyFactor> activeFactors;
  final bool isEvidenceSufficient;
  final String? insufficientDataReason;
  final int evidenceCount;
  final String? routeId;
  final String? origin;
  final String? destination;
  final String? dataFreshness;
  final bool isProvisional;
  final String? safetyMode;
  final String? tripContext;

  PersonalizedSafetyResult({
    required this.score,
    required this.factors,
    required this.activeFactors,
    this.isEvidenceSufficient = true,
    this.insufficientDataReason,
    this.evidenceCount = 0,
    this.routeId,
    this.origin,
    this.destination,
    this.dataFreshness,
    this.isProvisional = false,
    this.safetyMode,
    this.tripContext,
  });

  List<SafetyFactorEvidence> get evidenceList =>
      factors.map((f) => f.evidenceDetails).toList();

  int get verifiedCount =>
      factors.where((f) => f.evidenceDetails.confidence == 'Verified').length;

  int get limitedCount => factors
      .where((f) =>
          f.evidenceDetails.confidence == 'Limited' ||
          f.evidenceDetails.confidence == 'Partial')
      .length;

  int get unavailableCount => factors
      .where((f) =>
          f.evidenceDetails.confidence == 'Unavailable' || f.score == null)
      .length;

  String get evidenceSummary =>
      '$verifiedCount verified · $limitedCount limited · $unavailableCount unavailable';
}

enum TripContextType { short, medium, long }

TripContextType _classifyTrip(double distanceKm, [double? durationMinutes]) {
  if (distanceKm < 20.0 && (durationMinutes == null || durationMinutes < 45.0)) {
    return TripContextType.short;
  } else if (distanceKm < 60.0 && (durationMinutes == null || durationMinutes < 90.0)) {
    return TripContextType.medium;
  } else {
    return TripContextType.long;
  }
}

bool _isDaytimeTravel(String travelTime) {
  if (travelTime == 'Morning' || travelTime == 'Afternoon' || travelTime == 'Day') {
    return true;
  }
  if (travelTime == 'Night' || travelTime == 'Evening') {
    return false;
  }
  if (travelTime == 'Now') {
    final hour = DateTime.now().hour;
    return hour >= 6 && hour < 18;
  }
  return travelTime != 'Night';
}

bool _requiresLightingTravel(String travelTime) {
  if (travelTime == 'Night' || travelTime == 'Evening') {
    return true;
  }
  if (travelTime == 'Morning' || travelTime == 'Afternoon' || travelTime == 'Day') {
    return false;
  }
  if (travelTime == 'Now') {
    final hour = DateTime.now().hour;
    return hour < 6 || hour >= 18;
  }
  return travelTime != 'Day';
}

bool _isBothTravel(String travelTime) => travelTime == 'Both';

PersonalizedSafetyResult calculateAuthoritativeSafetyScore({
  required double? accidentScore,
  required double? roadConditionScore,
  required double? trafficScore,
  required double? weatherScore,
  required double? lightingScore,
  required double? accessibilityScore,
  int accidentSegmentsWithMatches = 0,
  int accidentVerifiedRecordCount = 0,
  String? accidentUnavailableReason,
  int roadConditionSegments = 0,
  int lightingSegments = 0,
  int accessibilitySegments = 0,
  String travelTime = 'Day',
  String priority = 'Safety First',
  PersonalSafetyProfile? profile,
  double? routeDistanceKm,
  double? routeDurationMinutes,
  String? trafficSource,
  String? trafficStatus,
  int? trafficMatchedSamples,
  double? trafficCoveragePercent,
  bool trafficRoadClosure = false,
  String? weatherDescription,
  double? weatherTemperature,
  double? weatherWindSpeed,
  int? weatherCode,
  double? weatherPrecipitation,
  bool isWeatherCached = false,
  DateTime? weatherTimestamp,
}) {
  final effectiveProfile = profile ?? PersonalSafetyProfile.unconfiguredProfile();
  final safetyMode = effectiveProfile.safetyMode;
  final dist = routeDistanceKm ?? 25.0;
  final dur = routeDurationMinutes ?? 35.0;
  final tripContext = _classifyTrip(dist, dur);
  final accessibilityPriority = priority == 'Accessibility Friendly' ||
      effectiveProfile.accessibilityPreference == 'Prefer accessible routes';
  final isDay = _isDaytimeTravel(travelTime);
  final isBoth = _isBothTravel(travelTime);

  // Profile & Context Adaptive Base Weights
  double baseAccidentWeight;
  double baseRoadWeight;
  double baseTrafficWeight;
  double baseWeatherWeight;
  double baseLightingWeight;
  double baseAccessibilityWeight;

  if (safetyMode == 'Women Safety') {
    baseAccidentWeight = 0.25;
    baseRoadWeight = 0.15;
    baseTrafficWeight = 0.10;
    baseWeatherWeight = 0.10;
    baseLightingWeight = isDay ? 0.05 : (isBoth ? 0.20 : 0.30);
    baseAccessibilityWeight = 0.10;
  } else if (safetyMode == 'Senior Friendly') {
    baseAccidentWeight = 0.20;
    baseRoadWeight = 0.25;
    baseTrafficWeight = 0.10;
    baseWeatherWeight = 0.05;
    baseLightingWeight = isDay ? 0.0 : 0.05;
    baseAccessibilityWeight = 0.35;
  } else if (safetyMode == 'Family Safety') {
    baseAccidentWeight = 0.35;
    baseRoadWeight = 0.20;
    baseTrafficWeight = 0.15;
    baseWeatherWeight = 0.15;
    baseLightingWeight = isDay ? 0.0 : 0.05;
    baseAccessibilityWeight = 0.10;
  } else {
    // General Mode
    baseAccidentWeight = accessibilityPriority
        ? 0.20
        : (tripContext == TripContextType.short ? 0.35 : 0.30);
    baseRoadWeight = accessibilityPriority
        ? 0.15
        : (tripContext == TripContextType.short ? 0.25 : 0.20);
    baseTrafficWeight = accessibilityPriority ? 0.10 : 0.15;
    baseWeatherWeight = tripContext == TripContextType.long ? 0.15 : 0.10;
    baseLightingWeight = isDay ? 0.0 : (isBoth ? 0.05 : 0.10);
    baseAccessibilityWeight = accessibilityPriority ? 0.35 : 0.15;
  }

  // Weather freshness check (within 30 mins fresh, older stale)
  final String weatherFreshness;
  final String weatherConfidence;
  if (weatherScore == null) {
    weatherFreshness = 'Unavailable';
    weatherConfidence = 'Unavailable';
  } else if (weatherTimestamp != null) {
    final ageMinutes = DateTime.now().difference(weatherTimestamp).inMinutes.abs();
    if (ageMinutes <= 30) {
      weatherFreshness = 'Live 15m';
      weatherConfidence = 'Verified';
    } else {
      weatherFreshness = 'Stale (> 30m)';
      weatherConfidence = 'Provisional';
    }
  } else {
    weatherFreshness = isWeatherCached ? 'Cached 15m' : 'Live 15m';
    weatherConfidence = 'Verified';
  }

  final factors = <SafetyFactor>[
    SafetyFactor(
      title: 'Accident Risk',
      icon: Icons.shield_rounded,
      score: accidentScore,
      scoreLabel: accidentSegmentsWithMatches == 0
          ? 'Verified accident data: No matched blackspots'
          : '$accidentSegmentsWithMatches verified blackspot${accidentSegmentsWithMatches == 1 ? '' : 's'} near route',
      weight: baseAccidentWeight,
      source: 'Verified TN accident blackspots',
      evidence: accidentScore != null
          ? '$accidentVerifiedRecordCount records screened'
          : 'No verified accident records mapped for corridor',
      freshness: 'Verified Dataset v2024',
      confidence: accidentScore != null ? 'Verified' : 'Unavailable',
      status: accidentScore != null
          ? (accidentSegmentsWithMatches == 0 ? 'Clear' : 'Caution')
          : 'Unavailable',
      unavailableReason: accidentScore == null
          ? accidentUnavailableReason ?? 'Verified accident data unavailable'
          : null,
    ),
    SafetyFactor(
      title: 'Road Condition',
      icon: Icons.add_road_rounded,
      score: roadConditionScore,
      scoreLabel: roadConditionScore != null
          ? '$roadConditionSegments road segments with verified tags'
          : 'Road attributes unmapped for this route',
      weight: baseRoadWeight,
      source: 'OpenStreetMap verified road attributes',
      evidence: roadConditionScore != null
          ? '$roadConditionSegments segments with surface/smoothness tags'
          : 'Road attributes unmapped for this route',
      freshness: 'OSM Overpass Live',
      confidence: roadConditionScore != null
          ? (roadConditionSegments >= 5 ? 'Verified' : 'Partial')
          : 'Limited',
      status: roadConditionScore != null ? 'Available' : 'Unmapped',
      unavailableReason: roadConditionScore == null
          ? 'Road attributes unmapped for this route'
          : null,
    ),
    SafetyFactor(
      title: 'Traffic',
      icon: Icons.traffic_rounded,
      score: trafficScore,
      scoreLabel: trafficScore != null
          ? (trafficRoadClosure
                ? 'Road closure reported by TomTom'
                : '${trafficMatchedSamples ?? 0} matched samples · ${trafficCoveragePercent?.toStringAsFixed(0) ?? 0}% coverage')
          : 'Live traffic unavailable',
      weight: baseTrafficWeight,
      status: trafficStatus ?? 'Unavailable',
      source: trafficSource ?? 'TomTom live flow',
      evidence: trafficScore != null
          ? '${trafficCoveragePercent?.toStringAsFixed(0) ?? 0}% corridor telemetry'
          : 'TomTom flow sensor unavailable',
      freshness: trafficScore != null ? 'Live 1m' : 'Unavailable',
      confidence: trafficScore != null ? 'Verified' : 'Unavailable',
      unavailableReason: trafficScore == null
          ? 'Live traffic unavailable'
          : null,
    ),
    SafetyFactor(
      title: 'Weather',
      icon: Icons.cloud_rounded,
      score: weatherScore,
      scoreLabel: (weatherScore != null && weatherDescription != null)
          ? '$weatherDescription · ${weatherTemperature?.toStringAsFixed(0) ?? ''}°C, ${weatherWindSpeed?.toStringAsFixed(0) ?? ''} km/h wind'
          : (weatherScore != null
                ? 'Open-Meteo observations'
                : 'Open-Meteo observations unavailable'),
      weight: baseWeatherWeight,
      source: 'Open-Meteo Weather Forecast API',
      evidence: weatherScore != null
          ? '${weatherTemperature?.toStringAsFixed(0) ?? ''}°C, ${weatherPrecipitation ?? 0}mm rain, code ${weatherCode ?? 0}'
          : 'Weather station radar unavailable',
      freshness: weatherFreshness,
      confidence: weatherConfidence,
      status: weatherScore != null ? 'Available' : 'Unavailable',
      unavailableReason: weatherScore == null
          ? 'Open-Meteo data unavailable for this route'
          : null,
    ),
    SafetyFactor(
      title: 'Lighting',
      icon: Icons.lightbulb_rounded,
      score: isDay ? 100.0 : lightingScore,
      scoreLabel: isDay
          ? 'Daytime travel (natural light)'
          : (isBoth
                ? 'Night portion ($lightingSegments segments with explicit lit tags)'
                : (lightingScore != null
                      ? '$lightingSegments matched segments with explicit lit tags'
                      : 'Lighting data unmapped for this route')),
      weight: baseLightingWeight,
      relevant: true,
      source: isDay ? 'Daylight calculation' : 'OpenStreetMap lit tags',
      evidence: isDay
          ? 'Solar altitude daytime calculation'
          : (lightingScore != null
              ? '$lightingSegments segments with explicit lit=yes/no tags'
              : 'No explicit lit tags along corridor'),
      freshness: isDay ? 'Daylight Verified' : 'OSM Overpass Live',
      confidence: isDay
          ? 'Verified'
          : (lightingScore != null
              ? (lightingSegments >= 3 ? 'Verified' : 'Partial')
              : 'Unavailable'),
      status: isDay
          ? 'Daylight'
          : (lightingScore != null ? 'Available' : 'Unmapped'),
      unavailableReason: isDay
          ? null
          : (lightingScore == null
                ? (isBoth
                      ? 'Unavailable · no explicit lit=yes/no tags for night portion'
                      : 'Lighting data unmapped for this route')
                : null),
    ),
    SafetyFactor(
      title: 'Accessibility',
      icon: Icons.accessible_rounded,
      score: accessibilityScore,
      scoreLabel: accessibilityScore != null
          ? '$accessibilitySegments matched segments with explicit tags'
          : 'Accessibility data unmapped for this corridor',
      weight: baseAccessibilityWeight,
      source: 'OpenStreetMap accessibility tags',
      evidence: accessibilityScore != null
          ? '$accessibilitySegments segments with wheelchair/sidewalk tags'
          : 'Accessibility tags unmapped along corridor',
      freshness: 'OSM Overpass Live',
      confidence: accessibilityScore != null
          ? (accessibilitySegments >= 3 ? 'Verified' : 'Partial')
          : 'Limited',
      status: accessibilityScore != null ? 'Available' : 'Unmapped',
      unavailableReason: accessibilityScore == null
          ? 'Accessibility data unmapped for this corridor'
          : null,
    ),
  ];

  final eligibleFactors = factors
      .where((factor) => factor.relevant && factor.score != null)
      .toList();

  final hasAccident = factors.any(
    (f) => f.title == 'Accident Risk' && f.score != null,
  );
  final hasRoad = factors.any(
    (f) => f.title == 'Road Condition' && f.score != null,
  );
  final hasTraffic = factors.any(
    (f) => f.title == 'Traffic' && f.score != null,
  );
  final hasCoreInfrastructure = hasAccident || hasRoad || hasTraffic;
  final isFullEvidence =
      eligibleFactors.length >= 3 && hasCoreInfrastructure;
  final isProvisional =
      !isFullEvidence && eligibleFactors.length >= 2 && hasCoreInfrastructure;
  final isEvidenceSufficient = isFullEvidence || isProvisional;

  final String? insufficientReason;
  if (!isEvidenceSufficient) {
    final missingParts = <String>[];
    if (!hasCoreInfrastructure) {
      missingParts.add(
        'core infrastructure data (accident blackspots, OSM road attributes, or live traffic)',
      );
    }
    if (eligibleFactors.length < 2) {
      missingParts.add(
        'at least 2 verified independent factors (currently ${eligibleFactors.length})',
      );
    }
    insufficientReason =
        'Safety score unavailable: Requires ${missingParts.join(' and ')}.';
  } else {
    insufficientReason = null;
  }

  final totalEligibleWeight = eligibleFactors.fold<double>(
    0.0,
    (sum, factor) => sum + factor.weight,
  );

  final activeFactors = (!isEvidenceSufficient || totalEligibleWeight == 0.0)
      ? <SafetyFactor>[]
      : eligibleFactors.map((factor) {
          return SafetyFactor(
            title: factor.title,
            icon: factor.icon,
            score: factor.score,
            scoreLabel: factor.scoreLabel,
            weight: factor.weight / totalEligibleWeight,
            relevant: factor.relevant,
            status: factor.status,
            source: factor.source,
            evidence: factor.evidence,
            freshness: factor.freshness,
            confidence: factor.confidence,
          );
        }).toList();

  final finalScore = (!isEvidenceSufficient || activeFactors.isEmpty)
      ? null
      : activeFactors.fold<double>(
          0.0,
          (sum, factor) => sum + factor.score! * factor.weight,
        );

  final normalizedWeightMap = {
    for (final factor in activeFactors) factor.title: factor.weight,
  };

  final displayFactors = factors.map((factor) {
    final normalized = normalizedWeightMap[factor.title];
    return SafetyFactor(
      title: factor.title,
      icon: factor.icon,
      score: factor.score,
      scoreLabel: factor.scoreLabel,
      weight: normalized ?? 0.0,
      relevant: factor.relevant,
      unavailableReason: factor.unavailableReason,
      status: factor.status,
      source: factor.source,
      evidence: factor.evidence,
      freshness: factor.freshness,
      confidence: factor.confidence,
    );
  }).toList();

  return PersonalizedSafetyResult(
    score: finalScore,
    factors: displayFactors,
    activeFactors: activeFactors,
    isEvidenceSufficient: isEvidenceSufficient,
    insufficientDataReason: insufficientReason,
    evidenceCount: eligibleFactors.length,
    isProvisional: isProvisional,
    safetyMode: safetyMode,
    tripContext: tripContext.name,
  );
}

int selectRecommendedRouteIndex({
  required List<RouteEvaluation> candidates,
  PersonalSafetyProfile? profile,
  String travelTime = 'Day',
  String priority = 'Safety First',
}) {
  if (candidates.isEmpty) return 0;
  if (candidates.length == 1) return 0;

  final effectiveProfile = profile ?? PersonalSafetyProfile.unconfiguredProfile();
  final isBoth = _isBothTravel(travelTime);
  final isDay = _isDaytimeTravel(travelTime);
  final safetyMode = effectiveProfile.safetyMode;
  final accessibilityPriority = priority == 'Accessibility Friendly' ||
      effectiveProfile.accessibilityPreference == 'Prefer accessible routes';

  Map<String, double> factorWeights;
  if (safetyMode == 'Women Safety') {
    factorWeights = <String, double>{
      'Accident Risk': 0.25,
      'Road Condition': 0.15,
      'Traffic': 0.10,
      'Weather': 0.10,
      'Lighting': isDay ? 0.05 : (isBoth ? 0.25 : 0.30),
      'Accessibility': 0.10,
    };
  } else if (safetyMode == 'Senior Friendly') {
    factorWeights = <String, double>{
      'Accessibility': 0.35,
      'Road Condition': 0.25,
      'Accident Risk': 0.20,
      'Traffic': 0.10,
      'Weather': 0.05,
      'Lighting': isDay ? 0.0 : 0.05,
    };
  } else if (safetyMode == 'Family Safety') {
    factorWeights = <String, double>{
      'Accident Risk': 0.35,
      'Road Condition': 0.20,
      'Weather': 0.15,
      'Traffic': 0.15,
      'Accessibility': 0.10,
      'Lighting': isDay ? 0.0 : 0.05,
    };
  } else {
    factorWeights = <String, double>{
      'Accident Risk': accessibilityPriority ? 0.20 : 0.30,
      'Road Condition': accessibilityPriority ? 0.15 : 0.20,
      'Traffic': accessibilityPriority ? 0.10 : 0.15,
      'Weather': 0.10,
      'Lighting': isDay
          ? 0.0
          : ((accessibilityPriority ? 0.10 : 0.10) * (isBoth ? 0.5 : 1.0)),
      'Accessibility': accessibilityPriority ? 0.35 : 0.15,
    };
  }

  double scoreFor(RouteEvaluation evaluation) {
    var weightedScore = 0.0;
    var totalWeight = 0.0;
    for (final f in evaluation.safety.factors) {
      if (f.score != null && factorWeights.containsKey(f.title)) {
        final w = factorWeights[f.title]!;
        weightedScore += f.score! * w;
        totalWeight += w;
      }
    }
    if (totalWeight > 0) return weightedScore / totalWeight;
    return evaluation.safety.score ?? 0.0;
  }

  final minDistance = candidates.map((c) => c.route.distance).reduce(math.min);
  final minDuration = candidates.map((c) => c.route.duration).reduce(math.min);

  double compositeScoreFor(RouteEvaluation evaluation) {
    final s = scoreFor(evaluation);
    final durEfficiency = evaluation.route.duration > 0
        ? (minDuration / evaluation.route.duration).clamp(0.4, 1.0) * 100.0
        : 100.0;
    final distEfficiency = evaluation.route.distance > 0
        ? (minDistance / evaluation.route.distance).clamp(0.4, 1.0) * 100.0
        : 100.0;

    double trafficBonus = 0.0;
    if (evaluation.traffic != null) {
      if (evaluation.traffic!.roadClosure) {
        trafficBonus -= 25.0;
      } else if (evaluation.traffic!.meanSpeedRatio >= 0.85) {
        trafficBonus += 5.0;
      }
    }

    if (priority == 'Faster Route' || effectiveProfile.safetyPriority == 'Faster Route') {
      return (durEfficiency * 0.60) + (distEfficiency * 0.20) + (s * 0.20) + trafficBonus;
    }
    if (safetyMode == 'Women Safety') {
      return (s * 0.75) + (durEfficiency * 0.15) + (distEfficiency * 0.10) + trafficBonus;
    }
    if (safetyMode == 'Senior Friendly') {
      return (s * 0.80) + (durEfficiency * 0.10) + (distEfficiency * 0.10) + trafficBonus;
    }
    if (safetyMode == 'Family Safety') {
      return (s * 0.70) + (durEfficiency * 0.15) + (distEfficiency * 0.15) + trafficBonus;
    }
    if (accessibilityPriority) {
      return (s * 0.80) + (durEfficiency * 0.10) + (distEfficiency * 0.10) + trafficBonus;
    }

    return (s * 0.65) + (durEfficiency * 0.15) + (distEfficiency * 0.15) + trafficBonus;
  }

  final sorted = List<RouteEvaluation>.from(candidates);
  sorted.sort((a, b) {
    final cmp = compositeScoreFor(b).compareTo(compositeScoreFor(a));
    if (cmp != 0) return cmp;
    return a.route.duration.compareTo(b.route.duration);
  });

  return candidates.indexOf(sorted.first);
}

