class SafeRouteService {
  static const _maxOsmRouteSamples = 18;
  static const _osmSamplesPerQuery = 18;
  static const _osmQueryRadiusMeters = 50.0;
  static final Map<String, List<_OsmRoadSegment>> _osmRoadSegmentsCache = {};
  static final Map<String, Future<List<_OsmRoadSegment>?>>
  _inFlightOsmRequests = {};
  static DateTime? _lastOverpassFailureTime;

  static String _osmRouteCacheKey(List<LatLng> routePoints) {
    if (routePoints.isEmpty) return '';
    final start = routePoints.first;
    final end = routePoints.last;
    final mid = routePoints[routePoints.length ~/ 2];
    return '${start.latitude.toStringAsFixed(4)},${start.longitude.toStringAsFixed(4)}->'
        '${mid.latitude.toStringAsFixed(4)},${mid.longitude.toStringAsFixed(4)}->'
        '${end.latitude.toStringAsFixed(4)},${end.longitude.toStringAsFixed(4)}#${routePoints.length}';
  }

  static const _acceptablePlaceTypes = {
    'city',
    'town',
    'village',
    'hamlet',
    'suburb',
    'neighbourhood',
    'municipality',
    'administrative',
    'tourism',
    'attraction',
    'landmark',
    'resort',
    'station',
    'amenity',
    'place',
    'temple',
    'hospital',
    'college',
    'beach',
    'viewpoint',
    'water',
    'locality',
    'lake',
    'waterfall',
    'hill',
    'peak',
    'park',
    'historic',
  };

  static const _addressTypes = {'road', 'house', 'residential', 'address'};
  static const double _tnMinLat = 8.0;
  static const double _tnMaxLat = 13.6;
  static const double _tnMinLon = 76.1;
  static const double _tnMaxLon = 80.4;

  Future<Position?> getCurrentLocation() async {
    bool serviceEnabled;
    LocationPermission permission;

    serviceEnabled = await Geolocator.isLocationServiceEnabled();

    if (!serviceEnabled) {
      debugPrint('Location service is disabled.');
      return null;
    }

    permission = await Geolocator.checkPermission();

    if (permission == LocationPermission.denied) {
      permission = await Geolocator.requestPermission();

      if (permission == LocationPermission.denied) {
        debugPrint('Location permission denied.');
        return null;
      }
    }

    if (permission == LocationPermission.deniedForever) {
      debugPrint('Location permission permanently denied.');
      return null;
    }

    final position = await Geolocator.getCurrentPosition(
      locationSettings: const LocationSettings(accuracy: LocationAccuracy.high),
    );

    debugPrint(
      'CURRENT LOCATION: '
      '${position.latitude}, ${position.longitude}',
    );

    return position;
  }

  String _normalizeGeocodeText(String value) {
    return value.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), ' ').trim();
  }

  bool _isTamilNaduResult(Map<String, dynamic> result) {
    final address = result['address'];
    final country = address is Map
        ? _normalizeGeocodeText(address['country']?.toString() ?? '')
        : '';
    final countryCode = address is Map
        ? _normalizeGeocodeText(address['country_code']?.toString() ?? '')
        : '';
    final displayName = _normalizeGeocodeText(
      result['display_name']?.toString() ?? '',
    );

    final isIndia = country == 'india' ||
        countryCode == 'in' ||
        displayName.contains('india');

    if (address is Map) {
      final state = _normalizeGeocodeText(address['state']?.toString() ?? '');
      final stateCode = _normalizeGeocodeText(
        address['ISO3166-2-lvl4']?.toString() ?? '',
      );
      if ((state == 'tamil nadu' || stateCode == 'in tn') &&
          (isIndia || country.isEmpty)) {
        return true;
      }
    }

    if (displayName.contains('tamil nadu') && (isIndia || country.isEmpty)) {
      return true;
    }

    final lat = double.tryParse(result['lat']?.toString() ?? '');
    final lon = double.tryParse(result['lon']?.toString() ?? '');
    if (lat != null && lon != null && (isIndia || country.isEmpty)) {
      if (lat >= _tnMinLat &&
          lat <= _tnMaxLat &&
          lon >= _tnMinLon &&
          lon <= _tnMaxLon) {
        return true;
      }
    }

    return false;
  }

  double _geocodeMatchScore(Map<String, dynamic> result, String query) {
    final normalizedQuery = _normalizeGeocodeText(query);
    final queryTokens = normalizedQuery
        .split(' ')
        .where((token) => token.isNotEmpty)
        .toSet();
    if (queryTokens.isEmpty) return 0;

    final address = result['address'];
    final addressFields = address is Map
        ? address.values.map((value) => value.toString()).toList()
        : <String>[];
    final displayName = result['display_name']?.toString() ?? '';
    final name = result['name']?.toString() ?? '';
    final identityFields = [
      name,
      if (address is Map)
        for (final key in [
          'city',
          'town',
          'village',
          'municipality',
          'state_district',
          'county',
          'suburb',
          'neighbourhood',
          'road',
          'house',
          'tourism',
          'amenity',
          'railway',
          'leisure',
          'natural',
          'historic',
        ])
          if (address[key] != null) address[key].toString(),
    ];
    final normalizedIdentities = identityFields
        .map(_normalizeGeocodeText)
        .where((value) => value.isNotEmpty);
    final normalizedDisplayName = _normalizeGeocodeText(displayName);
    final normalizedCandidates = [
      ...normalizedIdentities,
      normalizedDisplayName,
      ...addressFields.map(_normalizeGeocodeText),
    ];

    final hasExactIdentity = normalizedIdentities.any(
      (identity) => identity == normalizedQuery,
    );
    final hasExactAddress = normalizedCandidates.any(
      (candidate) => candidate == normalizedQuery,
    );
    final displayContainsQuery = normalizedDisplayName.contains(
      normalizedQuery,
    );

    // Support common Tamil Nadu aliases/variants (e.g. Ooty -> Udhagamandalam)
    var aliasMatched = false;
    const aliasMap = {
      'ooty': ['udhagamandalam', 'nilgiris', 'ootacamund'],
      'trichy': ['tiruchirappalli', 'tiruchi'],
      'tanjore': ['thanjavur'],
      'tuticorin': ['thoothukudi', 'thoothukkudi'],
      'cape comorin': ['kanyakumari', 'kanniyakumari'],
      'pondicherry': ['puducherry'],
      'madras': ['chennai'],
    };
    for (final entry in aliasMap.entries) {
      if (normalizedQuery.contains(entry.key)) {
        for (final target in entry.value) {
          if (normalizedDisplayName.contains(target)) {
            aliasMatched = true;
            break;
          }
        }
      }
    }

    final matchingTokens = queryTokens
        .where(
          (token) => normalizedCandidates.any(
            (candidate) => candidate.split(' ').contains(token),
          ),
        )
        .length;
    final tokenCoverage = matchingTokens / queryTokens.length;

    var score = hasExactIdentity
        ? 100.0
        : hasExactAddress || displayContainsQuery || aliasMatched
        ? 90.0
        : tokenCoverage * 65.0;

    final resultType = _normalizeGeocodeText(
      '${result['type'] ?? ''} ${result['addresstype'] ?? ''}',
    );
    final typeTokens = resultType.split(' ').toSet();
    if (typeTokens.any(_acceptablePlaceTypes.contains)) {
      score += 15;
    } else if (typeTokens.any(_addressTypes.contains)) {
      score += 12;
    }
    final category = _normalizeGeocodeText(
      result['category']?.toString() ?? '',
    );
    if (hasExactIdentity &&
        _normalizeGeocodeText(name) == normalizedQuery &&
        category.isNotEmpty &&
        category != 'boundary' &&
        category != 'place' &&
        category != 'landuse') {
      score += 25;
    }

    if (_isTamilNaduResult(result)) {
      score += 10;
    } else {
      score -= 100;
    }

    final importance = result['importance'];
    if (importance is num) {
      score += importance.toDouble().clamp(0.0, 1.0).toDouble() * 5;
    }

    return score;
  }

  static final Map<String, _Location> _geocodeCache = {};
  static final Map<String, List<LocationSuggestion>> _suggestionCache = {};

  static const Map<String, List<String>> _knownQueryExpansions = {
    'coi': ['Coimbatore', 'Coimbatore International Airport', 'Coimbatore Junction', 'Gandhipuram, Coimbatore'],
    'oot': ['Ooty', 'Coonoor', 'Kotagiri'],
    'mad': ['Madurai', 'Madurai Airport', 'Madurai Junction'],
    'che': ['Chennai', 'Chennai Central', 'Chennai Airport', 'Marina Beach, Chennai'],
    'tri': ['Trichy', 'Tiruchirappalli', 'Tiruchirappalli Junction'],
    'sal': ['Salem', 'Salem Junction'],
    'ero': ['Erode', 'Erode Junction'],
    'tir': ['Tiruppur', 'Tirunelveli', 'Tiruvannamalai'],
    'kod': ['Kodaikanal'],
    'vel': ['Vellore'],
    'tha': ['Thanjavur'],
    'kan': ['Kanyakumari'],
    'din': ['Dindigul'],
    'pol': ['Pollachi'],
    'hos': ['Hosur'],
    'nag': ['Nagercoil'],
  };

  Future<List<LocationSuggestion>> fetchLocationSuggestions(String query) async {
    final clean = query.trim();
    if (clean.length < 2) return const [];

    final cacheKey = clean.toLowerCase();
    if (_suggestionCache.containsKey(cacheKey)) {
      return _suggestionCache[cacheKey]!;
    }

    final queriesToTry = <String>[clean];
    final lower = clean.toLowerCase();
    for (final entry in _knownQueryExpansions.entries) {
      if (entry.key.startsWith(lower) || lower.startsWith(entry.key)) {
        for (final exp in entry.value) {
          if (!queriesToTry.contains(exp)) {
            queriesToTry.add(exp);
          }
        }
        break;
      }
    }

    final results = <LocationSuggestion>[];
    final seen = <String>{};

    for (var i = 0; i < queriesToTry.length && results.length < 5; i++) {
      final q = queriesToTry[i];
      final url = Uri.https('nominatim.openstreetmap.org', '/search', {
        'q': q,
        'format': 'jsonv2',
        'limit': '5',
        'countrycodes': 'in',
        'addressdetails': '1',
        'accept-language': 'en',
      });

      try {
        final response = await http
            .get(
              url,
              headers: {'User-Agent': 'SafeRouteTN/2.0 (Flutter Web project)'},
            )
            .timeout(const Duration(seconds: 6));

        if (response.statusCode != 200) continue;
        final data = jsonDecode(response.body);
        if (data is! List || data.isEmpty) continue;

        for (final item in data) {
          if (item is! Map<String, dynamic>) continue;
          final lat = double.tryParse(item['lat']?.toString() ?? '');
          final lon = double.tryParse(item['lon']?.toString() ?? '');
          if (lat == null || lon == null) continue;

          final rawName = item['name']?.toString() ?? '';
          final displayName = item['display_name']?.toString() ?? '';
          final title = rawName.isNotEmpty
              ? rawName
              : (displayName.contains(',')
                  ? displayName.split(',').first.trim()
                  : displayName);

          final address = item['address'];
          final subParts = <String>[];
          if (address is Map<String, dynamic>) {
            for (final k in [
              'suburb',
              'city_district',
              'district',
              'county',
              'state_district',
              'state',
              'country',
            ]) {
              final val = address[k]?.toString();
              if (val != null && val.isNotEmpty && !subParts.contains(val) && val != title) {
                subParts.add(val);
              }
            }
          }
          final subtitle = subParts.isNotEmpty
              ? subParts.take(3).join(', ')
              : (displayName.contains(',')
                  ? displayName.split(',').skip(1).take(3).join(', ').trim()
                  : displayName);

          final coordKey = '${lat.toStringAsFixed(3)},${lon.toStringAsFixed(3)}';
          if (!seen.contains(coordKey)) {
            seen.add(coordKey);
            results.add(
              LocationSuggestion(
                title: title,
                subtitle: subtitle,
                lat: lat,
                lon: lon,
                rawDisplayName: displayName,
              ),
            );
            if (results.length >= 5) break;
          }
        }
      } catch (e) {
        debugPrint('Nominatim suggestion fetch error: $e');
      }
    }

    _suggestionCache[cacheKey] = results;
    return results;
  }

  Future<_Location?> searchLocation(String place) async {
    try {
      final cleanQuery = place.trim();
      if (cleanQuery.isEmpty) return null;

      final cacheKey = cleanQuery.toLowerCase();
      if (_geocodeCache.containsKey(cacheKey)) {
        final cached = _geocodeCache[cacheKey]!;
        debugPrint(
          'GEOCODE CACHE HIT: query="$cleanQuery" -> ${cached.lat}, ${cached.lon}',
        );
        return cached;
      }

      final lower = cleanQuery.toLowerCase();
      final hasTN = lower.contains('tamil nadu') || lower.contains('tamilnadu');
      final hasIndia = lower.contains('india');

      final queriesToTry = <String>[];
      if (!hasTN && !hasIndia) {
        queriesToTry.add('$cleanQuery, Tamil Nadu');
        queriesToTry.add(cleanQuery);
        queriesToTry.add('$cleanQuery, Tamil Nadu, India');
      } else if (hasTN && !hasIndia) {
        queriesToTry.add(cleanQuery);
        queriesToTry.add('$cleanQuery, India');
      } else {
        queriesToTry.add(cleanQuery);
      }

      for (var attempt = 0; attempt < queriesToTry.length; attempt++) {
        final queryAttempt = queriesToTry[attempt];
        final url = Uri.https('nominatim.openstreetmap.org', '/search', {
          'q': queryAttempt,
          'format': 'jsonv2',
          'limit': '10',
          'countrycodes': 'in',
          'addressdetails': '1',
          'accept-language': 'en',
        });

        debugPrint(
          'NOMINATIM REQUEST: query="$cleanQuery", attempt=${attempt + 1}/${queriesToTry.length}, url=$url',
        );

        final response = await http
            .get(
              url,
              headers: {'User-Agent': 'SafeRouteTN/2.0 (Flutter Web project)'},
            )
            .timeout(const Duration(seconds: 10));

        debugPrint(
          'NOMINATIM RESPONSE: status=${response.statusCode}, bodyLength=${response.body.length}',
        );

        if (response.statusCode != 200) {
          continue;
        }

        final data = jsonDecode(response.body);
        if (data is! List || data.isEmpty) {
          continue;
        }

        final candidates = <({Map<String, dynamic> result, double score})>[];
        for (final entry in data) {
          if (entry is! Map<String, dynamic>) continue;

          final score = _geocodeMatchScore(entry, cleanQuery);
          debugPrint(
            'GEOCODE CANDIDATE:\n'
            'query=$cleanQuery\n'
            'name=${entry['display_name'] ?? ''}\n'
            'type=${entry['type'] ?? ''}\n'
            'lat=${entry['lat'] ?? ''}\n'
            'lon=${entry['lon'] ?? ''}\n'
            'importance=${entry['importance'] ?? ''}\n'
            'matchScore=$score',
          );
          candidates.add((result: entry, score: score));
        }

        final matchingCandidates =
            candidates
                .where(
                  (candidate) =>
                      _isTamilNaduResult(candidate.result) &&
                      candidate.score >= 15,
                )
                .toList()
              ..sort((a, b) => b.score.compareTo(a.score));

        if (matchingCandidates.isEmpty) {
          continue;
        }

        final item = matchingCandidates.first.result;
        final latitude = double.tryParse(item['lat']?.toString() ?? '');
        final longitude = double.tryParse(item['lon']?.toString() ?? '');
        if (latitude == null || longitude == null) {
          continue;
        }

        debugPrint(
          'GEOCODE FINAL:\n'
          'query=$cleanQuery\n'
          'attempt=${attempt + 1}\n'
          'name=${item['display_name']}\n'
          'lat=$latitude\n'
          'lon=$longitude',
        );

        final locationResult = _Location(
          lat: latitude,
          lon: longitude,
          name: item['display_name'].toString(),
        );
        _geocodeCache[cacheKey] = locationResult;
        return locationResult;
      }

      return null;
    } catch (e) {
      debugPrint('LOCATION ERROR: $e');
      return null;
    }
  }

  Future<double?> getLightingScore(List<LatLng> routePoints) async {
    try {
      if (routePoints.isEmpty) {
        return null;
      }

      // Check 3 points instead of only the middle point
      final indexes = [0, routePoints.length ~/ 2, routePoints.length - 1];

      int successfulSamples = 0;
      int litSamples = 0;

      for (final index in indexes.toSet()) {
        final point = routePoints[index];

        final lat = point.latitude;
        final lon = point.longitude;

        final query =
            '''
[out:json][timeout:15];

(
  node["highway"="street_lamp"]
    (around:500,$lat,$lon);

  way["highway"]["lit"="yes"]
    (around:500,$lat,$lon);
);

out tags;
''';

        final endpoints = [
          'https://overpass-api.de/api/interpreter',
          'https://overpass.kumi.systems/api/interpreter',
        ];

        bool success = false;

        for (final endpoint in endpoints) {
          try {
            final url = Uri.parse(
              '$endpoint?data=${Uri.encodeComponent(query)}',
            );

            final response = await http
                .get(url)
                .timeout(const Duration(seconds: 20));

            debugPrint('LIGHTING STATUS: ${response.statusCode}');

            if (response.statusCode == 200) {
              final data = jsonDecode(response.body);

              final elements = data['elements'] as List<dynamic>? ?? [];
              successfulSamples++;
              if (elements.isNotEmpty) litSamples++;

              success = true;
              break;
            }
          } catch (e) {
            debugPrint('Lighting endpoint failed: $e');
          }
        }

        if (!success) {
          debugPrint('Lighting data unavailable for point $index');
        }
      }

      if (successfulSamples == 0 || litSamples == 0) return null;
      return (litSamples / successfulSamples) * 100;
    } catch (e) {
      debugPrint('LIGHTING ERROR: $e');
      return null;
    }
  }

  Future<double?> getAccessibilityScore(List<LatLng> routePoints) async {
    try {
      if (routePoints.isEmpty) {
        return null;
      }

      final indexes = [0, routePoints.length ~/ 2, routePoints.length - 1];

      int successfulSamples = 0;
      int accessibleSamples = 0;

      for (final index in indexes.toSet()) {
        final point = routePoints[index];

        final lat = point.latitude;
        final lon = point.longitude;

        final query =
            '''
[out:json][timeout:15];

(
  way["sidewalk"]
    (around:500,$lat,$lon);

  way["wheelchair"="yes"]
    (around:500,$lat,$lon);

  way["tactile_paving"="yes"]
    (around:500,$lat,$lon);

  node["crossing"]
    (around:500,$lat,$lon);
);

out tags;
''';

        final endpoints = [
          'https://overpass-api.de/api/interpreter',
          'https://overpass.kumi.systems/api/interpreter',
        ];

        bool success = false;

        for (final endpoint in endpoints) {
          try {
            final url = Uri.parse(
              '$endpoint?data=${Uri.encodeComponent(query)}',
            );

            final response = await http
                .get(url)
                .timeout(const Duration(seconds: 20));

            debugPrint('ACCESSIBILITY STATUS: ${response.statusCode}');

            if (response.statusCode == 200) {
              final data = jsonDecode(response.body);

              final elements = data['elements'] as List<dynamic>? ?? [];
              bool sampleHasAccessibilityData = false;
              successfulSamples++;

              for (final element in elements) {
                final tags = element['tags'] as Map<String, dynamic>? ?? {};

                if (tags.containsKey('sidewalk')) {
                  sampleHasAccessibilityData = true;
                }

                if (tags['wheelchair'] == 'yes') {
                  sampleHasAccessibilityData = true;
                }

                if (tags['tactile_paving'] == 'yes') {
                  sampleHasAccessibilityData = true;
                }

                if (tags.containsKey('crossing')) {
                  sampleHasAccessibilityData = true;
                }
              }
              if (sampleHasAccessibilityData) accessibleSamples++;

              success = true;
              break;
            }
          } catch (e) {
            debugPrint('Accessibility endpoint failed: $e');
          }
        }

        if (!success) {
          debugPrint('Accessibility data unavailable for point $index');
        }
      }

      if (successfulSamples == 0 || accessibleSamples == 0) return null;
      return (accessibleSamples / successfulSamples) * 100;
    } catch (e) {
      debugPrint('ACCESSIBILITY ERROR: $e');
      return null;
    }
  }

  Future<List<_RouteResult>?> getRoutes(_Location start, _Location end) async {
    try {
      // Query all available alternative corridors from OSRM (using standard alternatives=true)
      var url = Uri.parse(
        'https://router.project-osrm.org/route/v1/driving/'
        '${start.lon},${start.lat};'
        '${end.lon},${end.lat}'
        '?overview=full&geometries=geojson&alternatives=true',
      );

      debugPrint('OSRM REQUEST URL: $url');
      var response = await http.get(url).timeout(const Duration(seconds: 12));
      debugPrint('OSRM RESPONSE STATUS: ${response.statusCode}');

      // If alternatives=true rejected or failed, fallback to alternatives=3
      if (response.statusCode != 200) {
        url = Uri.parse(
          'https://router.project-osrm.org/route/v1/driving/'
          '${start.lon},${start.lat};'
          '${end.lon},${end.lat}'
          '?overview=full&geometries=geojson&alternatives=3',
        );
        debugPrint('OSRM FALLBACK REQUEST URL: $url');
        response = await http.get(url).timeout(const Duration(seconds: 12));
        debugPrint('OSRM FALLBACK RESPONSE STATUS: ${response.statusCode}');
      }

      if (response.statusCode != 200) {
        debugPrint('OSRM request failed with status: ${response.statusCode}');
        return null;
      }

      final data = jsonDecode(response.body);

      final routeData = data['routes'] as List<dynamic>?;
      if (routeData == null || routeData.isEmpty) {
        debugPrint('OSRM returned no routes.');
        return null;
      }

      final results = [
        for (var routeIndex = 0; routeIndex < routeData.length; routeIndex++)
          _parseRoute(routeData[routeIndex], routeIndex),
      ];

      final distinctRoutes = filterDistinctRoutes(results);

      debugPrint('OSRM ROUTES FOUND: ${distinctRoutes.length}');
      for (var i = 0; i < distinctRoutes.length; i++) {
        debugPrint(
          'Route $i: ${distinctRoutes[i].distance.toStringAsFixed(1)} km / ${distinctRoutes[i].duration.toStringAsFixed(0)} min / ${distinctRoutes[i].points.length} points',
        );
      }

      return distinctRoutes;
    } catch (e) {
      debugPrint('ROUTE ERROR: $e');
      return null;
    }
  }

  List<_RouteResult> filterDistinctRoutes(List<_RouteResult> rawRoutes) {
    final validRoutes = rawRoutes.where((r) {
      return r.points.length >= 2 && r.distance > 0 && r.duration > 0;
    }).toList();

    final distinct = <_RouteResult>[];
    for (final route in validRoutes) {
      final isDuplicate = distinct.any((existing) {
        final distDiff = (existing.distance - route.distance).abs();
        final durDiff = (existing.duration - route.duration).abs();
        final sameStart = existing.points.first.latitude == route.points.first.latitude &&
            existing.points.first.longitude == route.points.first.longitude;
        final sameEnd = existing.points.last.latitude == route.points.last.latitude &&
            existing.points.last.longitude == route.points.last.longitude;
        return distDiff < 0.05 && durDiff < 0.1 && sameStart && sameEnd;
      });

      if (!isDuplicate) {
        distinct.add(
          _RouteResult(
            points: route.points,
            distance: route.distance,
            duration: route.duration,
            routeIndex: distinct.length,
          ),
        );
      }
    }
    return distinct;
  }

  _RouteResult _parseRoute(dynamic route, int routeIndex) {
    final routeMap = route as Map<String, dynamic>;
    final geometry = routeMap['geometry'] as Map<String, dynamic>;
    final coordinates = geometry['coordinates'] as List<dynamic>;
    final points = coordinates.map((point) {
      return LatLng((point[1] as num).toDouble(), (point[0] as num).toDouble());
    }).toList();
    final distanceMeters = (routeMap['distance'] as num).toDouble();
    final durationSeconds = (routeMap['duration'] as num).toDouble();

    debugPrint('OSRM route $routeIndex distance meters: $distanceMeters');
    debugPrint('OSRM route $routeIndex duration seconds: $durationSeconds');
    debugPrint(
      'Route $routeIndex first point: ${points.isEmpty ? 'none' : points.first}',
    );
    debugPrint(
      'Route $routeIndex last point: ${points.isEmpty ? 'none' : points.last}',
    );

    return _RouteResult(
      points: points,
      distance: distanceMeters / 1000,
      duration: durationSeconds / 60,
      routeIndex: routeIndex,
    );
  }

  double calculateVehicleTime(double distanceKm, String vehicle) {
    double speedKmph;

    switch (vehicle) {
      case 'Car':
        speedKmph = 45;
        break;

      case 'Bike':
        speedKmph = 40;
        break;

      case 'Bus':
        speedKmph = 30;
        break;

      case 'Walk':
        speedKmph = 5;
        break;

      default:
        speedKmph = 40;
    }

    return (distanceKm / speedKmph) * 60;
  }

  Future<List<_OsmRoadSegment>?> getOsmRoadSegmentsForRoute(
    List<LatLng> routePoints,
  ) async {
    if (routePoints.isEmpty) {
      debugPrint(
        'OSM ROAD SEGMENTS UNAVAILABLE: selected route has no geometry.',
      );
      return null;
    }

    final cacheKey = _osmRouteCacheKey(routePoints);

    // 1. In-memory cache hit
    final cached = _osmRoadSegmentsCache[cacheKey];
    if (cached != null) {
      debugPrint(
        'OSM ROAD SEGMENTS CACHE HIT: '
        'reusing ${cached.length} cached OSM segments for route.',
      );
      return cached;
    }

    // 2. Request deduplication: reuse active in-flight request for identical route
    final inFlight = _inFlightOsmRequests[cacheKey];
    if (inFlight != null) {
      debugPrint(
        'OSM ROAD SEGMENTS DEDUPLICATION: '
        'reusing active in-flight Overpass request.',
      );
      return await inFlight;
    }

    // 3. Temporary cooldown if Overpass recently failed with 504 / timeout
    final lastFailure = _lastOverpassFailureTime;
    if (lastFailure != null &&
        DateTime.now().difference(lastFailure) < const Duration(seconds: 20)) {
      debugPrint(
        'OSM road data temporarily paused after recent Overpass timeout; '
        'continuing without OSM segment tags.',
      );
      return null;
    }

    final requestFuture = _loadOsmRoadSegmentsInternal(routePoints);
    _inFlightOsmRequests[cacheKey] = requestFuture;

    try {
      final segments = await requestFuture;
      if (segments != null && segments.isNotEmpty) {
        _osmRoadSegmentsCache[cacheKey] = segments;
      }
      return segments;
    } catch (error) {
      debugPrint('OSM ROAD SEGMENT LOOKUP ERROR: $error');
      return null;
    } finally {
      _inFlightOsmRequests.remove(cacheKey);
    }
  }

  Future<List<_OsmRoadSegment>?> _loadOsmRoadSegmentsInternal(
    List<LatLng> routePoints,
  ) async {
    // 1. Try local backend proxy first (has direct Overpass access + local road segments)
    try {
      final backendUrl = Uri.parse('$_trafficBackendBaseUrl/osm-roads');
      final backendResp = await http
          .post(
            backendUrl,
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode({
              'points': [
                for (final p in routePoints) [p.latitude, p.longitude],
              ],
            }),
          )
          .timeout(const Duration(seconds: 6));

      if (backendResp.statusCode == 200) {
        final decoded = jsonDecode(backendResp.body);
        if (decoded is Map<String, dynamic> && decoded['elements'] is List) {
          final elements = decoded['elements'] as List;
          final backendMatched = <int, _OsmRoadSegment>{};
          for (final el in elements) {
            if (el is! Map<String, dynamic> || el['type'] != 'way') continue;
            final id = el['id'];
            final tags = el['tags'];
            final geometryData = el['geometry'];
            if (id is! num || tags is! Map) continue;

            final geom = <LatLng>[];
            if (geometryData is List) {
              for (final point in geometryData) {
                if (point is Map &&
                    point['lat'] is num &&
                    point['lon'] is num) {
                  geom.add(
                    LatLng(
                      (point['lat'] as num).toDouble(),
                      (point['lon'] as num).toDouble(),
                    ),
                  );
                }
              }
            }
            final highway = tags['highway']?.toString();
            if (highway == null) continue;
            final matchPt = geom.isNotEmpty
                ? _matchedRoadPoint(geom, routePoints, _osmQueryRadiusMeters) ??
                      geom.first
                : routePoints.first;

            final segment = _OsmRoadSegment(
              osmId: id.toInt(),
              name: tags['name']?.toString(),
              highway: highway,
              surface: tags['surface']?.toString(),
              smoothness: tags['smoothness']?.toString(),
              maxspeed: tags['maxspeed']?.toString(),
              lit: tags['lit']?.toString(),
              lanes: tags['lanes']?.toString(),
              sidewalk:
                  (tags['sidewalk'] ??
                          tags['sidewalk:both'] ??
                          tags['sidewalk:left'] ??
                          tags['sidewalk:right'])
                      ?.toString(),
              access: tags['access']?.toString(),
              bridge: tags['bridge']?.toString(),
              tunnel: tags['tunnel']?.toString(),
              bicycle: tags['bicycle']?.toString(),
              foot: tags['foot']?.toString(),
              motorVehicle: tags['motor_vehicle']?.toString(),
              wheelchair: tags['wheelchair']?.toString(),
              tactilePaving: tags['tactile_paving']?.toString(),
              width: tags['width']?.toString(),
              routeMatchPoint: matchPt,
              geometry: geom.length >= 2 ? geom : [matchPt, matchPt],
            );
            backendMatched[segment.osmId] = segment;
          }
          if (backendMatched.isNotEmpty) {
            debugPrint(
              'OSM ROAD SEGMENTS: backend returned ${backendMatched.length} real OSM road ways.',
            );
            return backendMatched.values.toList();
          }
        }
      }
    } catch (_) {}

    final samples = _sampleRouteForOsm(routePoints);
    final chunks = <List<LatLng>>[
      for (var start = 0; start < samples.length; start += _osmSamplesPerQuery)
        samples.skip(start).take(_osmSamplesPerQuery).toList(),
    ];
    final matchedSegments = <int, _OsmRoadSegment>{};
    var successfulQueries = 0;
    var failedQueries = 0;

    debugPrint(
      'OSM ROAD SEGMENT LOOKUP: '
      '${samples.length} route samples in ${chunks.length} bounded queries.',
    );

    for (final chunk in chunks) {
      final query = _roadSegmentQuery(chunk);
      final responseData = await _fetchOverpassChunk(query);
      if (responseData == null) {
        failedQueries++;
        continue;
      }

      successfulQueries++;
      final elements = responseData['elements'];
      if (elements is! List) {
        debugPrint(
          'OSM ROAD SEGMENT QUERY ERROR: response has no elements list.',
        );
        failedQueries++;
        successfulQueries--;
        continue;
      }

      for (final element in elements) {
        if (element is! Map<String, dynamic> || element['type'] != 'way') {
          continue;
        }

        final id = element['id'];
        final tags = element['tags'];
        final geometryData = element['geometry'];
        if (id is! num || tags is! Map || geometryData is! List) continue;

        final geometry = <LatLng>[];
        for (final point in geometryData) {
          if (point is! Map || point['lat'] is! num || point['lon'] is! num) {
            continue;
          }
          geometry.add(
            LatLng(
              (point['lat'] as num).toDouble(),
              (point['lon'] as num).toDouble(),
            ),
          );
        }
        if (geometry.length < 2) continue;

        final highway = tags['highway']?.toString();
        if (highway == null) continue;
        final routeMatchPoint = _matchedRoadPoint(
          geometry,
          chunk,
          _osmQueryRadiusMeters,
        );
        if (routeMatchPoint == null) continue;

        final segment = _OsmRoadSegment(
          osmId: id.toInt(),
          name: tags['name']?.toString(),
          highway: highway,
          surface: tags['surface']?.toString(),
          smoothness: tags['smoothness']?.toString(),
          maxspeed: tags['maxspeed']?.toString(),
          lit: tags['lit']?.toString(),
          lanes: tags['lanes']?.toString(),
          sidewalk:
              (tags['sidewalk'] ??
                      tags['sidewalk:both'] ??
                      tags['sidewalk:left'] ??
                      tags['sidewalk:right'])
                  ?.toString(),
          access: tags['access']?.toString(),
          bridge: tags['bridge']?.toString(),
          tunnel: tags['tunnel']?.toString(),
          bicycle: tags['bicycle']?.toString(),
          foot: tags['foot']?.toString(),
          motorVehicle: tags['motor_vehicle']?.toString(),
          wheelchair: tags['wheelchair']?.toString(),
          tactilePaving: tags['tactile_paving']?.toString(),
          width: tags['width']?.toString(),
          routeMatchPoint: routeMatchPoint,
          geometry: geometry,
        );
        matchedSegments[segment.osmId] = segment;
      }
    }

    if (successfulQueries == 0) {
      debugPrint(
        'OSM road data unavailable for this route; continuing without OSM segment tags.',
      );
      return null;
    }
    if (failedQueries > 0) {
      debugPrint(
        'OSM ROAD SEGMENTS PARTIALLY UNAVAILABLE: '
        '$failedQueries of ${chunks.length} queries failed.',
      );
    }

    final segments = matchedSegments.values.toList();
    if (segments.isEmpty) {
      debugPrint(
        'OSM ROAD SEGMENTS: retrieved data, but no road geometry matched '
        'the selected route samples.',
      );
    } else {
      debugPrint(
        'OSM ROAD SEGMENTS: matched ${segments.length} real OSM road ways.',
      );
    }
    return segments;
  }

  double _segmentGeometryLengthMeters(_OsmRoadSegment segment) {
    if (segment.geometry.length < 2) return 10.0;
    var total = 0.0;
    for (var i = 1; i < segment.geometry.length; i++) {
      total += _distanceBetweenMeters(
        segment.geometry[i - 1],
        segment.geometry[i],
      );
    }
    return total > 0.0 ? total : 10.0;
  }

  _OsmRouteSafetyScores scoreOsmRoadSegments(
    List<_OsmRoadSegment>? segments, {
    required bool includeLighting,
  }) {
    if (segments == null || segments.isEmpty) {
      return const _OsmRouteSafetyScores(
        roadCondition: null,
        lighting: null,
        accessibility: null,
        roadConditionSegments: 0,
        lightingSegments: 0,
        accessibilitySegments: 0,
      );
    }

    var roadConditionWeightedSum = 0.0;
    var roadConditionTotalLength = 0.0;
    var roadConditionCount = 0;

    var lightingWeightedSum = 0.0;
    var lightingTotalLength = 0.0;
    var lightingCount = 0;

    var accessibilityWeightedSum = 0.0;
    var accessibilityTotalLength = 0.0;
    var accessibilityCount = 0;
    var accessibilityPositiveCount = 0;
    var accessibilityNegativeCount = 0;
    var accessibilityNoEvidenceCount = 0;

    for (final segment in segments) {
      final length = _segmentGeometryLengthMeters(segment);

      final roadScore = _roadConditionScoreForSegment(segment);
      if (roadScore != null) {
        roadConditionWeightedSum += roadScore * length;
        roadConditionTotalLength += length;
        roadConditionCount++;
      }

      if (includeLighting) {
        final lightScore = _lightingScoreForSegment(segment);
        if (lightScore != null) {
          lightingWeightedSum += lightScore * length;
          lightingTotalLength += length;
          lightingCount++;
        }
      }

      final accessScore = _accessibilityScoreForSegment(segment);
      if (accessScore != null) {
        accessibilityWeightedSum += accessScore * length;
        accessibilityTotalLength += length;
        accessibilityCount++;
        if (accessScore >= 50.0) {
          accessibilityPositiveCount++;
        } else {
          accessibilityNegativeCount++;
        }
      } else {
        accessibilityNoEvidenceCount++;
      }
    }

    final roadCondition = roadConditionTotalLength > 0
        ? roadConditionWeightedSum / roadConditionTotalLength
        : null;

    final lighting = (includeLighting && lightingTotalLength > 0)
        ? lightingWeightedSum / lightingTotalLength
        : null;

    final accessibility = accessibilityTotalLength > 0
        ? accessibilityWeightedSum / accessibilityTotalLength
        : null;

    return _OsmRouteSafetyScores(
      roadCondition: roadCondition,
      lighting: lighting,
      accessibility: accessibility,
      roadConditionSegments: roadConditionCount,
      lightingSegments: lightingCount,
      accessibilitySegments: accessibilityCount,
      accessibilityPositiveSegments: accessibilityPositiveCount,
      accessibilityNegativeSegments: accessibilityNegativeCount,
      accessibilityNoEvidenceSegments: accessibilityNoEvidenceCount,
    );
  }

  double? _roadConditionScoreForSegment(_OsmRoadSegment segment) {
    final observedValues = <double>[];

    final surface = segment.surface?.toLowerCase().trim();
    if (surface != null && surface.isNotEmpty) {
      switch (surface) {
        case 'asphalt' ||
            'bitumen' ||
            'tarmac' ||
            'concrete' ||
            'paved' ||
            'cement':
          observedValues.add(100.0);
          break;
        case 'paving_stones' || 'sett':
          observedValues.add(75.0);
          break;
        case 'cobblestone' || 'brick' || 'metal' || 'wood':
          observedValues.add(60.0);
          break;
        case 'compacted' || 'fine_gravel':
          observedValues.add(40.0);
          break;
        case 'unpaved' || 'gravel' || 'pebblestone':
          observedValues.add(25.0);
          break;
        case 'dirt' || 'earth' || 'ground':
          observedValues.add(15.0);
          break;
        case 'mud' || 'sand' || 'grass':
          observedValues.add(0.0);
          break;
      }
    }

    const smoothnessLevels = [
      'excellent',
      'good',
      'intermediate',
      'bad',
      'very_bad',
      'horrible',
      'very_horrible',
      'impassable',
    ];
    final smoothness = segment.smoothness?.toLowerCase().trim();
    if (smoothness != null && smoothness.isNotEmpty) {
      final index = smoothnessLevels.indexOf(smoothness);
      if (index >= 0) {
        observedValues.add(
          (1.0 - (index / (smoothnessLevels.length - 1))) * 100.0,
        );
      }
    }

    if (observedValues.isEmpty) return null;
    return observedValues.reduce((sum, value) => sum + value) /
        observedValues.length;
  }

  double? _lightingScoreForSegment(_OsmRoadSegment segment) {
    return switch (segment.lit?.toLowerCase().trim()) {
      'yes' => 100.0,
      'no' => 0.0,
      _ => null,
    };
  }

  double? _accessibilityScoreForSegment(_OsmRoadSegment segment) {
    final observed = <double>[];

    if (segment.wheelchair != null) {
      switch (segment.wheelchair!.toLowerCase().trim()) {
        case 'yes' || 'designated':
          observed.add(100.0);
          break;
        case 'limited':
          observed.add(60.0);
          break;
        case 'no':
          // Explicit wheelchair=no represents poor accessibility, not 0
          observed.add(15.0);
          break;
      }
    }

    if (segment.sidewalk != null) {
      switch (segment.sidewalk!.toLowerCase().trim()) {
        case 'yes' ||
            'both' ||
            'separate' ||
            'left:separate' ||
            'right:separate':
          observed.add(100.0);
          break;
        case 'left' || 'right' || 'shared':
          observed.add(75.0);
          break;
        case 'no' || 'none':
          // Explicit absence of sidewalk represents poor pedestrian infrastructure, not complete 0
          observed.add(20.0);
          break;
      }
    }

    if (segment.tactilePaving != null) {
      switch (segment.tactilePaving!.toLowerCase().trim()) {
        case 'yes':
          observed.add(100.0);
          break;
        case 'incorrect' || 'primitive':
          observed.add(40.0);
          break;
        case 'no':
          observed.add(25.0);
          break;
      }
    }

    if (segment.width != null) {
      final cleaned = segment.width!.toLowerCase().replaceAll('m', '').trim();
      final widthVal = double.tryParse(cleaned);
      if (widthVal != null) {
        if (widthVal >= 1.8) {
          observed.add(100.0);
        } else if (widthVal >= 1.2) {
          observed.add(80.0);
        } else if (widthVal >= 0.9) {
          observed.add(60.0);
        } else {
          observed.add(30.0);
        }
      }
    }

    if (segment.access != null) {
      switch (segment.access!.toLowerCase().trim()) {
        case 'yes' || 'permissive' || 'public':
          observed.add(100.0);
          break;
        case 'destination' || 'customers':
          observed.add(70.0);
          break;
        case 'private' || 'no':
          observed.add(10.0);
          break;
      }
    }

    if (segment.foot != null) {
      switch (segment.foot!.toLowerCase().trim()) {
        case 'yes' || 'designated' || 'permissive':
          observed.add(100.0);
          break;
        case 'use_sidepath':
          observed.add(85.0);
          break;
        case 'no' || 'private':
          observed.add(10.0);
          break;
      }
    }

    if (segment.bicycle != null) {
      switch (segment.bicycle!.toLowerCase().trim()) {
        case 'yes' || 'designated' || 'permissive':
          observed.add(90.0);
          break;
        case 'no':
          observed.add(25.0);
          break;
      }
    }

    if (observed.isEmpty) return null;
    return observed.reduce((sum, value) => sum + value) / observed.length;
  }

