  String _formatTripDate(DateTime dt) {
    final now = DateTime.now();
    final diff = now.difference(dt);
    if (diff.inMinutes < 1) return 'Just now';
    if (diff.inMinutes < 60) return '${diff.inMinutes}m ago';
    if (diff.inHours < 24) return '${diff.inHours}h ago';
    if (diff.inDays < 7) return '${diff.inDays}d ago';

    const months = [
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];
    return '${months[dt.month - 1]} ${dt.day}, ${dt.year}';
  }

  IconData _vehicleIcon(String vehicle) {
    return switch (vehicle.toLowerCase()) {
      'bike' => Icons.two_wheeler_rounded,
      'bus' => Icons.directions_bus_rounded,
      'walk' => Icons.directions_walk_rounded,
      _ => Icons.directions_car_rounded,
    };
  }

  Future<void> _loadFavouriteRoutes() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final rawList = prefs.getStringList(_favouriteRoutesStorageKey);
      if (rawList != null) {
        final List<_FavouriteRoute> loaded = [];
        for (final item in rawList) {
          try {
            final decoded = jsonDecode(item);
            if (decoded is Map<String, dynamic>) {
              loaded.add(_FavouriteRoute.fromJson(decoded));
            }
          } catch (e) {
            debugPrint('Error decoding favourite route: $e');
          }
        }
        if (mounted) {
          setState(() {
            _favouriteRoutes = loaded;
            _favouriteRoutesLoaded = true;
          });
        }
        return;
      }
    } catch (e) {
      debugPrint('Error loading favourite routes from SharedPreferences: $e');
    }
    if (mounted) {
      setState(() {
        _favouriteRoutesLoaded = true;
      });
    }
  }

  Future<void> _persistFavouriteRoutes() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final stringList = _favouriteRoutes
          .map((f) => jsonEncode(f.toJson()))
          .toList();
      await prefs.setStringList(_favouriteRoutesStorageKey, stringList);
    } catch (e) {
      debugPrint('Error saving favourite routes to SharedPreferences: $e');
    }
  }

  bool _isCurrentRouteFavourite() {
    final from = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : currentFrom.trim();
    final to = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : currentTo.trim();
    if (from.isEmpty || to.isEmpty) return false;
    return _favouriteRoutes.any(
      (f) =>
          f.origin.toLowerCase() == from.toLowerCase() &&
          f.destination.toLowerCase() == to.toLowerCase(),
    );
  }

  Future<void> _addCurrentRouteToFavourites() async {
    final from = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : currentFrom.trim();
    final to = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : currentTo.trim();

    if (from.isEmpty || to.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('No active route to favourite'),
          backgroundColor: _NeonTheme.dangerRed,
        ),
      );
      return;
    }

    if (_isCurrentRouteFavourite()) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Route already in Favourites'),
            backgroundColor: _NeonTheme.electricBlue,
          ),
        );
      }
      return;
    }

    final fav = _FavouriteRoute(
      id: '${DateTime.now().millisecondsSinceEpoch}',
      origin: from,
      destination: to,
      vehicleMode: currentVehicle,
      travelTimeMode: currentTravelTime,
      createdAt: DateTime.now(),
      routeLabel: '$from → $to',
    );

    setState(() {
      _favouriteRoutes.insert(0, fav);
    });

    await _persistFavouriteRoutes();

    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('✓ Route added to Favourites'),
          backgroundColor: _NeonTheme.safeGreen,
        ),
      );
    }
  }

