  List<_Facility> get _displayedFacilities {
    if (_selectedFacilityGroups.isEmpty) return const [];
    final selected = _selectedFacilityGroups;
    final matched = <String, _Facility>{};
    for (final f in facilities) {
      for (final g in selected) {
        if (g.matches(f)) {
          matched[f.id] = f;
          break;
        }
      }
    }
    final list = matched.values.toList();
    if (routePoints.isNotEmpty) {
      list.sort((a, b) {
        final pa = _routeProgressMeters(LatLng(a.lat, a.lon), routePoints) ??
            double.infinity;
        final pb = _routeProgressMeters(LatLng(b.lat, b.lon), routePoints) ??
            double.infinity;
        return pa.compareTo(pb);
      });
    }
    return list;
  }

  void _syncFacilityGroupsFromCategories() {
    _selectedFacilityGroups.clear();
    for (final catLabel in _selectedFacilityCategories) {
      final g = _groupForCategoryLabel(catLabel);
      if (g != null) _selectedFacilityGroups.add(g);
    }
  }

  void _syncCategoriesFromFacilityGroups() {
    _selectedFacilityCategories.clear();
    for (final group in _selectedFacilityGroups) {
      _selectedFacilityCategories.addAll(_categoryLabelsForGroup(group));
    }
  }

  static _RouteFacilityGroup? _groupForCategoryLabel(String label) {
    return switch (label) {
      'Hospitals' => _RouteFacilityGroup.hospitals,
      'Police' => _RouteFacilityGroup.police,
      'Petrol' || 'EV' => _RouteFacilityGroup.petrolEv,
      'Pharmacies' => _RouteFacilityGroup.pharmacies,
      'Restaurants' => _RouteFacilityGroup.restaurants,
      'ATM' || 'Hotels' || 'Parking' || 'Restrooms' => _RouteFacilityGroup.other,
      _ => _RouteFacilityGroup.other,
    };
  }

  static List<String> _categoryLabelsForGroup(_RouteFacilityGroup group) {
    return switch (group) {
      _RouteFacilityGroup.hospitals => ['Hospitals'],
      _RouteFacilityGroup.police => ['Police'],
      _RouteFacilityGroup.petrolEv => ['Petrol', 'EV'],
      _RouteFacilityGroup.pharmacies => ['Pharmacies'],
      _RouteFacilityGroup.restaurants => ['Restaurants'],
      _RouteFacilityGroup.other => ['ATM', 'Hotels', 'Parking', 'Restrooms'],
      _RouteFacilityGroup.all => [
        'Hospitals',
        'Police',
        'Petrol',
        'EV',
        'Pharmacies',
        'Restaurants',
        'ATM',
        'Hotels',
        'Parking',
        'Restrooms',
      ],
    };
  }

  @override
  void initState() {
    super.initState();
    _heroAnimController = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 2),
    )..repeat(reverse: true);
    currentFrom = widget.from;
    currentTo = widget.to;
    currentPreference = widget.preference;
    currentTravelTime = widget.travelTime.isNotEmpty ? widget.travelTime : 'Now';
    currentVehicle = widget.vehicle.isNotEmpty ? widget.vehicle : 'Car';
    currentMainPriority = widget.mainPriority;
    currentFromIsCurrentLocation = widget.fromIsCurrentLocation;
    fromController.text = currentFrom;
    toController.text = currentTo;
    _selectedFacilityCategories.clear();
    _selectedFacilityGroups.clear();
    if (widget.optionalFacilities.isNotEmpty) {
      _selectedFacilityCategories.addAll(widget.optionalFacilities);
      _syncFacilityGroupsFromCategories();
    }
    _hasSearchedRoute = true;
    loading = false;
    unawaited(_loadSavedTrips());
    unawaited(_loadFavouriteRoutes());
    unawaited(_loadPersonalSafetyProfile());
    final isTestEnvironment =
        WidgetsBinding.instance.runtimeType.toString().contains('Test');
    final hasInitialRoute = (currentFromIsCurrentLocation || currentFrom.trim().isNotEmpty) &&
        currentTo.trim().isNotEmpty;
    if (!isTestEnvironment && hasInitialRoute) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && routePoints.isEmpty) {
          unawaited(loadRoute());
        }
      });
    }
  }

  Future<void> _toggleFacilityCategory(
    _FacilityCategory category,
    bool selected,
  ) async {
    setState(() {
      if (selected) {
        _selectedFacilityCategories.add(category.selectorLabel);
      } else {
        _selectedFacilityCategories.remove(category.selectorLabel);
      }
      _syncFacilityGroupsFromCategories();
      _facilitySearchGeneration++;
      _isLoadingFacilities = false;
      _facilitiesUnavailable = false;
      _facilityResultsIncomplete = false;
      _facilityFailedCategoryIds.clear();
      if (!selected ||
          !_selectedFacilityCategories.contains(
            _facilityCategoryForId(_selectedFacility?.categoryId)
                ?.selectorLabel,
          )) {
        _selectedFacility = null;
      }
    });

    if (_selectedFacilityCategories.isEmpty) return;
    final route =
        availableRoutes.isNotEmpty &&
            selectedRouteIndex < availableRoutes.length
        ? availableRoutes[selectedRouteIndex]
        : routeEvaluations[selectedRouteIndex]?.route;
    if (route == null) return;
    unawaited(_loadFacilitiesForRoute(route));
  }

  double? _facilityRouteDistanceMeters(_Facility facility) {
    if (routePoints.isEmpty) return null;
    final position = currentPosition;
    final referenceLocation = position != null
        ? LatLng(position.latitude, position.longitude)
        : routePoints.first;
    final referenceProgress =
        _routeProgressMeters(referenceLocation, routePoints) ?? 0.0;
    final facilityLocation = LatLng(facility.lat, facility.lon);
    final facilityProgress =
        _routeProgressMeters(facilityLocation, routePoints);
    if (facilityProgress == null) {
      return Geolocator.distanceBetween(
        referenceLocation.latitude,
        referenceLocation.longitude,
        facility.lat,
        facility.lon,
      );
    }
    return (facilityProgress - referenceProgress).abs();
  }

  bool _facilityIsAhead(_Facility facility) {
    if (routePoints.isEmpty) return true;
    final position = currentPosition;
    final referenceLocation = position != null
        ? LatLng(position.latitude, position.longitude)
        : routePoints.first;
    final referenceProgress =
        _routeProgressMeters(referenceLocation, routePoints) ?? 0.0;
    final facilityLocation = LatLng(facility.lat, facility.lon);
    final facilityProgress =
        _routeProgressMeters(facilityLocation, routePoints);
    if (facilityProgress == null) return true;
    return facilityProgress >= referenceProgress;
  }

  String _formatFacilityRouteDistance(_Facility facility) {
    final d = _facilityRouteDistanceMeters(facility);
    if (d == null) return 'Distance unavailable';
    final isAhead = _facilityIsAhead(facility);
    final distStr = d < 1000
        ? '${d.round()} m'
        : '${(d / 1000).toStringAsFixed(1)} km';
    return currentPosition != null
        ? '$distStr ${isAhead ? 'ahead' : 'passed'}'
        : '$distStr along route';
  }

  void _selectFacilityGroup(_RouteFacilityGroup group) {
    setState(() {
      if (group == _RouteFacilityGroup.all) {
        if (_selectedFacilityGroups.containsAll(_specificFacilityGroups)) {
          _selectedFacilityGroups.clear();
        } else {
          _selectedFacilityGroups.clear();
          _selectedFacilityGroups.addAll(_specificFacilityGroups);
        }
      } else {
        if (_selectedFacilityGroups.length == 1 &&
            _selectedFacilityGroups.contains(group)) {
          _selectedFacilityGroups.clear();
        } else {
          _selectedFacilityGroups.clear();
          _selectedFacilityGroups.add(group);
        }
      }
      _syncCategoriesFromFacilityGroups();
      _selectedFacility = null;
    });
    for (final g in _selectedFacilityGroups) {
      unawaited(_loadFacilitiesForGroup(g));
    }
  }

  Future<void> _loadFacilitiesForGroup(_RouteFacilityGroup group) async {
    final route =
        availableRoutes.isNotEmpty &&
            selectedRouteIndex < availableRoutes.length
        ? availableRoutes[selectedRouteIndex]
        : routeEvaluations[selectedRouteIndex]?.route;
    if (route == null || route.points.isEmpty) return;

    final categories = group.getCategories(_facilityCategories);
    if (categories.isEmpty) return;

    // Check in-memory cache first for all categories in this group
    final cachedFacilities = <_Facility>[];
    final missingCategories = <_FacilityCategory>[];

    for (final category in categories) {
      final cacheKey = _facilityCacheKey(route, category.id);
      final cached = _globalFacilityCache[cacheKey];
      if (cached != null) {
        cachedFacilities.addAll(cached);
      } else {
        missingCategories.add(category);
      }
    }

    if (missingCategories.isEmpty) {
      final byId = <String, _Facility>{for (final f in facilities) f.id: f};
      for (final f in cachedFacilities) {
        byId[f.id] = f;
      }
      setState(() {
        facilities = byId.values.toList(growable: false);
        _isLoadingFacilities = false;
        _facilitiesUnavailable = false;
        _facilityResultsIncomplete = false;
      });
      return;
    }

    if (_inFlightFacilityGroups.contains(group)) {
      return; // Deduplicate concurrent identical requests
    }
    _inFlightFacilityGroups.add(group);

    final generation = ++_facilitySearchGeneration;
    final currentRouteIndex = route.routeIndex;

    setState(() {
      _isLoadingFacilities = true;
      _facilitiesUnavailable = false;
      _facilityResultsIncomplete = false;
      _facilityFailedCategoryIds.clear();
    });

    try {
      final results = await service._getFacilitiesForRoute(
        route.points,
        missingCategories,
      );

      if (!mounted ||
          generation != _facilitySearchGeneration ||
          selectedRouteIndex != currentRouteIndex) {
        return; // Stale request protection
      }

      if (results.failedChunks > 0 && results.successfulChunks == 0) {
        _facilityFailedCategoryIds.addAll(missingCategories.map((c) => c.id));
        setState(() {
          _isLoadingFacilities = false;
          _facilitiesUnavailable = true;
          _facilityResultsIncomplete = false;
        });
        return;
      }

      for (final category in missingCategories) {
        final categoryFacilities = results.facilities
            .where((facility) => facility.categoryId == category.id)
            .toList(growable: false);
        final cacheKey = _facilityCacheKey(route, category.id);
        _globalFacilityCache[cacheKey] = categoryFacilities;
      }

      final allForRoute = <_Facility>[...facilities];
      for (final category in missingCategories) {
        final cacheKey = _facilityCacheKey(route, category.id);
        final list = _globalFacilityCache[cacheKey];
        if (list != null) allForRoute.addAll(list);
      }

      final byId = <String, _Facility>{};
      for (final f in allForRoute) {
        byId[f.id] = f;
      }

      setState(() {
        facilities = byId.values.toList(growable: false);
        _isLoadingFacilities = false;
        _facilitiesUnavailable = false;
        _facilityResultsIncomplete = results.failedChunks > 0;
      });
    } catch (e) {
      debugPrint('FACILITY LOAD ERROR: $e');
      if (!mounted ||
          generation != _facilitySearchGeneration ||
          selectedRouteIndex != currentRouteIndex) {
        return;
      }
      setState(() {
        _isLoadingFacilities = false;
        _facilitiesUnavailable = true;
      });
    } finally {
      _inFlightFacilityGroups.remove(group);
    }
  }

  Future<void> _loadFacilitiesForRoute(_RouteResult route) async {
    for (final g in _selectedFacilityGroups) {
      await _loadFacilitiesForGroup(g);
    }
  }

  String _facilityCacheKey(_RouteResult route, String categoryId) {
    final fromName = widget.fromIsCurrentLocation
        ? (route.points.isNotEmpty
              ? '${route.points.first.latitude.toStringAsFixed(3)},${route.points.first.longitude.toStringAsFixed(3)}'
              : 'curr')
        : widget.from.trim().toLowerCase();
    final toName = widget.to.trim().toLowerCase();
    return '$fromName→$toName#${route.routeIndex}|$categoryId';
  }

  _FacilityCategory? _facilityCategoryForId(String? id) {
    if (id == 'fuel') id = 'petrol';
    for (final category in _facilityCategories) {
      if (category.id == id) return category;
    }
    return null;
  }

