    final rawId = facility.categoryId.trim().toLowerCase();
    if (rawId == 'hospital' ||
        rawId == 'clinic' ||
        rawId == 'doctors' ||
        rawId == 'health_post') {
      return const _FacilityCategory(
        id: 'hospital',
        label: 'Hospital',
        selectorLabel: 'Hospitals',
        statusLabel: 'Hospitals',
        noResultsLabel: 'hospitals',
        icon: Icons.local_hospital_rounded,
        color: Color(0xffE11D48),
        osmTag: 'amenity',
        osmValue: 'hospital',
      );
    }
    if (rawId == 'police') {
      return const _FacilityCategory(
        id: 'police',
        label: 'Police',
        selectorLabel: 'Police',
        statusLabel: 'Police stations',
        noResultsLabel: 'police stations',
        icon: Icons.shield_rounded,
        color: Color(0xff2563EB),
        osmTag: 'amenity',
        osmValue: 'police',
      );
    }
    if (rawId == 'petrol' || rawId == 'fuel' || rawId == 'petrol_pump') {
      return const _FacilityCategory(
        id: 'petrol',
        label: 'Petrol Station',
        selectorLabel: 'Petrol',
        statusLabel: 'Petrol stations',
        noResultsLabel: 'petrol stations',
        icon: Icons.local_gas_station_rounded,
        color: Color(0xffEA580C),
        osmTag: 'amenity',
        osmValue: 'fuel',
      );
    }
    if (rawId == 'ev' || rawId == 'charging_station') {
      return const _FacilityCategory(
        id: 'ev',
        label: 'EV Charging',
        selectorLabel: 'EV',
        statusLabel: 'EV chargers',
        noResultsLabel: 'EV charging stations',
        icon: Icons.ev_station_rounded,
        color: Color(0xff06B6D4),
        osmTag: 'amenity',
        osmValue: 'charging_station',
      );
    }
    if (rawId == 'pharmacy' || rawId == 'chemist') {
      return const _FacilityCategory(
        id: 'pharmacy',
        label: 'Pharmacy',
        selectorLabel: 'Pharmacies',
        statusLabel: 'Pharmacies',
        noResultsLabel: 'pharmacies',
        icon: Icons.medication_rounded,
        color: Color(0xff10B981),
        osmTag: 'amenity',
        osmValue: 'pharmacy',
      );
    }
    if (rawId == 'restaurant' ||
        rawId == 'cafe' ||
        rawId == 'fast_food' ||
        rawId == 'food_court') {
      return const _FacilityCategory(
        id: 'restaurant',
        label: 'Restaurant',
        selectorLabel: 'Restaurants',
        statusLabel: 'Restaurants',
        noResultsLabel: 'restaurants',
        icon: Icons.restaurant_rounded,
        color: Color(0xffEA580C),
        osmTag: 'amenity',
        osmValue: 'restaurant',
      );
    }
    final known = _facilityCategoryForId(rawId);
    if (known != null) return known;

    return const _FacilityCategory(
      id: 'other',
