  Future<void> updateBlackspotProximity(Position position) async {
    final data = await service.checkBlackspotProximity(
      position.latitude,
      position.longitude,
    );

    if (data != null && mounted) {
      setState(() {
        isNearBlackspot = data['is_near_blackspot'] == true;
        final nearby = data['nearby_blackspots'] as List<dynamic>?;
        if (nearby != null && nearby.isNotEmpty) {
          blackspotDetails = nearby.first as Map<String, dynamic>;
          blackspotDistanceMeters =
              (blackspotDetails!['distance_meters'] as num?)?.toDouble();
        } else {
          final nearest = data['nearest_blackspot'] as Map<String, dynamic>?;
          blackspotDetails = nearest;
          blackspotDistanceMeters = (nearest?['distance_meters'] as num?)
              ?.toDouble();
        }
      });
    }
  }

  Future<void> _startNavigation() async {
    if (_navigationActive || _navigationStartInProgress) return;
    setState(() {
      _navigationStartInProgress = true;
      _navigationError = null;
      _routeProximityStatus = null;
    });

    try {
      if (!await Geolocator.isLocationServiceEnabled()) {
        throw const _NavigationLocationException(
          'Location services are disabled. Enable location services and try again.',
        );
      }

      var permission = await Geolocator.checkPermission();
      if (permission == LocationPermission.denied) {
        permission = await Geolocator.requestPermission();
      }
      if (permission == LocationPermission.denied) {
        throw const _NavigationLocationException(
          'Location permission was denied. Allow location access to start navigation.',
        );
      }
      if (permission == LocationPermission.deniedForever) {
        throw const _NavigationLocationException(
          'Location permission is blocked. Enable it in your device or browser settings.',
        );
      }

      final position = await Geolocator.getCurrentPosition(
        locationSettings: const LocationSettings(
          accuracy: LocationAccuracy.high,
        ),
      );
      if (!mounted) return;

      setState(() {
        _navigationActive = true;
        _navigationStartInProgress = false;
        _followMe = true;
        currentPosition = position;
        _destinationStage = _DestinationProximityStage.none;
        _destinationAlertText = null;
        _lastSpokenDestinationStage = _DestinationProximityStage.none;
        _lastSpokenAlert = null;
        _lastSpokenTime = null;
        _spokenFacilityKey = null;
        _offRouteAlertSpoken = false;
        _updateRouteProximity(position);
        _updateNavigationProgressAndAlerts(position);
        _updateSelectedFacilityProgress(position);
      });
      _centerMapOnPosition(position);
      positionSubscription =
          Geolocator.getPositionStream(
            locationSettings: const LocationSettings(
              accuracy: LocationAccuracy.high,
              distanceFilter: 5,
            ),
          ).listen(
            _handlePositionUpdate,
            onError: _handlePositionStreamError,
            cancelOnError: true,
          );
    } on _NavigationLocationException catch (error) {
      if (!mounted) return;
      setState(() {
        _navigationStartInProgress = false;
        _navigationError = error.message;
      });
    } on LocationServiceDisabledException {
      _handleNavigationStartError(
        'Location services are disabled. Enable location services and try again.',
      );
    } on PermissionDeniedException {
      _handleNavigationStartError(
        'Location permission was denied. Allow location access to start navigation.',
      );
    } catch (error) {
      _navigationActive = false;
      _followMe = false;
      positionSubscription?.cancel();
      positionSubscription = null;
      _handleNavigationStartError(
        'Unable to get your current location. Check GPS/browser location settings and try again.',
      );
      debugPrint('NAVIGATION LOCATION ERROR: $error');
    }
  }

  void _handleNavigationStartError(String message) {
    if (!mounted) return;
    setState(() {
      _navigationStartInProgress = false;
      _navigationError = message;
    });
  }

void _handlePositionUpdate(Position position) {
    if (!mounted) return;
    setState(() {
      currentPosition = position;
      _navigationError = null;
      _updateRouteProximity(position);
      _updateNavigationProgressAndAlerts(position);
      _updateSelectedFacilityProgress(position);
    });
    if (_followMe) _centerMapOnPosition(position);
    _evaluateContextualRefreshIfNeeded(position);
  }

  Future<void> _evaluateContextualRefreshIfNeeded(Position position) async {
    if (!mounted || _isContextRefreshing || routePoints.isEmpty) return;
    final currentEval = routeEvaluations[selectedRouteIndex];
    if (currentEval == null) return;

    final now = DateTime.now();
    final lastRefresh = _lastContextRefreshTime;
    // Enforce throttle: at least 45 seconds between dynamic context refreshes
    if (lastRefresh != null && now.difference(lastRefresh).inSeconds < 45) {
      return;
    }

    final currentLoc = LatLng(position.latitude, position.longitude);
    final lastLoc = _lastEvaluatedContextPosition;

    // Trigger 1: Distance moved along route > 1000m
    final double distMovedMeters = lastLoc != null
        ? service._distanceBetweenMeters(currentLoc, lastLoc)
        : double.infinity;
    final bool significantMove = distMovedMeters >= 1000.0;

    // Trigger 2: Weather cache expired (> 15 minutes old)
    final bool weatherExpired = currentEval.weather != null &&
        now.difference(currentEval.weather!.fetchedAt).inMinutes >= 15;

    // Trigger 3: Off-route detection change
    final bool offRouteTrigger = _isOffRoute &&
        _distanceFromRouteMeters != null &&
        _distanceFromRouteMeters! > 150.0;

    // Only proceed if at least one trigger condition is satisfied
    if (!significantMove && !weatherExpired && !offRouteTrigger) {
      return;
    }

    _isContextRefreshing = true;
    _lastContextRefreshTime = now;
    _lastEvaluatedContextPosition = currentLoc;

    try {
      // 1. Weather: if expired or never fetched, fetch for current position
      _WeatherData? updatedWeather = currentEval.weather;
      if (weatherExpired || updatedWeather == null) {
        updatedWeather = await service.getWeather(
          position.latitude,
          position.longitude,
        );
      }

      // 2. Traffic: unconfigured or existing assessment
      final updatedTraffic = currentEval.traffic;

      // 3. Blackspots: re-evaluate blackspot proximity against verified dataset with cached segments
      final updatedBlackspots = await service.assessRouteBlackspots(
        routePoints,
        currentEval.roadSegments,
      );

      // 4. OSM road scores (reuse cached segments, zero redundant Overpass network queries)
      final roadScores = service.scoreOsmRoadSegments(
        currentEval.roadSegments,
        includeLighting: _requiresLightingTravel(currentTravelTime),
      );

      final weatherScore = _calculateWeatherSafetyScore(updatedWeather);
      final trafficScore = _calculateTrafficSafetyScore(updatedTraffic);

      // 5. Re-run calculatePersonalizedSafetyScore with updated context
      final updatedSafety = calculatePersonalizedSafetyScore(
        accidentScore: updatedBlackspots.clearSampleScore,
        roadConditionScore: roadScores.roadCondition,
        trafficScore: trafficScore,
        weatherScore: weatherScore,
        lightingScore: roadScores.lighting,
        accessibilityScore: roadScores.accessibility,
        accidentSegmentsWithMatches: updatedBlackspots.detectedBlackspots ?? 0,
        accidentVerifiedRecordCount: updatedBlackspots.verifiedRecordCount,
        accidentUnavailableReason: updatedBlackspots.unavailableReason,
        roadConditionSegments: roadScores.roadConditionSegments,
        lightingSegments: roadScores.lightingSegments,
        accessibilitySegments: roadScores.accessibilitySegments,
        traffic: updatedTraffic,
        weather: updatedWeather,
        priority: _effectivePriority,
      );

      if (!mounted) return;

      setState(() {
        final refreshedEval = _RouteEvaluation(
          route: currentEval.route,
          roadSegments: currentEval.roadSegments,
          safety: updatedSafety,
          weather: updatedWeather,
          blackspots: updatedBlackspots,
          traffic: updatedTraffic,
        );
        routeEvaluations[selectedRouteIndex] = refreshedEval;
        personalizedSafetyResult = updatedSafety;
        safetyScore = updatedSafety.score;
        weather = updatedWeather;
        recommendationReasons = _buildRecommendationReasons(refreshedEval);
      });
    } catch (e) {
      debugPrint('Dynamic context refresh non-fatal error: $e');
    } finally {
      _isContextRefreshing = false;
    }
  }

  void _handlePositionStreamError(Object error) {
    if (!mounted) return;
    setState(() {
      _navigationActive = false;
      _followMe = false;
      _distanceFromRouteMeters = null;
      _routeProximityStatus = null;
      _destinationStage = _DestinationProximityStage.none;
      _destinationAlertText = null;
      _lastSpokenDestinationStage = _DestinationProximityStage.none;
      _lastSpokenAlert = null;
      _lastSpokenTime = null;
      _spokenFacilityKey = null;
      _offRouteAlertSpoken = false;
      _navigationError =
          'Live location updates stopped. Check GPS/browser location settings.';
    });
    WebSpeechHelper.stop();
    debugPrint('NAVIGATION LOCATION STREAM ERROR: $error');
  }

  _FacilityAheadInfo? _getNextFacilityAhead() {
    final catId = _activeFacilityAlertCategory ??
        _selectedFacility?.categoryId ??
        (_selectedFacilityCategories.isNotEmpty
            ? _facilityCategories
                .firstWhere(
                  (c) => _selectedFacilityCategories.contains(c.selectorLabel),
                  orElse: () => _facilityCategories.first,
                )
                .id
            : null);

    if (catId == null || routePoints.isEmpty) return null;
    final category = _facilityCategoryForId(catId);
    if (category == null) return null;

    final pos = currentPosition;
    final userLocation = pos != null
        ? LatLng(pos.latitude, pos.longitude)
        : routePoints.first;

    final userProgress = _routeProgressMeters(userLocation, routePoints) ?? 0.0;
    final matches = <_FacilityProgressMatch>[];

    for (final facility in facilities) {
      if (facility.categoryId != catId) continue;
      final facilityLocation = LatLng(facility.lat, facility.lon);

      final perpDistance = _distanceFromCoordinatesToRoute(
        facilityLocation,
        routePoints,
      );
      if (perpDistance == null || perpDistance > 650.0) continue;

      final progress = _routeProgressMeters(facilityLocation, routePoints);
      if (progress == null) continue;

      if (progress > userProgress) {
        matches.add(
          _FacilityProgressMatch(
            facility: facility,
            remainingMeters: progress - userProgress,
          ),
        );
      }
    }

    if (matches.isEmpty) return null;
    matches.sort((a, b) => a.remainingMeters.compareTo(b.remainingMeters));
    final closest = matches.first;
    final mins = (closest.remainingMeters / 666.6).round();

    return _FacilityAheadInfo(
      facility: closest.facility,
      category: category,
      distanceMeters: closest.remainingMeters,
      estimatedMinutes: mins.clamp(1, 120),
      isClose: closest.remainingMeters <= 2000,
      isReached: closest.remainingMeters <= 150,
    );
  }


  void _updateRouteProximity(Position position) {
    _distanceFromRouteMeters = _distanceToRouteMeters(position, routePoints);
    if (_distanceFromRouteMeters == null) {
      _routeProximityStatus = 'Route position unavailable';
    } else if (!position.accuracy.isFinite ||
        position.accuracy > _maximumUsableGpsAccuracyMeters) {
      _routeProximityStatus =
          'GPS accuracy too low to determine route position';
    } else if (_distanceFromRouteMeters! <= _onRouteThresholdMeters) {
      _routeProximityStatus =
          selectedRouteIndex == routeRecommendation.recommendedRouteIndex
          ? 'On recommended route'
          : 'On selected route';
    } else {
      _routeProximityStatus = 'You are off route';
    }
  }

  double? _distanceToRouteMeters(Position position, List<LatLng> points) {
    return _distanceFromCoordinatesToRoute(
      LatLng(position.latitude, position.longitude),
      points,
    );
  }

  double? _distanceFromCoordinatesToRoute(
    LatLng location,
    List<LatLng> points,
  ) {
    if (points.isEmpty ||
        !location.latitude.isFinite ||
        !location.longitude.isFinite ||
        points.any(
          (point) => !point.latitude.isFinite || !point.longitude.isFinite,
        )) {
      return null;
    }
    final latitudeScale = 110540.0;
    final longitudeScale =
        111320.0 * math.cos(location.latitude * math.pi / 180);
    double toX(LatLng point) =>
        (point.longitude - location.longitude) * longitudeScale;
    double toY(LatLng point) =>
        (point.latitude - location.latitude) * latitudeScale;

    if (points.length == 1) {
      return math.sqrt(
        math.pow(toX(points.first), 2) + math.pow(toY(points.first), 2),
      );
    }

    var nearestDistanceSquared = double.infinity;
    for (var index = 0; index < points.length - 1; index++) {
      final first = points[index];
      final second = points[index + 1];
      final firstX = toX(first);
      final firstY = toY(first);
      final segmentX = toX(second) - firstX;
      final segmentY = toY(second) - firstY;
      final lengthSquared = segmentX * segmentX + segmentY * segmentY;
      final fraction = lengthSquared == 0
          ? 0.0
          : (-(firstX * segmentX + firstY * segmentY) / lengthSquared)
                .clamp(0.0, 1.0)
                .toDouble();
      final nearestX = firstX + fraction * segmentX;
      final nearestY = firstY + fraction * segmentY;
      final distanceSquared = nearestX * nearestX + nearestY * nearestY;
      if (distanceSquared < nearestDistanceSquared) {
        nearestDistanceSquared = distanceSquared;
      }
    }
    return math.sqrt(nearestDistanceSquared);
  }

  Future<void> _stopNavigation() async {
    await positionSubscription?.cancel();
    positionSubscription = null;
    WebSpeechHelper.stop();
    if (!mounted) return;
    setState(() {
      _navigationActive = false;
      _followMe = false;
      _distanceFromRouteMeters = null;
      _routeProximityStatus = null;
      _navigationError = null;
      _destinationStage = _DestinationProximityStage.none;
      _destinationAlertText = null;
      _lastSpokenDestinationStage = _DestinationProximityStage.none;
      _lastSpokenAlert = null;
      _lastSpokenTime = null;
      _spokenFacilityKey = null;
      _offRouteAlertSpoken = false;
    });
  }

  double _calculateBearing(LatLng from, LatLng to) {
    final lat1 = from.latitude * math.pi / 180;
    final lat2 = to.latitude * math.pi / 180;
    final dLon = (to.longitude - from.longitude) * math.pi / 180;
    final y = math.sin(dLon) * math.cos(lat2);
    final x = math.cos(lat1) * math.sin(lat2) -
        math.sin(lat1) * math.cos(lat2) * math.cos(dLon);
    final radians = math.atan2(y, x);
    return (radians * 180 / math.pi + 360) % 360;
  }

  void _speakAlert(String message) {
    if (!_voiceAlertsEnabled || !_navigationActive) return;
    final now = DateTime.now();
    if (_lastSpokenAlert == message) {
      if (_lastSpokenTime != null &&
          now.difference(_lastSpokenTime!).inSeconds < 15) {
        return;
      }
    } else {
      if (_lastSpokenTime != null &&
          now.difference(_lastSpokenTime!).inSeconds < 3) {
        return;
      }
    }
    _lastSpokenAlert = message;
    _lastSpokenTime = now;
    try {
      WebSpeechHelper.speak(message);
    } catch (_) {}
  }

  double _calculateTotalRouteMeters(List<LatLng> points) {
    if (points.length < 2) return distanceKm * 1000.0;
    var sum = 0.0;
    for (var i = 0; i < points.length - 1; i++) {
      sum += service._distanceBetweenMeters(points[i], points[i + 1]);
    }
    return sum > 0 ? sum : (distanceKm * 1000.0);
  }

  double _getCurrentUserRouteProgressMeters() {
    final pos = currentPosition;
    if (pos == null || routePoints.isEmpty) return 0.0;
    final userLocation = LatLng(pos.latitude, pos.longitude);
    return _routeProgressMeters(userLocation, routePoints) ?? 0.0;
  }

  void _updateDestinationProgress(double remainingMeters) {
    var newStage = _DestinationProximityStage.none;
    String? alertText;
    String? voiceText;

    if (remainingMeters <= 35) {
      newStage = _DestinationProximityStage.reached;
      alertText = 'You have reached your destination';
      voiceText = 'You have reached your destination.';
    } else if (remainingMeters <= 100) {
      newStage = _DestinationProximityStage.m100;
      alertText = 'You are almost at your destination';
      voiceText = 'You are almost at your destination.';
    } else if (remainingMeters <= 500) {
      newStage = _DestinationProximityStage.m500;
      alertText = 'Destination is 500 m ahead';
      voiceText = 'Destination is 500 metres ahead.';
    } else if (remainingMeters <= 1000) {
      newStage = _DestinationProximityStage.km1;
      alertText = 'Destination is 1 km ahead';
      voiceText = 'Destination is 1 kilometre ahead.';
    }

    _destinationStage = newStage;
    _destinationAlertText = alertText;

    if (newStage != _DestinationProximityStage.none &&
        newStage != _lastSpokenDestinationStage) {
      _lastSpokenDestinationStage = newStage;
      if (voiceText != null) {
        _speakAlert(voiceText);
      }
    } else if (newStage == _DestinationProximityStage.none &&
        remainingMeters > 1200) {
      _lastSpokenDestinationStage = _DestinationProximityStage.none;
    }
  }

  void _updateNavigationProgressAndAlerts(Position position) {
    if (routePoints.isEmpty) return;

    final totalMeters = _calculateTotalRouteMeters(routePoints);
    final userProgressMeters =
        _getCurrentUserRouteProgressMeters().clamp(0.0, totalMeters);
    final remainingMeters = math.max(0.0, totalMeters - userProgressMeters);

    // 1. Off-Route Check
    if (_isOffRoute) {
      final now = DateTime.now();
      if (!_offRouteAlertSpoken ||
          (_lastOffRouteSpokenTime != null &&
              now.difference(_lastOffRouteSpokenTime!).inSeconds > 25)) {
        final dist = _distanceFromRouteMeters?.round() ?? 50;
        _speakAlert('You are $dist metres away from your route.');
        _offRouteAlertSpoken = true;
        _lastOffRouteSpokenTime = now;
      }
    } else {
      _offRouteAlertSpoken = false;
    }

    // 2. Approaching Destination Check
    _updateDestinationProgress(remainingMeters);

    // 3. Facility Proximity Voice Check (if active)
    if (_activeFacilityAlertCategory != null ||
        _selectedFacility != null ||
        _selectedFacilityCategories.isNotEmpty) {
      final ahead = _getNextFacilityAhead();
      if (ahead != null && ahead.isClose) {
        final key = '${ahead.facility.name}_${ahead.category.id}';
        if (_spokenFacilityKey != key) {
          _spokenFacilityKey = key;
          final distStr = _formatFacilityDistance(ahead.distanceMeters);
          final label = ahead.facility.name ?? ahead.category.label;
          _speakAlert('$label is $distStr ahead.');
        }
      }
    }
  }

  _NextStepInfo _getNextStepInfo() {
    if (routePoints.length < 2) {
      return const _NextStepInfo(
        icon: Icons.navigation_rounded,
        instruction: 'Continue on route',
      );
    }

    final pos = currentPosition;
    final LatLng userLoc = pos != null
        ? LatLng(pos.latitude, pos.longitude)
        : routePoints.first;

    int nearestIndex = 0;
    double nearestDistSq = double.infinity;
    const latScale = 110540.0;
    final lonScale = 111320.0 * math.cos(userLoc.latitude * math.pi / 180);

    for (var i = 0; i < routePoints.length - 1; i++) {
      final p1 = routePoints[i];
      final p2 = routePoints[i + 1];
      final x1 = (p1.longitude - userLoc.longitude) * lonScale;
      final y1 = (p1.latitude - userLoc.latitude) * latScale;
      final sx = (p2.longitude - userLoc.longitude) * lonScale - x1;
      final sy = (p2.latitude - userLoc.latitude) * latScale - y1;
      final lenSq = sx * sx + sy * sy;
      final fraction =
          lenSq == 0 ? 0.0 : (-(x1 * sx + y1 * sy) / lenSq).clamp(0.0, 1.0);
      final dx = x1 + sx * fraction;
      final dy = y1 + sy * fraction;
      final distSq = dx * dx + dy * dy;
      if (distSq < nearestDistSq) {
        nearestDistSq = distSq;
        nearestIndex = i;
      }
    }

    final currentBearing = _calculateBearing(
      routePoints[nearestIndex],
      routePoints[nearestIndex + 1],
    );

    var accumulatedMeters = 0.0;
    for (var j = nearestIndex + 1; j < routePoints.length - 1; j++) {
      final segLen = service._distanceBetweenMeters(
        routePoints[j],
        routePoints[j + 1],
      );
      accumulatedMeters += segLen;
      if (accumulatedMeters > 450) break;
      if (segLen < 8) continue;

      final segBearing = _calculateBearing(
        routePoints[j],
        routePoints[j + 1],
      );
      final angleDiff = ((segBearing - currentBearing + 540) % 360) - 180;

      if (angleDiff > 32 && angleDiff < 150) {
        final distAhead = accumulatedMeters.round();
        return _NextStepInfo(
          icon: Icons.turn_right_rounded,
          instruction: distAhead > 40
              ? 'Turn right in $distAhead m'
              : 'Turn right ahead',
          distanceMeters: accumulatedMeters,
        );
      } else if (angleDiff < -32 && angleDiff > -150) {
        final distAhead = accumulatedMeters.round();
        return _NextStepInfo(
          icon: Icons.turn_left_rounded,
          instruction: distAhead > 40
              ? 'Turn left in $distAhead m'
              : 'Turn left ahead',
          distanceMeters: accumulatedMeters,
        );
      }
    }

    return const _NextStepInfo(
      icon: Icons.straight_rounded,
      instruction: 'Continue on route',
    );
  }

  void _centerMapOnPosition(Position position) {
    if (!_mapReady) return;

    final currentZoom = mapController.camera.zoom;
    final targetZoom =
        (_navigationActive && currentZoom < 14.5) ? 15.5 : currentZoom;
    mapController.move(
      LatLng(position.latitude, position.longitude),
      targetZoom,
    );
  }

  void _toggleFollowMe() {
    if (!_navigationActive) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Start navigation to enable location following.'),
        ),
      );
      return;
    }
    setState(() => _followMe = !_followMe);

    final position = currentPosition;
    if (_followMe && position != null) {
      _centerMapOnPosition(position);
    }
  }

  void _fitRoute(List<LatLng> points) {
    if (!_mapReady || points.isEmpty) return;
    try {
      final bounds = LatLngBounds.fromPoints(points);
      mapController.fitCamera(
        CameraFit.bounds(bounds: bounds, padding: const EdgeInsets.all(50)),
      );
    } catch (e) {
      debugPrint('FIT ROUTE ERROR: $e');
    }
  }

  Future<void> loadRoute() async {
    if (!mounted) return;
    final fromValid = currentFromIsCurrentLocation || currentFrom.trim().isNotEmpty;
    final toValid = currentTo.trim().isNotEmpty;
    if (!fromValid || !toValid) {
      setState(() {
        loading = false;
        errorMessage = '';
      });
      return;
    }
    final generation = ++_routeSearchGeneration;
    _facilitySearchGeneration++;
    setState(() {
      loading = true;
      errorMessage = '';
      _routeEvaluationLoading = false;
      _routeEvaluationError = null;
      routeEvaluations = {};
      availableRoutes = [];
      routePoints = [];
      _routeRiskSections = [];
      _selectedRiskSection = null;
      selectedRouteIndex = 0;
      // Facilities cleared on new route search (Requirement 8)
      facilities = [];
      _facilityFailedCategoryIds.clear();
      _selectedFacility = null;
      _routeViaFacilityName = null;
      _isLoadingFacilities = false;
      _facilitiesUnavailable = false;
      _facilityResultsIncomplete = false;
      // Preserve active facility group selection from HOME / Route page
      if (_selectedFacilityCategories.isNotEmpty) {
        _syncFacilityGroupsFromCategories();
      } else if (_selectedFacilityGroups.isNotEmpty) {
        _syncCategoriesFromFacilityGroups();
      }
      routeRecommendation = const _RouteRecommendation(
        recommendedRouteIndex: null,
        rankedRouteIndexes: [],
        reason: 'Recommendation unavailable — insufficient real data',
      );
      selectedOsmRoadSegments = null;
      _osmRoadDataStatus = null;
      safetyScore = null;
      accidentSafety = null;
      roadSafety = null;
      lightingSafety = null;
      accessibilitySafety = null;
      trafficSafety = null;
      personalizedSafetyResult = PersonalizedSafetyResult(
        score: null,
        factors: [],
        activeFactors: [],
      );
      weather = null;
      isNearBlackspot = false;
      blackspotDetails = null;
      blackspotDistanceMeters = null;
      recommendationReasons = [];
      routeWarnings = [];
    });
    try {
      final position = currentFromIsCurrentLocation
          ? await service
                .getCurrentLocation()
                .timeout(const Duration(seconds: 8))
                .catchError((_) => null)
          : null;
      if (!mounted || generation != _routeSearchGeneration) return;
      if (position != null) {
        setState(() => currentPosition = position);
        updateBlackspotProximity(position);
      }

      final effectivePosition = position ??
          currentPosition ??
          (_selectedStartLocation != null
              ? Position(
                  latitude: _selectedStartLocation!.lat,
                  longitude: _selectedStartLocation!.lon,
                  timestamp: DateTime.now(),
                  accuracy: 10.0,
                  altitude: 0.0,
                  heading: 0.0,
                  speed: 0.0,
                  speedAccuracy: 0.0,
                  altitudeAccuracy: 0.0,
                  headingAccuracy: 0.0,
                )
              : null);

      final start = currentFromIsCurrentLocation
          ? (effectivePosition == null
              ? null
              : _Location(
                  lat: effectivePosition.latitude,
                  lon: effectivePosition.longitude,
                  name: currentFrom.isNotEmpty ? currentFrom : 'Current Location',
                ))
          : (_selectedStartLocation != null
              ? _selectedStartLocation
              : await service.searchLocation(currentFrom));
      final end = _selectedEndLocation != null
          ? _selectedEndLocation
          : await service.searchLocation(currentTo);

      if (_selectedStartLocation == null && start != null) {
        _selectedStartLocation = start;
      }
      if (_selectedEndLocation == null && end != null) {
        _selectedEndLocation = end;
      }

      if (!mounted || generation != _routeSearchGeneration) return;
      if (start == null || end == null) {
        final notFoundPlace = start == null ? currentFrom : currentTo;
        setState(() {
          loading = false;
          errorMessage = start == null && currentFromIsCurrentLocation
              ? 'Current location is unavailable. Check location permission and try again.'
              : 'Place "$notFoundPlace" not found. Try adding the district or Tamil Nadu.';
        });
        return;
      }

      debugPrint('FROM FINAL: ${start.name} + ${start.lat} + ${start.lon}');
      debugPrint('TO FINAL: ${end.name} + ${end.lat} + ${end.lon}');

      final routes = await service.getRoutes(start, end);
      if (!mounted || generation != _routeSearchGeneration) return;
      if (routes == null || routes.isEmpty) {
        setState(() {
          loading = false;
          errorMessage = 'Unable to find a route.';
        });
        return;
      }

      // CRITICAL PATH: IMMEDIATELY SHOW MAP, ROUTE, ALTERNATIVES, DISTANCE, ETA
      final primaryRoute = routes.first;
      // Unify startLocation and endLocation with authentic route geometry
      // endpoints so map markers and route polylines are 100% coherent at state layer
      final unifiedStart = primaryRoute.points.isNotEmpty
          ? _Location(
              lat: primaryRoute.points.first.latitude,
              lon: primaryRoute.points.first.longitude,
              name: start.name,
            )
          : start;
      final unifiedEnd = primaryRoute.points.isNotEmpty
          ? _Location(
              lat: primaryRoute.points.last.latitude,
              lon: primaryRoute.points.last.longitude,
              name: end.name,
            )
          : end;

      setState(() {
        startLocation = unifiedStart;
        endLocation = unifiedEnd;
        _selectedStartLocation = unifiedStart;
        _selectedEndLocation = unifiedEnd;
        availableRoutes = routes;
        selectedRouteIndex = 0;
        routePoints = primaryRoute.points;
        _routeRiskSections = _buildRouteRiskSections(
          routePoints: primaryRoute.points,
          evaluation: null,
          segments: null,
          weather: weather,
          travelTime: currentTravelTime,
        );
        _selectedRiskSection = null;
        distanceKm = primaryRoute.distance;
        durationMinutes = service.calculateVehicleTime(
          primaryRoute.distance,
          currentVehicle,
        );
        loading = false; // STOPS THE MAIN ROUTE LOADER IMMEDIATELY!
        _routeEvaluationLoading = true; // Background safety indicator
        _routeEvaluationError = null;
        routeRecommendation = _RouteRecommendation(
          recommendedRouteIndex: 0,
          rankedRouteIndexes: [for (var i = 0; i < routes.length; i++) i],
          reason: routes.length > 1
              ? 'Displaying primary route. Evaluating alternatives and safety in background...'
              : 'Route displayed. Evaluating safety data in background...',
        );
      });

      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && routePoints.isNotEmpty) {
          _fitRoute(routePoints);
        }
      });

      // Run secondary safety data in background without delaying route display
      unawaited(_evaluateRoutesInBackground(routes, generation));
      if (_selectedFacilityGroups.isNotEmpty) {
        unawaited(_loadFacilitiesForRoute(primaryRoute));
      }
    } catch (error) {
      if (!mounted || generation != _routeSearchGeneration) return;
      setState(() {
        loading = false;
        errorMessage = 'Unable to evaluate routes. Please try again.';
      });
      debugPrint('ROUTE LOAD ERROR: $error');
    }
  }

  Future<void> _evaluateRoutesInBackground(
    List<_RouteResult> routes,
    int generation,
  ) async {
    try {
      final evals = <_RouteEvaluation>[];
      // Prioritize selected route first so real data displays immediately
      final sortedRoutes = [
        ...routes.where((r) => r.routeIndex == selectedRouteIndex),
        ...routes.where((r) => r.routeIndex != selectedRouteIndex),
      ];
      for (final route in sortedRoutes) {
        if (!mounted || generation != _routeSearchGeneration) return;
        if (route != sortedRoutes.first) {
          await Future.delayed(const Duration(milliseconds: 1200));
        }
        try {
          final eval = await _evaluateRoute(route, _loadRouteRoadSegments(route));
          evals.add(eval);
          if (!mounted || generation != _routeSearchGeneration) return;

          setState(() {
            routeEvaluations[route.routeIndex] = eval;
            if (route.routeIndex == selectedRouteIndex) {
              weather = eval.weather;
              accidentSafety = _factorScore(eval.safety, 'Verified blackspots');
              roadSafety = _factorScore(eval.safety, 'Road condition');
              trafficSafety = _factorScore(eval.safety, 'Traffic');
              lightingSafety = _factorScore(eval.safety, 'Lighting');
              accessibilitySafety = _factorScore(eval.safety, 'Accessibility');
              personalizedSafetyResult = eval.safety;
              safetyScore = eval.safety.score;
              selectedOsmRoadSegments = eval.roadSegments;
              _osmRoadDataStatus = eval.roadSegments == null
                  ? 'Real road data unavailable for this route'
                  : 'Real OSM road segments found: ${eval.roadSegments!.length}';
              recommendationReasons = _buildRecommendationReasons(eval);
              routeWarnings = _buildRouteWarnings(eval);
              _routeRiskSections = _buildRouteRiskSections(
                routePoints: routePoints,
                evaluation: eval,
                segments: eval.roadSegments,
                weather: eval.weather,
                travelTime: currentTravelTime,
              );
            }
          });
        } catch (routeErr) {
          debugPrint('EVALUATION ERROR for route ${route.routeIndex}: $routeErr');
        }
      }

      if (!mounted || generation != _routeSearchGeneration) return;

      final recommendation = _recommendRoutes(evals);
      final currentEval = evals.firstWhere(
        (e) => e.route.routeIndex == selectedRouteIndex,
        orElse: () => evals.first,
      );

      setState(() {
        routeEvaluations = {
          for (final evaluation in evals)
            evaluation.route.routeIndex: evaluation,
        };
        routeRecommendation = recommendation;
        weather = currentEval.weather;
        accidentSafety = _factorScore(
          currentEval.safety,
          'Verified blackspots',
        );
        roadSafety = _factorScore(currentEval.safety, 'Road condition');
        trafficSafety = _factorScore(currentEval.safety, 'Traffic');
        lightingSafety = _factorScore(currentEval.safety, 'Lighting');
        accessibilitySafety = _factorScore(currentEval.safety, 'Accessibility');
        personalizedSafetyResult = currentEval.safety;
        safetyScore = currentEval.safety.score;
        selectedOsmRoadSegments = currentEval.roadSegments;
        _osmRoadDataStatus = currentEval.roadSegments == null
            ? 'Real road data unavailable for this route'
            : 'Real OSM road segments found: ${currentEval.roadSegments!.length}';
        recommendationReasons = _buildRecommendationReasons(currentEval);
        routeWarnings = _buildRouteWarnings(currentEval);
        _routeRiskSections = _buildRouteRiskSections(
          routePoints: routePoints,
          evaluation: currentEval,
          segments: currentEval.roadSegments,
          weather: currentEval.weather,
          travelTime: currentTravelTime,
        );
        _routeEvaluationLoading = false;
      });

      if (currentEval.safety.score != null) {
        final historyItem = _TripHistoryEntry(
          from: currentFrom,
          to: currentTo,
          distanceKm: currentEval.route.distance,
          durationMinutes: service.calculateVehicleTime(
            currentEval.route.distance,
            currentVehicle,
          ),
          safetyScore: currentEval.safety.score,
          timestamp: DateTime.now(),
        );
        if (_sessionTripHistory.isEmpty ||
            _sessionTripHistory.last.from != historyItem.from ||
            _sessionTripHistory.last.to != historyItem.to) {
          _sessionTripHistory.add(historyItem);
        }
        _autoSaveRouteTrip(
          origin: currentFrom,
          destination: currentTo,
          distanceKm: currentEval.route.distance,
          durationMinutes: service.calculateVehicleTime(
            currentEval.route.distance,
            currentVehicle,
          ),
          safetyScore: currentEval.safety.score,
          routeIndex: currentEval.route.routeIndex,
          vehicleMode: currentVehicle,
          travelTimeMode: currentTravelTime,
          trafficStatus: currentEval.traffic?.status,
          weatherScore: _calculateWeatherSafetyScore(currentEval.weather),
        );
      }
    } catch (e) {
      debugPrint('BACKGROUND EVALUATION ERROR: $e');
      if (mounted && generation == _routeSearchGeneration) {
        setState(() {
          _routeEvaluationLoading = false;
        });
      }
    }
  }

  void _selectRoute(_RouteResult route) {
    if (route.routeIndex == selectedRouteIndex) return;

    if (_navigationActive ||
        (_activeJourney != null && !_activeJourney!.isFinished)) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              _isTamil
                  ? 'பயணம் நடந்து கொண்டிருக்கிறது. வழியை மாற்ற பயணத்தை முடிக்கவும்.'
                  : 'Cannot switch routes while navigation is active. Please end the journey first.',
            ),
            duration: const Duration(seconds: 3),
            behavior: SnackBarBehavior.floating,
          ),
        );
      }
      return;
    }

    final evaluation = routeEvaluations[route.routeIndex];

    setState(() {
      _facilitySearchGeneration++;
      facilities = [];
      _isLoadingFacilities = false;
      _facilitiesUnavailable = false;
      _facilityResultsIncomplete = false;
      _facilityFailedCategoryIds.clear();
      _selectedFacility = null;
      _routeViaFacilityName = null;
      _selectedFacilityCategories
          .clear(); // Clear facility selection on route switch
      _syncCategoriesFromFacilityGroups();

      selectedRouteIndex = route.routeIndex;
      routePoints = route.points;
      final position = currentPosition;
      if (_navigationActive && position != null) {
        _updateRouteProximity(position);
      }
      distanceKm = route.distance;
      durationMinutes = service.calculateVehicleTime(
        route.distance,
        currentVehicle,
      );

      if (evaluation != null) {
        weather = evaluation.weather;
        accidentSafety = _factorScore(evaluation.safety, 'Verified blackspots');
        roadSafety = _factorScore(evaluation.safety, 'Road condition');
        trafficSafety = _factorScore(evaluation.safety, 'Traffic');
        lightingSafety = _factorScore(evaluation.safety, 'Lighting');
        accessibilitySafety = _factorScore(evaluation.safety, 'Accessibility');
        personalizedSafetyResult = evaluation.safety;
        safetyScore = evaluation.safety.score;
        selectedOsmRoadSegments = evaluation.roadSegments;
        _osmRoadDataStatus = evaluation.roadSegments == null
            ? 'Real road data unavailable for this route'
            : 'Real OSM road segments found: ${evaluation.roadSegments!.length}';
        recommendationReasons = _buildRecommendationReasons(evaluation);
        routeWarnings = _buildRouteWarnings(evaluation);
        _routeRiskSections = _buildRouteRiskSections(
          routePoints: routePoints,
          evaluation: evaluation,
          segments: evaluation.roadSegments,
          weather: evaluation.weather,
          travelTime: currentTravelTime,
        );
        _selectedRiskSection = null;
        _routeEvaluationLoading = false;
        _routeEvaluationError = null;
      } else {
        weather = null;
        accidentSafety = null;
        roadSafety = null;
        trafficSafety = null;
        lightingSafety = null;
        accessibilitySafety = null;
        personalizedSafetyResult = PersonalizedSafetyResult(
          score: null,
          factors: [],
          activeFactors: [],
        );
        safetyScore = null;
        selectedOsmRoadSegments = null;
        _osmRoadDataStatus = null;
        recommendationReasons = [];
        routeWarnings = [];
        _routeRiskSections = _buildRouteRiskSections(
          routePoints: routePoints,
          evaluation: null,
          segments: null,
          weather: null,
          travelTime: currentTravelTime,
        );
        _selectedRiskSection = null;
        _routeEvaluationLoading = true;
      }
    });

    if (_mapReady && route.points.isNotEmpty) {
      _fitRoute(route.points);
    }
    if (_selectedFacilityGroups.isNotEmpty) {
      unawaited(_loadFacilitiesForRoute(route));
    }
  }

  Future<List<_OsmRoadSegment>?> _loadRouteRoadSegments(
    _RouteResult route,
  ) async {
    try {
      return await service.getOsmRoadSegmentsForRoute(route.points);
    } catch (error) {
      debugPrint(
        'ROUTE OSM ROAD DATA ERROR: '
        'route ${route.routeIndex + 1}: $error',
      );
      return null;
    }
  }

  double? _calculateWeatherSafetyScore(_WeatherData? weather) {
    if (weather == null) return null;
    var baseScore = switch (weather.weatherCode) {
      0 => 100.0,
      1 || 2 || 3 => 92.0,
      45 || 48 => 65.0,
      51 || 53 || 55 => 75.0,
      56 || 57 => 40.0,
      61 => 75.0,
      63 => 60.0,
      65 => 45.0,
      66 || 67 => 30.0,
      71 => 55.0,
      73 => 45.0,
      75 => 30.0,
      80 => 70.0,
      81 => 55.0,
      82 => 40.0,
      95 => 35.0,
      96 || 99 => 20.0,
      _ => 80.0,
    };

    if (weather.precipitation > 10.0) {
      baseScore -= 20.0;
    } else if (weather.precipitation > 2.0) {
      baseScore -= 10.0;
    } else if (weather.precipitation > 0.0) {
      baseScore -= 5.0;
    }

    if (weather.windSpeed > 50.0) {
      baseScore -= 20.0;
    } else if (weather.windSpeed > 25.0) {
      baseScore -= 10.0;
    }

    if (weather.temperature < 0.0 || weather.temperature > 45.0) {
      baseScore -= 10.0;
    }

    return baseScore.clamp(0.0, 100.0);
  }

  double? _calculateTrafficSafetyScore(_TrafficAssessment? traffic) {
    if (traffic == null) return null;
    if (traffic.roadClosure) return 0.0;
    return (traffic.meanSpeedRatio.clamp(0.0, 1.0) * 100.0);
  }

  Future<_RouteEvaluation> _evaluateRoute(
    _RouteResult route,
    Future<List<_OsmRoadSegment>?> roadSegmentsFuture,
  ) async {
    final midpoint = route.points.isEmpty
        ? null
        : route.points[route.points.length ~/ 2];
    final results = await Future.wait<Object?>([
      roadSegmentsFuture,
      midpoint == null
          ? Future<_WeatherData?>.value(null)
          : service.getWeather(midpoint.latitude, midpoint.longitude),
      service._getRouteTraffic(route.points),
    ]);

    final roadSegments = results[0] as List<_OsmRoadSegment>?;
    final weatherData = results[1] as _WeatherData?;
    final traffic = results[2] as _TrafficAssessment?;
    final blackspots = await service.assessRouteBlackspots(
      route.points,
      roadSegments,
    );
    final roadScores = service.scoreOsmRoadSegments(
      roadSegments,
      includeLighting: _requiresLightingTravel(currentTravelTime),
    );

    final weatherScore = _calculateWeatherSafetyScore(weatherData);
    final trafficScore = _calculateTrafficSafetyScore(traffic);

    final safety = calculatePersonalizedSafetyScore(
      accidentScore: blackspots.clearSampleScore,
      roadConditionScore: roadScores.roadCondition,
      trafficScore: trafficScore,
      weatherScore: weatherScore,
      lightingScore: roadScores.lighting,
      accessibilityScore: roadScores.accessibility,
      accidentSegmentsWithMatches: blackspots.detectedBlackspots ?? 0,
      accidentVerifiedRecordCount: blackspots.verifiedRecordCount,
      accidentUnavailableReason: blackspots.unavailableReason,
      roadConditionSegments: roadScores.roadConditionSegments,
      lightingSegments: roadScores.lightingSegments,
      accessibilitySegments: roadScores.accessibilitySegments,
      traffic: traffic,
      weather: weatherData,
      priority: _effectivePriority,
    );

    final isDay = _isDaytimeTravel(currentTravelTime);
    final fromName = currentFrom.trim();
    final toName = currentTo.trim();
    final routeTitle = fromName.isNotEmpty && toName.isNotEmpty
        ? '$fromName → $toName'
        : 'Route ${route.routeIndex + 1}';

    final nowStr = DateTime.now().toIso8601String();
    debugPrint(
      '\n================ FACTOR DIAGNOSTICS ================\n'
      'Route: $routeTitle (${(route.distance).toStringAsFixed(1)} km, ${route.points.length} points)\n'
      '----------------------------------------------------\n'
      'FACTOR: Accident Risk\n'
      'SOURCE: Verified TN accident blackspots (MoRTH / NHAI v2024)\n'
      'STATUS: ${blackspots.successfulSamples > 0 ? 'available' : 'unavailable'}\n'
      'MATCHED: ${blackspots.detectedBlackspots ?? 0} blackspots\n'
      'COVERAGE: ${blackspots.segmentsChecked} segments checked\n'
      'VALUE: ${blackspots.clearSampleScore != null ? '${blackspots.clearSampleScore!.toStringAsFixed(1)}%' : 'unavailable'}\n'
      'QUERIED_AT: $nowStr\n'
      'REASON: ${blackspots.unavailableReason ?? (blackspots.detectedBlackspots == 0 ? 'Verified accident data: No matched blackspots' : '${blackspots.detectedBlackspots} blackspots near route')}\n\n'
      'FACTOR: Road Condition\n'
      'SOURCE: OpenStreetMap verified road attributes\n'
      'STATUS: ${roadScores.roadCondition != null ? 'available' : 'unavailable'}\n'
      'MATCHED: ${roadScores.roadConditionSegments} segments with known condition\n'
      'COVERAGE: ${roadSegments != null && roadSegments.isNotEmpty ? '${roadScores.roadConditionSegments}/${roadSegments.length} segments' : '0%'}\n'
      'VALUE: ${roadScores.roadCondition != null ? '${roadScores.roadCondition!.toStringAsFixed(1)}%' : 'unavailable'}\n'
      'QUERIED_AT: $nowStr\n'
      'REASON: ${roadScores.roadCondition != null ? 'Usable OSM surface/smoothness tags found' : 'Road attributes unmapped for this route'}\n\n'
      'FACTOR: Traffic\n'
      'SOURCE: ${traffic?.source ?? 'TomTom live flow'}\n'
      'STATUS: ${traffic != null ? 'available' : 'unavailable'}\n'
      'MATCHED: ${traffic?.matchedSamples ?? 0} matched samples\n'
      'COVERAGE: ${traffic != null ? '${traffic.coveragePercent}%' : '0%'}\n'
      'VALUE: ${trafficScore != null ? '${trafficScore.toStringAsFixed(1)}%' : 'unavailable'}\n'
      'QUERIED_AT: $nowStr\n'
      'REASON: ${traffic != null ? traffic.status : 'Live traffic data could not be retrieved; excluded from composite score'}\n\n'
      'FACTOR: Weather\n'
      'SOURCE: Open-Meteo Weather Forecast API\n'
      'STATUS: ${weatherData != null ? 'available' : 'unavailable'}\n'
      'MATCHED: 1 midpoint observation\n'
      'COVERAGE: 100%\n'
      'VALUE: ${weatherScore != null ? '${weatherScore.toStringAsFixed(1)}%' : 'unavailable'}\n'
      'QUERIED_AT: $nowStr\n'
      'REASON: ${weatherData != null ? '${weatherText(weatherData)} · ${weatherData.temperature.toStringAsFixed(0)}°C, ${weatherData.windSpeed.toStringAsFixed(0)} km/h wind' : 'Open-Meteo observations unavailable'}\n\n'
      'FACTOR: Lighting\n'
      'SOURCE: ${isDay ? 'Daylight calculation' : 'OpenStreetMap lit tags'}\n'
      'STATUS: ${isDay ? 'available (Daylight)' : (roadScores.lighting != null ? 'available' : 'unavailable')}\n'
      'MATCHED: ${isDay ? 1 : roadScores.lightingSegments} segments\n'
      'COVERAGE: ${isDay ? '100%' : (roadSegments != null && roadSegments.isNotEmpty ? '${roadScores.lightingSegments}/${roadSegments.length}' : '0%')}\n'
      'VALUE: ${isDay ? '100.0% (Natural light)' : (roadScores.lighting != null ? '${roadScores.lighting!.toStringAsFixed(1)}%' : 'unavailable')}\n'
      'QUERIED_AT: $nowStr\n'
      'REASON: ${isDay ? 'Daytime travel (natural light)' : (roadScores.lighting != null ? 'Explicit lit tags found' : 'Lighting data unmapped for this route')}\n\n'
      'FACTOR: Accessibility\n'
      'SOURCE: OpenStreetMap accessibility tags\n'
      'STATUS: ${roadScores.accessibility != null ? 'available' : 'unavailable'}\n'
      'MATCHED: ${roadScores.accessibilitySegments} segments with explicit tags\n'
      'COVERAGE: ${roadSegments != null && roadSegments.isNotEmpty ? '${roadScores.accessibilitySegments}/${roadSegments.length}' : '0%'}\n'
      'VALUE: ${roadScores.accessibility != null ? '${roadScores.accessibility!.toStringAsFixed(1)}%' : 'unavailable'}\n'
      'QUERIED_AT: $nowStr\n'
      'REASON: ${roadScores.accessibility != null ? 'Explicit wheelchair/sidewalk tags found' : 'Accessibility data unmapped for this corridor'}\n'
      '----------------------------------------------------\n'
      'Available factors:\n'
      'Weather = ${weatherScore != null ? '${weatherScore.toStringAsFixed(1)}%' : 'unavailable'}\n'
      'Traffic = ${trafficScore != null ? '${trafficScore.toStringAsFixed(1)}%' : 'unavailable'}\n'
      'Road Condition = ${roadScores.roadCondition != null ? '${roadScores.roadCondition!.toStringAsFixed(1)}%' : 'unavailable'}\n'
      'Accident Risk = ${blackspots.clearSampleScore != null ? '${blackspots.clearSampleScore!.toStringAsFixed(1)}%' : 'unavailable'}\n'
      'Lighting = ${isDay ? '100.0% (Natural light)' : (roadScores.lighting != null ? '${roadScores.lighting!.toStringAsFixed(1)}%' : 'unavailable')}\n'
      'Accessibility = ${roadScores.accessibility != null ? '${roadScores.accessibility!.toStringAsFixed(1)}%' : 'unavailable'}\n\n'
      'Evidence:\n'
      '${safety.evidenceCount}/6\n\n'
      'Final Safety Score:\n'
      '${safety.score != null ? '${safety.score!.toStringAsFixed(1)}%' : 'UNAVAILABLE — insufficient evidence'}\n'
      '====================================================\n',
    );

    return _RouteEvaluation(
      route: route,
      roadSegments: roadSegments,
      safety: safety,
      weather: weatherData,
      blackspots: blackspots,
      traffic: traffic,
    );
  }

  _RouteRecommendation _recommendRoutes(List<_RouteEvaluation> evaluations) {
    final usableRoutes = evaluations
        .where(
          (evaluation) =>
              evaluation.route.distance.isFinite &&
              evaluation.route.distance > 0 &&
              evaluation.route.duration.isFinite &&
              evaluation.route.duration > 0,
        )
        .toList();
    if (usableRoutes.length < 2) return _unavailableRecommendation;

    switch (_effectivePriority) {
      case 'Fastest':
        usableRoutes.sort((first, second) {
          final durationOrder = first.route.duration.compareTo(
            second.route.duration,
          );
          return durationOrder != 0
              ? durationOrder
              : first.route.distance.compareTo(second.route.distance);
        });
        if (_sameOsrmDurationAndDistance(usableRoutes[0], usableRoutes[1])) {
          return _unavailableRecommendation;
        }
        final fastestReason =
            usableRoutes[0].route.duration != usableRoutes[1].route.duration
            ? 'Recommended because it has the shortest OSRM-reported duration '
                  '(${formatDuration(usableRoutes.first.route.duration)}).'
            : 'Recommended because OSRM durations are tied and it has the '
                  'shorter OSRM distance '
                  '(${usableRoutes.first.route.distance.toStringAsFixed(1)} km).';
        return _RouteRecommendation(
          recommendedRouteIndex: usableRoutes.first.route.routeIndex,
          rankedRouteIndexes: [
            for (final evaluation in usableRoutes) evaluation.route.routeIndex,
          ],
          reason: fastestReason,
        );
      case 'Shortest':
        usableRoutes.sort((first, second) {
          final distanceOrder = first.route.distance.compareTo(
            second.route.distance,
          );
          return distanceOrder != 0
              ? distanceOrder
              : first.route.duration.compareTo(second.route.duration);
        });
        if (_sameOsrmDurationAndDistance(usableRoutes[0], usableRoutes[1])) {
          return _unavailableRecommendation;
        }
        final shortestReason =
            usableRoutes[0].route.distance != usableRoutes[1].route.distance
            ? 'Recommended because it has the shortest OSRM distance '
                  '(${usableRoutes.first.route.distance.toStringAsFixed(1)} km).'
            : 'Recommended because OSRM distances are tied and it has the '
                  'shorter OSRM-reported duration '
                  '(${formatDuration(usableRoutes.first.route.duration)}).';
        return _RouteRecommendation(
          recommendedRouteIndex: usableRoutes.first.route.routeIndex,
          rankedRouteIndexes: [
            for (final evaluation in usableRoutes) evaluation.route.routeIndex,
          ],
          reason: shortestReason,
        );
      case 'Less Traffic':
        final routesWithTraffic = usableRoutes
            .where((evaluation) => evaluation.traffic != null)
            .toList();
        if (routesWithTraffic.length < 2) {
          return _unavailableRecommendation;
        }
        routesWithTraffic.sort((first, second) {
          final closureOrder = (first.traffic!.roadClosure ? 1 : 0).compareTo(
            second.traffic!.roadClosure ? 1 : 0,
          );
          if (closureOrder != 0) return closureOrder;
          return second.traffic!.meanSpeedRatio.compareTo(
            first.traffic!.meanSpeedRatio,
          );
        });
        final bestTraffic = routesWithTraffic.first.traffic!;
        final secondTraffic = routesWithTraffic[1].traffic!;
        if (bestTraffic.roadClosure == secondTraffic.roadClosure &&
            bestTraffic.meanSpeedRatio == secondTraffic.meanSpeedRatio) {
          return _unavailableRecommendation;
        }
        return _RouteRecommendation(
          recommendedRouteIndex: routesWithTraffic.first.route.routeIndex,
          rankedRouteIndexes: [
            for (final evaluation in routesWithTraffic)
              evaluation.route.routeIndex,
          ],
          reason: bestTraffic.roadClosure != secondTraffic.roadClosure
              ? 'Recommended because TomTom reports no road closure on this '
                    'route, unlike the next route.'
              : 'Recommended because TomTom reports a higher observed '
                    'current-to-free-flow speed ratio '
                    '(${(bestTraffic.meanSpeedRatio * 100).toStringAsFixed(0)}%) '
                    'than the next route '
                    '(${(secondTraffic.meanSpeedRatio * 100).toStringAsFixed(0)}%).',
        );
      case 'Accessibility Friendly':
        final accessibleRoutes = usableRoutes
            .where(
              (evaluation) =>
                  _availableSafetyFactorScores(evaluation)['Accessibility'] !=
                  null,
            )
            .toList();
        return _recommendBySafetyEvidence(
          accessibleRoutes,
          accessibilityPriority: true,
        );
      default:
        final routesWithSafetyData = usableRoutes
            .where((evaluation) => evaluation.safety.score != null)
            .toList();
        return _recommendBySafetyEvidence(
          routesWithSafetyData,
          accessibilityPriority: false,
        );
    }
  }

  _RouteRecommendation _recommendBySafetyEvidence(
    List<_RouteEvaluation> candidates, {
    required bool accessibilityPriority,
  }) {
    if (candidates.length < 2) return _unavailableRecommendation;

    final isBoth = _isBothTravel(currentTravelTime);
    final isDay = _isDaytimeTravel(currentTravelTime);
    final safetyMode = _personalProfile.safetyMode;

    Map<String, double> factorWeights;
    if (safetyMode == 'Women Safety') {
      factorWeights = <String, double>{
        'Accident Risk': 0.25,
        'Road Condition': 0.15,
        'Traffic': 0.10,
        'Weather': 0.10,
        'Lighting': isDay ? 0.05 : (isBoth ? 0.25 : 0.30),
        'Accessibility': 0.10,
      };
    } else if (safetyMode == 'Senior Friendly') {
      factorWeights = <String, double>{
        'Accessibility': 0.35,
        'Road Condition': 0.25,
        'Accident Risk': 0.20,
        'Traffic': 0.10,
        'Weather': 0.05,
        'Lighting': isDay ? 0.0 : 0.05,
      };
    } else if (safetyMode == 'Family Safety') {
      factorWeights = <String, double>{
        'Accident Risk': 0.35,
        'Road Condition': 0.20,
        'Weather': 0.15,
        'Traffic': 0.15,
        'Accessibility': 0.10,
        'Lighting': isDay ? 0.0 : 0.05,
      };
    } else {
      factorWeights = <String, double>{
        'Accident Risk': accessibilityPriority ? 0.20 : 0.30,
        'Road Condition': accessibilityPriority ? 0.15 : 0.20,
        'Traffic': accessibilityPriority ? 0.10 : 0.15,
        'Weather': 0.10,
        'Lighting': isDay
            ? 0.0
            : ((accessibilityPriority ? 0.10 : 0.10) * (isBoth ? 0.5 : 1.0)),
        'Accessibility': accessibilityPriority ? 0.35 : 0.15,
      };
    }

    final commonFactors = factorWeights.keys
        .where(
          (title) => candidates.every(
            (evaluation) =>
                _availableSafetyFactorScores(evaluation).containsKey(title),
          ),
        )
        .toList();
    if (commonFactors.isEmpty ||
        (accessibilityPriority && !commonFactors.contains('Accessibility'))) {
      if (!candidates.every((e) => e.safety.score != null)) {
        return _unavailableRecommendation;
      }
    }

    double scoreFor(_RouteEvaluation evaluation) {
      if (commonFactors.isNotEmpty) {
        final scores = _availableSafetyFactorScores(evaluation);
        var weightedScore = 0.0;
        var totalWeight = 0.0;
        for (final title in commonFactors) {
          final weight = factorWeights[title] ?? 0.1;
          weightedScore += scores[title]! * weight;
          totalWeight += weight;
        }
        if (totalWeight > 0) return weightedScore / totalWeight;
      }
      return evaluation.safety.score ?? 0.0;
    }

    // Explicit balanced scoring balancing Safety (primary), Travel time, Distance, and Traffic context
    final minDistance = candidates.map((c) => c.route.distance).reduce(math.min);
    final minDuration = candidates.map((c) => c.route.duration).reduce(math.min);

    double compositeScoreFor(_RouteEvaluation evaluation) {
      final s = scoreFor(evaluation);
      final durEfficiency = evaluation.route.duration > 0
          ? (minDuration / evaluation.route.duration).clamp(0.4, 1.0) * 100.0
          : 100.0;
      final distEfficiency = evaluation.route.distance > 0
          ? (minDistance / evaluation.route.distance).clamp(0.4, 1.0) * 100.0
          : 100.0;

      double trafficBonus = 0.0;
      if (evaluation.traffic != null) {
        if (evaluation.traffic!.roadClosure) {
          trafficBonus -= 25.0;
        } else if (evaluation.traffic!.meanSpeedRatio >= 0.85) {
          trafficBonus += 5.0;
        }
      }

      if (_personalProfile.safetyMode == 'Women Safety') {
        // High safety priority (75%) + duration (15%) + distance (10%)
        return (s * 0.75) + (durEfficiency * 0.15) + (distEfficiency * 0.10) + trafficBonus;
      }
      if (_personalProfile.safetyMode == 'Senior Friendly') {
        // Comfort & accessibility (80%) + duration (10%) + distance (10%)
        return (s * 0.80) + (durEfficiency * 0.10) + (distEfficiency * 0.10) + trafficBonus;
      }
      if (_personalProfile.safetyMode == 'Family Safety') {
        // Family safety margin (70%) + duration (15%) + distance (15%)
        return (s * 0.70) + (durEfficiency * 0.15) + (distEfficiency * 0.15) + trafficBonus;
      }
      if (accessibilityPriority) {
        return (s * 0.80) + (durEfficiency * 0.10) + (distEfficiency * 0.10) + trafficBonus;
      }

      // Safety is primary (65%), balanced with travel time (15%) and distance (15%)
      return (s * 0.65) + (durEfficiency * 0.15) + (distEfficiency * 0.15) + trafficBonus;
    }

    candidates.sort((first, second) {
      final scoreOrder = compositeScoreFor(second).compareTo(compositeScoreFor(first));
      if (scoreOrder != 0) return scoreOrder;
      final safetyOrder = scoreFor(second).compareTo(scoreFor(first));
      if (safetyOrder != 0) return safetyOrder;
      final distanceOrder = first.route.distance.compareTo(
        second.route.distance,
      );
      return distanceOrder != 0
          ? distanceOrder
          : first.route.duration.compareTo(second.route.duration);
    });
    final best = candidates.first;
    final next = candidates[1];
    final bestScore = scoreFor(best);
    final nextScore = scoreFor(next);
    final sameEvidence = bestScore == nextScore;
    if (sameEvidence && _sameOsrmDurationAndDistance(best, next)) {
      return _unavailableRecommendation;
    }

    final String reason;
    final tripContext = _classifyTrip(best.route.distance, best.route.duration);
    final tripLabel = switch (tripContext) {
      TripContextType.short => 'short local trip',
      TripContextType.medium => 'sub-district transit',
      TripContextType.long => 'long-distance highway corridor',
    };

    if (_personalProfile.safetyMode == 'Women Safety') {
      reason = isDay
          ? 'Recommended for Women Safety mode ($tripLabel): verified corridor with lowest accident exposure and reliable road infrastructure.'
          : 'Recommended for Women Safety mode ($tripLabel): prioritized verified lighting and low accident exposure for night travel.';
    } else if (_personalProfile.safetyMode == 'Senior Friendly') {
      reason = 'Recommended for Senior Friendly mode ($tripLabel): prioritized verified accessibility and smoother road conditions.';
    } else if (_personalProfile.safetyMode == 'Family Safety') {
      reason = 'Recommended for Family Safety mode ($tripLabel): highest accident safety margin (${bestScore.round()}%) and favorable corridor conditions.';
    } else if (accessibilityPriority) {
      reason = 'Recommended because it has better available accessibility and safety evidence for your selected priority (${commonFactors.join(", ")}).';
    } else if (bestScore > 0) {
      reason = 'Recommended because it provides the best overall balance of verified safety (${bestScore.round()}%), travel time (${formatDuration(best.route.duration)}), and distance (${best.route.distance.toStringAsFixed(1)} km) for this $tripLabel.';
    } else {
      reason = 'Recommended because it provides the best balance of travel time (${formatDuration(best.route.duration)}) and distance (${best.route.distance.toStringAsFixed(1)} km).';
    }

    return _RouteRecommendation(
      recommendedRouteIndex: best.route.routeIndex,
      rankedRouteIndexes: [
        for (final evaluation in candidates) evaluation.route.routeIndex,
      ],
      reason: reason,
    );
  }

  Map<String, double> _availableSafetyFactorScores(
    _RouteEvaluation evaluation,
  ) {
    return {
      for (final factor in evaluation.safety.factors)
        if (factor.relevant && factor.score != null)
          factor.title: factor.score!,
    };
  }

  bool _sameOsrmDurationAndDistance(
    _RouteEvaluation first,
    _RouteEvaluation second,
  ) {
    return first.route.duration == second.route.duration &&
        first.route.distance == second.route.distance;
  }

  _RouteRecommendation get _unavailableRecommendation =>
      const _RouteRecommendation(
        recommendedRouteIndex: null,
        rankedRouteIndexes: [],
        reason: 'Recommendation unavailable — insufficient real data',
      );

  List<_RouteResult> get _routesForDisplay {
    if (!routeRecommendation.isAvailable) return availableRoutes;
    final routeByIndex = {
      for (final route in availableRoutes) route.routeIndex: route,
    };
    final rankedRoutes = routeRecommendation.rankedRouteIndexes
        .map((routeIndex) => routeByIndex[routeIndex])
        .whereType<_RouteResult>();
    return [
      ...rankedRoutes,
      for (final route in availableRoutes)
        if (!routeRecommendation.rankedRouteIndexes.contains(route.routeIndex))
          route,
    ];
  }

  String get _effectivePriority {
    if (currentMainPriority != 'Safety First') return currentMainPriority;
    return switch (currentPreference) {
      'Fastest Route' => 'Fastest',
      'Shortest Route' => 'Shortest',
      'Accessibility Friendly' => 'Accessibility Friendly',
      'Less Traffic' => 'Less Traffic',
      _ => 'Safety First',
    };
  }

  int? get _shortestRouteIndex {
    if (availableRoutes.isEmpty) return null;
    int shortestIdx = 0;
    for (int i = 1; i < availableRoutes.length; i++) {
      if (availableRoutes[i].distance < availableRoutes[shortestIdx].distance) {
        shortestIdx = i;
      }
    }
    return availableRoutes[shortestIdx].routeIndex;
  }

  int? get _fastestRouteIndex {
    if (availableRoutes.isEmpty) return null;
    int fastestIdx = 0;
    for (int i = 1; i < availableRoutes.length; i++) {
      if (availableRoutes[i].duration < availableRoutes[fastestIdx].duration) {
        fastestIdx = i;
      }
    }
    return availableRoutes[fastestIdx].routeIndex;
  }

  int? get _safestRouteIndex {
    if (availableRoutes.isEmpty) return null;
    int? safestIdx;
    double highestScore = -1.0;
    for (final r in availableRoutes) {
      final score = routeEvaluations[r.routeIndex]?.safety.score;
      if (score != null && score > highestScore) {
        highestScore = score;
        safestIdx = r.routeIndex;
      }
    }
    return safestIdx;
  }

  int? get _recommendedRouteIndex {
    return routeRecommendation.recommendedRouteIndex;
  }

  List<String> _getRouteCategoryBadges(int routeIndex) {
    if (availableRoutes.length <= 1) return const [];
    final badges = <String>[];
    if (routeIndex == _recommendedRouteIndex && routeRecommendation.isAvailable) {
      if (_personalProfile.safetyMode == 'Women Safety') {
        badges.add('BEST FOR WOMEN');
      } else if (_personalProfile.safetyMode == 'Senior Friendly') {
        badges.add('SENIOR OPTIMAL');
      } else if (_personalProfile.safetyMode == 'Family Safety') {
        badges.add('FAMILY SAFE');
      } else {
        badges.add('BEST BALANCED');
      }
    }
    if (routeIndex == _safestRouteIndex && _safestRouteIndex != null) {
      badges.add('SAFEST');
    }
    if (routeIndex == _shortestRouteIndex && _shortestRouteIndex != null) {
      badges.add('SHORTEST');
    }
    if (routeIndex == _fastestRouteIndex && _fastestRouteIndex != null) {
      badges.add('FASTEST');
    }
    if (badges.isEmpty) {
      badges.add('ALTERNATIVE');
    }
    return badges;
  }

  String _getRouteCategoryBadge(int routeIndex) {
    final badges = _getRouteCategoryBadges(routeIndex);
    return badges.isNotEmpty ? badges.first : '';
  }

  String _getRouteFullBadgeLabel(int routeIndex) {
    final badges = _getRouteCategoryBadges(routeIndex);
    return badges.isNotEmpty ? badges.join(' • ') : '';
  }

  Color _getRouteBadgeColor(String badge) {
    switch (badge) {
      case 'BEST':
      case 'BEST BALANCED':
      case 'FAMILY SAFE':
        return _NeonTheme.safeGreen;
      case 'BEST FOR WOMEN':
        return const Color(0xffEC4899);
      case 'SENIOR OPTIMAL':
        return const Color(0xff8B5CF6);
      case 'SAFEST':
        return const Color(0xff10B981);
      case 'SHORTEST':
        return const Color(0xffF59E0B);
      case 'FASTEST':
        return const Color(0xff38BDF8);
      default:
        return const Color(0xffC084FC);
    }
  }

  Color _getRouteCoreColor(int routeIndex) {
    switch (routeIndex % 4) {
      case 0:
        return _NeonTheme.neonCyan;
      case 1:
        return const Color(0xffC084FC);
      case 2:
        return const Color(0xff38BDF8);
      case 3:
        return const Color(0xffFBBF24);
      default:
        return _NeonTheme.neonCyan;
    }
  }

  Color _getRouteUnselectedColor(int routeIndex) {
    switch (routeIndex % 4) {
      case 0:
        return const Color(0xff0284C7);
      case 1:
        return const Color(0xff9333EA);
      case 2:
        return const Color(0xff0369A1);
      case 3:
        return const Color(0xffD97706);
      default:
        return const Color(0xff0284C7);
    }
  }

  PersonalizedSafetyResult calculatePersonalizedSafetyScore({
    required double? accidentScore,
    required double? roadConditionScore,
    required double? trafficScore,
    required double? weatherScore,
    required double? lightingScore,
    required double? accessibilityScore,
    required int accidentSegmentsWithMatches,
    required int accidentVerifiedRecordCount,
    required String? accidentUnavailableReason,
    required int roadConditionSegments,
    required int lightingSegments,
    required int accessibilitySegments,
    required _TrafficAssessment? traffic,
    required _WeatherData? weather,
    required String priority,
    PersonalSafetyProfile? profile,
    double? routeDistanceKm,
    double? routeDurationMinutes,
  }) {
    return calculateAuthoritativeSafetyScore(
      accidentScore: accidentScore,
      roadConditionScore: roadConditionScore,
      trafficScore: trafficScore,
      weatherScore: weatherScore,
      lightingScore: lightingScore,
      accessibilityScore: accessibilityScore,
      accidentSegmentsWithMatches: accidentSegmentsWithMatches,
      accidentVerifiedRecordCount: accidentVerifiedRecordCount,
      accidentUnavailableReason: accidentUnavailableReason,
      roadConditionSegments: roadConditionSegments,
      lightingSegments: lightingSegments,
      accessibilitySegments: accessibilitySegments,
      travelTime: currentTravelTime,
      priority: priority,
      profile: profile ?? _personalProfile,
      routeDistanceKm: routeDistanceKm ?? distanceKm,
      routeDurationMinutes: routeDurationMinutes ?? durationMinutes,
      trafficSource: traffic?.source,
      trafficStatus: traffic?.status,
      trafficMatchedSamples: traffic?.matchedSamples,
      trafficCoveragePercent: traffic?.coveragePercent.toDouble(),
      trafficRoadClosure: traffic?.roadClosure ?? false,
      weatherDescription: weather != null ? weatherText(weather) : null,
      weatherTemperature: weather?.temperature,
      weatherWindSpeed: weather?.windSpeed,
      weatherCode: weather?.weatherCode,
      weatherPrecipitation: weather?.precipitation,
      weatherTimestamp: weather?.fetchedAt,
    );
  }

  List<String> _buildRecommendationReasons(_RouteEvaluation recommended) {
    final reasons = <String>[
      'Optimal primary route selected for the destination corridor.',
    ];

    if (recommended.blackspots.successfulSamples > 0) {
      if ((recommended.blackspots.detectedBlackspots ?? 0) == 0) {
        reasons.add(
          'Verified accident data: No matched blackspots along route corridor.',
        );
      } else {
        reasons.add(
          'Verified blackspot checks flagged ${recommended.blackspots.detectedBlackspots} risk location(s).',
        );
      }
    }

    return reasons;
  }

  List<String> _buildRouteWarnings(_RouteEvaluation evaluation) {
    final warnings = <String>[];
    if (!evaluation.safety.isEvidenceSufficient) {
      warnings.add(
        evaluation.safety.insufficientDataReason ?? 'Not enough verified route data is available to calculate a reliable score.',
      );
    }
    if (_effectivePriority == 'Less Traffic' && evaluation.traffic == null) {
      warnings.add('TomTom live traffic data is unavailable for this route.');
    }
    if (evaluation.blackspots.successfulSamples == 0) {
      warnings.add('Verified blackspot data is unavailable for this route.');
    } else if ((evaluation.blackspots.detectedBlackspots ?? 0) > 0) {
      warnings.add(
        '${evaluation.blackspots.detectedBlackspots} matched road segment(s) are near verified blackspots.',
      );
    }
    if (evaluation.safety.score == null) {
      warnings.add('No scored safety factors are available for this route.');
    }
    return warnings;
  }

  List<_RouteRiskSection> _buildRouteRiskSections({
    required List<LatLng> routePoints,
    required _RouteEvaluation? evaluation,
    required List<_OsmRoadSegment>? segments,
    required _WeatherData? weather,
    required String travelTime,
  }) {
    if (routePoints.length < 2) return const [];

    final blackspots = SafeRouteService._authenticVerifiedBlackspots;
    final isNight = _requiresLightingTravel(travelTime);
    final weatherScore = _calculateWeatherSafetyScore(weather);

    final subSegmentLevels = <_SectionRiskLevel>[];
    final subSegmentScores = <double>[];
    final subSegmentBlackspots = <String?>[];
    final subSegmentRoads = <String?>[];
    final subSegmentLighting = <String?>[];
    final subSegmentAccess = <String?>[];

    for (var i = 0; i < routePoints.length - 1; i++) {
      final p1 = routePoints[i];
      final p2 = routePoints[i + 1];
      final mid = LatLng(
        (p1.latitude + p2.latitude) / 2,
        (p1.longitude + p2.longitude) / 2,
      );

      // 1. Authentic Blackspot Check (within 1000m corridor)
      var hasBlackspot = false;
      String? blackspotName;
      for (final spot in blackspots) {
        if (service._distanceBetweenMeters(mid, spot.location) <= 1000.0) {
          hasBlackspot = true;
          blackspotName = '${spot.landmark} (${spot.id})';
          break;
        }
      }
      final blackspotScore = hasBlackspot ? 25.0 : 100.0;
      subSegmentBlackspots.add(
        hasBlackspot
            ? 'Near Verified Blackspot: $blackspotName'
            : 'No verified blackspots near this section',
      );

      // 2. Real OSM Road Segment Check
      _OsmRoadSegment? nearestSeg;
      var nearestSegDist = double.infinity;
      if (segments != null && segments.isNotEmpty) {
        for (final seg in segments) {
          final d = service._distanceBetweenMeters(mid, seg.routeMatchPoint);
          if (d < nearestSegDist) {
            nearestSegDist = d;
            nearestSeg = seg;
          }
        }
      }

      double? roadScore;
      double? lightScore;
      double? accessScore;
      String? roadStatus;
      String? lightStatus;
      String? accessStatus;

      if (nearestSeg != null && nearestSegDist <= 1500.0) {
        roadScore = service._roadConditionScoreForSegment(nearestSeg);
        if (nearestSeg.surface != null || nearestSeg.smoothness != null) {
          final surf = nearestSeg.surface != null
              ? 'Surface: ${nearestSeg.surface}'
              : null;
          final smooth = nearestSeg.smoothness != null
              ? 'Smoothness: ${nearestSeg.smoothness}'
              : null;
          roadStatus = [surf, smooth].whereType<String>().join(' · ');
        }

        if (isNight) {
          lightScore = service._lightingScoreForSegment(nearestSeg);
          if (nearestSeg.lit != null) {
            lightStatus = nearestSeg.lit?.toLowerCase() == 'yes'
                ? 'Street lighting: Lit'
                : 'Street lighting: Unlit (Night hazard)';
          }
        } else {
          lightStatus = 'Daytime: Street lighting not active';
        }

        accessScore = service._accessibilityScoreForSegment(nearestSeg);
        if (nearestSeg.sidewalk != null || nearestSeg.wheelchair != null) {
          final sw = nearestSeg.sidewalk != null
              ? 'Sidewalk: ${nearestSeg.sidewalk}'
              : null;
          final wc = nearestSeg.wheelchair != null
              ? 'Wheelchair: ${nearestSeg.wheelchair}'
              : null;
          accessStatus = [sw, wc].whereType<String>().join(' · ');
        }
      }
      subSegmentRoads.add(roadStatus);
      subSegmentLighting.add(lightStatus);
      subSegmentAccess.add(accessStatus);

      // 3. Composite score calculation from available real factors
      var weightedSum = 0.0;
      var weightTotal = 0.0;

      weightedSum += blackspotScore * 0.35;
      weightTotal += 0.35;

      if (roadScore != null) {
        weightedSum += roadScore * 0.30;
        weightTotal += 0.30;
      }

      if (lightScore != null) {
        weightedSum += lightScore * 0.15;
        weightTotal += 0.15;
      }

      if (accessScore != null) {
        weightedSum += accessScore * 0.10;
        weightTotal += 0.10;
      }

      if (weatherScore != null) {
        weightedSum += weatherScore * 0.15;
        weightTotal += 0.15;
      }

      // Live Traffic is included ONLY if real/available, never invented:
      if (evaluation?.traffic != null &&
          evaluation!.traffic!.status != 'Traffic offline' &&
          evaluation.traffic!.coveragePercent > 0) {
        final trafficScore = _calculateTrafficSafetyScore(evaluation.traffic);
        if (trafficScore != null) {
          weightedSum += trafficScore * 0.20;
          weightTotal += 0.20;
        }
      }

      final score = weightTotal > 0 ? (weightedSum / weightTotal) : 75.0;
      subSegmentScores.add(score);

      final _SectionRiskLevel level;
      if (hasBlackspot || score < 45.0) {
        level = _SectionRiskLevel.high;
      } else if (score < 70.0) {
        level = _SectionRiskLevel.medium;
      } else {
        level = _SectionRiskLevel.low;
      }
      subSegmentLevels.add(level);
    }

    final weatherImpactStr = weather != null
        ? '${weatherText(weather)} · ${weather.temperature.round()}°C · Precipitation: ${weather.precipitation} mm'
        : null;

    final trafficImpactStr = (evaluation?.traffic != null &&
            evaluation!.traffic!.status != 'Traffic offline')
        ? '${evaluation.traffic!.status} (Speed ratio: ${(evaluation.traffic!.meanSpeedRatio * 100).round()}%)'
        : null;

    // Group consecutive sub-segments with the same risk level
    final sections = <_RouteRiskSection>[];
    var startPointIndex = 0;
    var currentLevel = subSegmentLevels.first;

    for (var i = 1; i <= subSegmentLevels.length; i++) {
      final isEnd = i == subSegmentLevels.length;
      final isLevelChange = !isEnd && subSegmentLevels[i] != currentLevel;

      if (isEnd || isLevelChange) {
        final pts = routePoints.sublist(startPointIndex, i + 1);

        var sumScore = 0.0;
        var totalLen = 0.0;
        String? foundBlackspot;
        String? foundRoad;
        String? foundLight;
        String? foundAccess;

        for (var k = startPointIndex; k < i; k++) {
          sumScore += subSegmentScores[k];
          totalLen += service._distanceBetweenMeters(
            routePoints[k],
            routePoints[k + 1],
          );
          if (subSegmentBlackspots[k] != null &&
              subSegmentBlackspots[k]!.startsWith('Near Verified')) {
            foundBlackspot = subSegmentBlackspots[k];
          }
          if (subSegmentRoads[k] != null) {
            foundRoad ??= subSegmentRoads[k];
          }
          if (subSegmentLighting[k] != null) {
            foundLight ??= subSegmentLighting[k];
          }
          if (subSegmentAccess[k] != null) {
            foundAccess ??= subSegmentAccess[k];
          }
        }

        final count = i - startPointIndex;
        final avgScore = count > 0 ? (sumScore / count) : 75.0;

        sections.add(
          _RouteRiskSection(
            sectionIndex: sections.length + 1,
            points: pts,
            riskLevel: currentLevel,
            score: avgScore,
            lengthMeters: totalLen,
            blackspotStatus:
                foundBlackspot ?? 'No verified blackspots near this section',
            roadConditionStatus: foundRoad,
            lightingStatus: foundLight,
            accessibilityStatus: foundAccess,
            weatherImpactStatus: weatherImpactStr,
            trafficStatus: trafficImpactStr,
          ),
        );

        if (!isEnd) {
          startPointIndex = i;
          currentLevel = subSegmentLevels[i];
        }
      }
    }

    return sections;
  }

