      decoration: BoxDecoration(
        color: _isDarkMode
            ? _NeonTheme.cardDark.withValues(alpha: 0.90)
            : Colors.white.withValues(alpha: 0.94),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: _isDarkMode ? _NeonTheme.cyanBorder : const Color(0x350284C7),
          width: 1,
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.15),
            blurRadius: 8,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            'Route Safety:',
            style: TextStyle(
              fontSize: 10,
              fontWeight: FontWeight.w800,
              letterSpacing: 0.3,
              color: _isDarkMode ? Colors.white70 : Colors.black87,
            ),
          ),
          const SizedBox(width: 8),
          _legendItem(_NeonTheme.safeGreen, 'Low Risk', _SectionRiskLevel.low),
          const SizedBox(width: 8),
          _legendItem(
            _NeonTheme.warningGold,
            'Medium Risk',
            _SectionRiskLevel.medium,
          ),
          const SizedBox(width: 8),
          _legendItem(_NeonTheme.dangerRed, 'High Risk', _SectionRiskLevel.high),
        ],
      ),
    );
  }

  Widget _legendItem(Color color, String label, _SectionRiskLevel level) {
    return InkWell(
      onTap: () {
        final match =
            _routeRiskSections.where((s) => s.riskLevel == level).firstOrNull;
        if (match != null) {
          setState(() => _selectedRiskSection = match);
        }
      },
      borderRadius: BorderRadius.circular(6),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 3, vertical: 2),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Container(
              width: 7,
              height: 7,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: color,
              ),
            ),
            const SizedBox(width: 4),
            Text(
              label,
              style: TextStyle(
                fontSize: 9.5,
                fontWeight: FontWeight.w700,
                color: color,
              ),
            ),
          ],
        ),
      ),
    );
  }

