            const Divider(height: 1, thickness: 0.5),
            const SizedBox(height: 8),

            // 1. Accident / Blackspot Status
            if (section.blackspotStatus != null)
              _riskDetailRow(
                icon: Icons.shield_rounded,
                iconColor: section.blackspotStatus!.startsWith('Near Verified')
                    ? _NeonTheme.dangerRed
                    : _NeonTheme.safeGreen,
                title: 'Accident Risk',
                detail: section.blackspotStatus!,
              ),

            // 2. Road Condition Status
            if (section.roadConditionStatus != null)
              _riskDetailRow(
                icon: Icons.add_road_rounded,
                iconColor: _NeonTheme.neonCyan,
                title: 'Road Condition',
                detail: section.roadConditionStatus!,
              ),

            // 3. Lighting Status
            if (section.lightingStatus != null)
              _riskDetailRow(
                icon: Icons.lightbulb_rounded,
                iconColor: _NeonTheme.warningGold,
                title: 'Lighting',
                detail: section.lightingStatus!,
              ),

            // 4. Accessibility Status
            if (section.accessibilityStatus != null)
              _riskDetailRow(
                icon: Icons.accessible_rounded,
                iconColor: _NeonTheme.neonViolet,
                title: 'Accessibility',
                detail: section.accessibilityStatus!,
              ),

            // 5. Weather Impact
            if (section.weatherImpactStatus != null)
              _riskDetailRow(
                icon: Icons.cloud_rounded,
                iconColor: const Color(0xff38BDF8),
                title: 'Weather Impact',
                detail: section.weatherImpactStatus!,
              ),

            // 6. Traffic (if available)
            if (section.trafficStatus != null)
              _riskDetailRow(
                icon: Icons.traffic_rounded,
                iconColor: _NeonTheme.neonAmber,
                title: 'Live Traffic',
                detail: section.trafficStatus!,
              ),
          ],
        ),
      ),
    );
  }

  Widget _riskDetailRow({
    required IconData icon,
    required Color iconColor,
    required String title,
    required String detail,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 6),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(icon, size: 14, color: iconColor),
          const SizedBox(width: 8),
          Expanded(
            child: RichText(
              text: TextSpan(
                style: TextStyle(
                  fontSize: 10.5,
                  height: 1.3,
                  color: _isDarkMode ? Colors.white70 : Colors.black87,
                ),
                children: [
                  TextSpan(
                    text: '$title: ',
                    style: const TextStyle(fontWeight: FontWeight.w700),
                  ),
                  TextSpan(text: detail),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  double? _factorScore(PersonalizedSafetyResult result, String title) {
    for (final factor in result.factors) {
      if (factor.title == title ||
          (title == 'Verified blackspots' && factor.title == 'Accident Risk') ||
          (title == 'Accident Risk' && factor.title == 'Verified blackspots') ||
          (title == 'Road condition' && factor.title == 'Road Condition') ||
          (title == 'Road Condition' && factor.title == 'Road condition') ||
          (title == 'Live Traffic' && factor.title == 'Traffic') ||
          (title == 'Traffic' && factor.title == 'Live Traffic')) {
        return factor.score;
      }
    }
    return null;
  }

  String weatherText([_WeatherData? targetWeather]) {
    final w = targetWeather ?? weather;
    if (w == null) return 'Unavailable';

    final code = w.weatherCode;

    if (code == 0) return 'Clear';
    if (code >= 1 && code <= 3) return 'Cloudy';
    if (code == 45 || code == 48) return 'Fog';
    if ((code >= 51 && code <= 67) || (code >= 80 && code <= 82)) return 'Rain';
    if ((code >= 71 && code <= 77) || (code >= 85 && code <= 86)) return 'Snow';
    if (code >= 95) return 'Storm';

    return 'Weather data';
  }

  String formatDuration(double minutes) {
    final hours = minutes ~/ 60;
    final mins = minutes.round() % 60;

    if (hours > 0) {
      return '${hours}h ${mins}m';
    }

    return '$mins min';
  }

  @override
  void dispose() {
    _debounceTimer?.cancel();
    WebSpeechHelper.stop();
    _heroAnimController.dispose();
    positionSubscription?.cancel();
    positionSubscription = null;
    fromController.dispose();
    toController.dispose();
    _tripsSearchController.dispose();
    _favouritesSearchController.dispose();
    super.dispose();
  }

