  Widget _buildBottomNavBar() {
    final isHome = _currentTab == _DashboardTab.planRoute;
    final isTrips = _currentTab == _DashboardTab.myTrips;
    final isJourney = _currentTab == _DashboardTab.journeyMode;
    final isSaved = _currentTab == _DashboardTab.favouriteRoutes;

    int currentIndex = 0;
    if (isHome) {
      currentIndex = 0;
    } else if (isTrips) {
      currentIndex = 1;
    } else if (isJourney) {
      currentIndex = 2;
    } else if (isSaved) {
      currentIndex = 3;
    } else {
      currentIndex = 0;
    }

    return Container(
      decoration: BoxDecoration(
        color: _isDarkMode
            ? const Color(0xEB0A1120)
            : const Color(0xF2FFFFFF),
        border: Border(
          top: BorderSide(
            color: _isDarkMode
                ? _NeonTheme.cyanBorder.withValues(alpha: 0.35)
                : const Color(0x250284C7),
            width: 1,
          ),
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: _isDarkMode ? 0.30 : 0.05),
            blurRadius: 10,
            offset: const Offset(0, -2),
          ),
        ],
      ),
      child: SafeArea(
        top: false,
        child: SizedBox(
          height: 60,
          child: BottomNavigationBar(
            currentIndex: currentIndex,
            onTap: (index) {
              setState(() {
                if (index == 0) {
                  _currentTab = _DashboardTab.planRoute;
                } else if (index == 1) {
                  _currentTab = _DashboardTab.myTrips;
                } else if (index == 2) {
                  _currentTab = _DashboardTab.journeyMode;
                } else if (index == 3) {
                  _currentTab = _DashboardTab.favouriteRoutes;
                } else if (index == 4) {
                  _openSafetyProfileDialog();
                }
              });
            },
            backgroundColor: Colors.transparent,
            elevation: 0,
            selectedItemColor: _NeonTheme.neonCyan,
            unselectedItemColor: _isDarkMode
                ? _NeonTheme.textSecondaryDark
                : _NeonTheme.textSecondaryLight,
            selectedFontSize: 11,
            unselectedFontSize: 10,
            selectedLabelStyle: const TextStyle(fontWeight: FontWeight.w800),
            unselectedLabelStyle: const TextStyle(fontWeight: FontWeight.w500),
            type: BottomNavigationBarType.fixed,
            items: const [
              BottomNavigationBarItem(
                icon: Icon(Icons.explore_rounded),
                label: 'Home',
              ),
              BottomNavigationBarItem(
                icon: Icon(Icons.history_rounded),
                label: 'Trips',
              ),
              BottomNavigationBarItem(
                icon: Icon(Icons.navigation_rounded),
                label: 'Journey',
              ),
              BottomNavigationBarItem(
                icon: Icon(Icons.star_rounded),
                label: 'Saved',
              ),
              BottomNavigationBarItem(
                icon: Icon(Icons.person_pin_rounded),
                label: 'Profile',
              ),
            ],
          ),
        ),
      ),
    );
  }

