  Widget _buildCompactFeatureHighlightsRow() {
    final items = [
      (
        icon: Icons.shield_rounded,
        color: const Color(0xff00E676),
        label: 'Real-time\nSafety Analysis',
      ),
      (
        icon: Icons.alt_route_rounded,
        color: const Color(0xffA855F7),
        label: 'Multiple\nRoute Options',
      ),
      (
        icon: Icons.place_rounded,
        color: const Color(0xff00E5FF),
        label: 'Nearby\nFacilities',
      ),
      (
        icon: Icons.emergency_rounded,
        color: const Color(0xffFF3366),
        label: 'Emergency\nSupport',
      ),
    ];

    Widget buildTile(({IconData icon, Color color, String label}) item) {
      return Container(
        margin: const EdgeInsets.symmetric(horizontal: 2, vertical: 2),
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        constraints: const BoxConstraints(minHeight: 48),
        decoration: BoxDecoration(
          color: _isDarkMode ? const Color(0xff0B1528) : Colors.white,
          borderRadius: BorderRadius.circular(12),
          border: Border.all(
            color: _isDarkMode ? const Color(0xff1E385C) : const Color(0x300284C7),
            width: 1,
          ),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withValues(alpha: _isDarkMode ? 0.20 : 0.04),
              blurRadius: 6,
              offset: const Offset(0, 2),
            ),
          ],
        ),
        child: Row(
          children: [
            Container(
              width: 26,
              height: 26,
              decoration: BoxDecoration(
                color: item.color.withValues(alpha: 0.14),
                borderRadius: BorderRadius.circular(7),
              ),
              child: Center(
                child: Icon(item.icon, size: 14, color: item.color),
              ),
            ),
            const SizedBox(width: 8),
            Expanded(
              child: Text(
                item.label,
                style: TextStyle(
                  fontSize: 10.5,
                  fontWeight: FontWeight.w700,
                  height: 1.15,
                  color: _isDarkMode
                      ? _NeonTheme.textPrimaryDark
                      : _NeonTheme.textPrimaryLight,
                ),
              ),
            ),
          ],
        ),
      );
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        if (constraints.maxWidth < 500) {
          return Column(
            children: [
              Row(
                children: [
                  Expanded(child: buildTile(items[0])),
                  const SizedBox(width: 4),
                  Expanded(child: buildTile(items[1])),
                ],
              ),
              const SizedBox(height: 4),
              Row(
                children: [
                  Expanded(child: buildTile(items[2])),
                  const SizedBox(width: 4),
                  Expanded(child: buildTile(items[3])),
                ],
              ),
            ],
          );
        }

        return Row(
          children: items.map((item) => Expanded(child: buildTile(item))).toList(),
        );
      },
    );
  }

