  Widget _buildAiSafetyBriefCard() {
    final eval = routeEvaluations[selectedRouteIndex];
    final vehicle = currentVehicle.isNotEmpty ? currentVehicle : 'Car';
    final isNight = currentTravelTime == 'Evening' || currentTravelTime == 'Night';

    final reasons = <({IconData icon, Color color, String title, String detail})>[];

    // 1. Accident Risk Exposure
    if (accidentSafety != null || eval?.blackspots != null) {
      final isLow = (accidentSafety ?? 90.0) >= 80.0 || (eval?.blackspots.detectedBlackspots ?? 0) == 0;
      reasons.add((
        icon: Icons.shield_rounded,
        color: isLow ? const Color(0xff10B981) : const Color(0xffF59E0B),
        title: 'Accident Risk Exposure',
        detail: isLow
            ? 'Lower corridor accident exposure with zero critical blackspot intersections'
            : '${eval?.blackspots.detectedBlackspots ?? 0} accident hotspots monitored along route',
      ));
    } else {
      reasons.add((
        icon: Icons.shield_outlined,
        color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
        title: 'Accident Risk Exposure',
        detail: 'Accident history data unavailable for this sector',
      ));
    }

    // 2. Road Surface Quality
    if (roadSafety != null) {
      final isGood = roadSafety! >= 75.0;
      reasons.add((
        icon: Icons.add_road_rounded,
        color: isGood ? _NeonTheme.neonCyan : const Color(0xffF59E0B),
        title: 'Road Surface Quality',
        detail: isGood
            ? 'Engineered highway surface with high lane confidence and smooth pavement'
            : 'Moderate road surface quality detected — maintain caution',
      ));
    } else {
      reasons.add((
        icon: Icons.add_road_rounded,
        color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
        title: 'Road Surface Quality',
        detail: 'Road condition telemetry provisional — insufficient evidence',
      ));
    }

    // 3. Weather & Environmental Safety
    if (eval?.weather != null) {
      reasons.add((
        icon: Icons.cloud_done_rounded,
        color: const Color(0xff38BDF8),
        title: 'Weather & Visibility',
        detail: 'Suitable for travel: ${eval!.weather!.temperature.round()}°C with favorable conditions',
      ));
    } else {
      reasons.add((
        icon: Icons.cloud_off_rounded,
        color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
        title: 'Weather & Visibility',
        detail: 'Real-time weather station radar unavailable',
      ));
    }

    // 4. Lighting / Night Safety or Vehicle Profile
    if (isNight) {
      if (lightingSafety != null) {
        reasons.add((
          icon: Icons.lightbulb_rounded,
          color: const Color(0xffFBBF24),
          title: 'Night Travel Lighting',
          detail: '${lightingSafety!.round()}% lighting coverage along verified road sectors',
        ));
      } else {
        reasons.add((
          icon: Icons.nightlight_round,
          color: const Color(0xffF59E0B),
          title: 'Night Travel Caution',
          detail: 'Lighting telemetry unavailable for this route — drive with dipped beams',
        ));
      }
    } else {
      final String vehicleDetail;
      switch (vehicle) {
        case 'Bike':
          vehicleDetail = 'Optimized for two-wheelers: curve alerts and lane surface checked';
          break;
        case 'Bus':
          vehicleDetail = 'Commercial transit verified: broad turning radii and wide highway lanes';
          break;
        case 'Walk':
          vehicleDetail = 'Pedestrian safety check: continuous walkways and safe crossings';
          break;
        case 'Car':
        default:
          vehicleDetail = 'Divided multilane highway prioritized with wide overtaking margins';
          break;
      }
      reasons.add((
        icon: vehicle == 'Bike'
            ? Icons.two_wheeler_rounded
            : (vehicle == 'Bus'
                ? Icons.directions_bus_rounded
                : (vehicle == 'Walk' ? Icons.directions_walk_rounded : Icons.directions_car_rounded)),
        color: const Color(0xffA855F7),
        title: '$vehicle Safety Profile',
        detail: vehicleDetail,
      ));
    }

    // 5. Active Safety Mode Intelligence
    final safetyMode = _personalProfile.safetyMode;
    if (safetyMode == 'Women Safety') {
      final lightingText = lightingSafety != null
          ? '${lightingSafety!.round()}% lighting verified'
          : 'Lighting telemetry unavailable';
      reasons.add((
        icon: Icons.shield_rounded,
        color: const Color(0xffEC4899),
        title: 'Women Safety Intelligence',
        detail: '$lightingText. Emergency corridors prioritized. Note: Corridor evidence is partial — stay alert.',
      ));
    } else if (safetyMode == 'Senior Friendly') {
      final accessText = accessibilitySafety != null
          ? '${accessibilitySafety!.round()}% accessibility'
          : 'Smooth highway priority';
      reasons.add((
        icon: Icons.elderly_rounded,
        color: const Color(0xff38BDF8),
        title: 'Senior-Friendly Support',
        detail: '$accessText. Low fatigue route selected with direct hospital coverage and gentle curves.',
      ));
    } else if (safetyMode == 'Family Safety') {
      reasons.add((
        icon: Icons.family_restroom_rounded,
        color: const Color(0xff10B981),
        title: 'Family Safety Margin',
        detail: 'Maximized safety buffer: lower accident exposure, stable weather, and emergency readiness.',
      ));
    }

    // 6. Long Journey Highway Corridor Telemetry
    final isLongTrip = (eval?.safety.tripContext == 'long' || eval?.safety.tripContext == TripContextType.long.name) ||
        ((eval?.route.distance ?? 0.0) >= 60.0);
    final isExtendedTrip = !isLongTrip &&
        ((eval?.safety.tripContext == 'medium' || eval?.safety.tripContext == TripContextType.medium.name) ||
        ((eval?.route.distance ?? 0.0) >= 20.0));

    if (isLongTrip) {
      reasons.add((
        icon: Icons.alt_route_rounded,
        color: const Color(0xff6366F1),
        title: 'Long Highway Corridor Brief',
        detail: 'Sustained intercity highway monitoring with verified roadside support and navigation continuity.',
      ));
    } else if (isExtendedTrip) {
      reasons.add((
        icon: Icons.alt_route_rounded,
        color: const Color(0xff6366F1),
        title: 'Extended Journey Safety Brief',
        detail: 'Sub-district corridor guidance with verified road transitions and service access.',
      ));
    }

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: _isDarkMode ? const Color(0xff0B1930) : Colors.white,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: _isDarkMode ? const Color(0x3500D9FF) : const Color(0x350284C7),
          width: 1.2,
        ),
        boxShadow: _NeonTheme.cardShadow(_isDarkMode),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          Row(
            children: [
              Container(
                width: 28,
                height: 28,
                decoration: BoxDecoration(
                  gradient: const LinearGradient(
                    colors: [Color(0xff8B5CF6), Color(0xff0D5BD8)],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  ),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: const Center(
                  child: Icon(Icons.psychology_rounded, color: Colors.white, size: 16),
                ),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      'AI Safety Brief',
                      style: TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w800,
                        color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                      ),
                    ),
                    Text(
                      'Why SafeRoute recommends Route ${selectedRouteIndex + 1}${safetyMode != 'General' ? ' · $safetyMode' : ''}',
                      style: TextStyle(
                        fontSize: 9.5,
                        color: _isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight,
                      ),
                    ),
                  ],
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 2.5),
                decoration: BoxDecoration(
                  color: const Color(0xff8B5CF6).withValues(alpha: 0.16),
                  borderRadius: BorderRadius.circular(6),
                  border: Border.all(
                    color: const Color(0xff8B5CF6).withValues(alpha: 0.4),
                    width: 0.8,
                  ),
                ),
                child: const Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(Icons.auto_awesome, size: 10, color: Color(0xffA78BFA)),
                    SizedBox(width: 3),
                    Text(
                      'AI ANALYSED',
                      style: TextStyle(
                        fontSize: 8.5,
                        fontWeight: FontWeight.w800,
                        letterSpacing: 0.4,
                        color: Color(0xffA78BFA),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
          for (var i = 0; i < reasons.length; i++) ...[
            if (i > 0) const SizedBox(height: 8),
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Container(
                  margin: const EdgeInsets.only(top: 2),
                  width: 20,
                  height: 20,
                  decoration: BoxDecoration(
                    color: reasons[i].color.withValues(alpha: 0.14),
                    borderRadius: BorderRadius.circular(5),
                  ),
                  child: Center(
                    child: Icon(reasons[i].icon, size: 12, color: reasons[i].color),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        reasons[i].title,
                        style: TextStyle(
                          fontSize: 10.5,
                          fontWeight: FontWeight.w700,
                          color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                        ),
                      ),
                      const SizedBox(height: 1.5),
                      Text(
                        reasons[i].detail,
                        style: TextStyle(
                          fontSize: 9.5,
                          height: 1.25,
                          color: _isDarkMode
                              ? _NeonTheme.textSecondaryDark
                              : _NeonTheme.textSecondaryLight,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ],
          if (eval?.safety != null) ...[
            const SizedBox(height: 10),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
              decoration: BoxDecoration(
                color: _isDarkMode ? const Color(0xff061325) : const Color(0xffF1F5F9),
                borderRadius: BorderRadius.circular(8),
                border: Border.all(
                  color: _isDarkMode ? const Color(0x2000D9FF) : const Color(0x200284C7),
                  width: 0.8,
                ),
              ),
              child: Row(
                children: [
                  Icon(
                    Icons.info_outline_rounded,
                    size: 13,
                    color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      '${eval!.safety.evidenceSummary} · Verified real-world telemetry only',
                      style: TextStyle(
                        fontSize: 9.0,
                        color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
                        fontStyle: FontStyle.italic,
                      ),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ],
      ),
    );
  }

  Widget _buildSafetyRiskTimelineCard() {
    final origin = fromController.text.isNotEmpty ? fromController.text : 'Start Location';
    final destination = toController.text.isNotEmpty ? toController.text : 'Destination';
    final eval = routeEvaluations[selectedRouteIndex];
    final hasBlackspots = (eval?.blackspots.detectedBlackspots ?? 0) > 0;
    final isLowRisk = (accidentSafety ?? 90.0) >= 80.0 || (eval?.blackspots.detectedBlackspots ?? 0) == 0;

    final steps = [
      (
        label: origin,
        sub: 'Start',
        status: 'Low Risk',
        color: const Color(0xff00E59B),
        icon: Icons.trip_origin_rounded,
      ),
      (
        label: 'Mid Route',
        sub: 'Transit',
        status: isLowRisk ? 'Low Risk' : 'Moderate Risk',
        color: isLowRisk ? const Color(0xff00E59B) : const Color(0xffFFC107),
        icon: Icons.alt_route_rounded,
      ),
      (
        label: hasBlackspots ? 'High Risk Zone' : 'Clear Sector',
        sub: 'Corridor',
        status: hasBlackspots ? 'Caution' : 'Safe',
        color: hasBlackspots ? const Color(0xffFF3D5A) : const Color(0xff00E59B),
        icon: hasBlackspots ? Icons.warning_amber_rounded : Icons.shield_rounded,
      ),
      (
        label: 'Safe',
        sub: 'Sector',
        status: 'Clear',
        color: const Color(0xff00E59B),
        icon: Icons.check_circle_rounded,
      ),
      (
        label: destination,
        sub: 'Destination',
        status: 'Verified',
        color: const Color(0xff00D9FF),
        icon: Icons.location_on_rounded,
      ),
    ];

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: _isDarkMode ? const Color(0xff0B1930) : Colors.white,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: _isDarkMode ? const Color(0x3500D9FF) : const Color(0x350284C7),
          width: 1.2,
        ),
        boxShadow: _NeonTheme.cardShadow(_isDarkMode),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          Row(
            children: [
              Container(
                width: 28,
                height: 28,
                decoration: BoxDecoration(
                  gradient: const LinearGradient(
                    colors: [Color(0xff00D9FF), Color(0xff00E59B)],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  ),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: const Center(
                  child: Icon(Icons.shield_rounded, color: Colors.white, size: 15),
                ),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      'Safety Risk Timeline',
                      style: TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w800,
                        color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                      ),
                    ),
                    Text(
                      'Corridor checkpoints • Real route telemetry',
                      style: TextStyle(
                        fontSize: 9.5,
                        color: _isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight,
                      ),
