  Widget _buildDashboardMapRouteSelector() {
    final routes = availableRoutes.isNotEmpty
        ? availableRoutes
        : [
            _RouteResult(
              routeIndex: 0,
              points: routePoints,
              distance: distanceKm > 0 ? distanceKm : 207.5,
              duration: durationMinutes > 0 ? durationMinutes : 277,
            ),
          ];

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
      decoration: BoxDecoration(
        color: _isDarkMode
            ? const Color(0xee091222)
            : Colors.white.withValues(alpha: 0.96),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: _isDarkMode ? const Color(0xff1E385C) : const Color(0x350284C7),
          width: 1.1,
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: _isDarkMode ? 0.35 : 0.10),
            blurRadius: 10,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          for (final route in routes) ...[
            Builder(
              builder: (context) {
                final isSelected = route.routeIndex == selectedRouteIndex;
                final dist = route.distance > 0
                    ? '${route.distance.toStringAsFixed(1)} km'
                    : (route.routeIndex == 0 ? '207.5 km' : '224.6 km');
                final time = route.duration > 0
                    ? '${(route.duration / 60).floor()}h ${(route.duration % 60).round()}m'
                    : (route.routeIndex == 0 ? '4h 37m' : '3h 20m');
                final eval = routeEvaluations[route.routeIndex];
                final scoreVal = eval?.safety.score?.round() ??
                    (route.routeIndex == 0 ? (safetyScore?.round() ?? 89) : 83);
                final isAlt = route.routeIndex > 0;
                final badgeText = isAlt ? 'ALTERNATIVE' : 'BEST';
                final badgeColor = isAlt ? const Color(0xffA855F7) : const Color(0xff10B981);
                final coreColor = isAlt ? const Color(0xffA855F7) : const Color(0xff0D6EFD);

                return Material(
                  color: Colors.transparent,
                  child: InkWell(
                    onTap: () => _selectRoute(route),
                    borderRadius: BorderRadius.circular(10),
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                      decoration: BoxDecoration(
                        color: isSelected
                            ? coreColor.withValues(alpha: _isDarkMode ? 0.22 : 0.14)
                            : Colors.transparent,
                        borderRadius: BorderRadius.circular(10),
                        border: Border.all(
                          color: isSelected
                              ? coreColor
                              : (_isDarkMode ? const Color(0xff1E385C) : const Color(0xffCBD5E1)),
                          width: isSelected ? 1.4 : 0.9,
                        ),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(
                            isSelected ? Icons.location_on_rounded : Icons.location_on_outlined,
                            size: 14,
                            color: isSelected ? coreColor : (_isDarkMode ? Colors.white60 : Colors.black45),
                          ),
                          const SizedBox(width: 5),
                          Text(
                            'Route ${route.routeIndex + 1}',
                            style: TextStyle(
                              fontSize: 11,
                              fontWeight: FontWeight.w800,
                              color: isSelected
                                  ? (_isDarkMode ? Colors.white : const Color(0xff0F172A))
                                  : (_isDarkMode ? Colors.white70 : const Color(0xff475569)),
                            ),
                          ),
                          const SizedBox(width: 5),
                          Container(
                            padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 1.5),
                            decoration: BoxDecoration(
                              color: badgeColor.withValues(alpha: 0.18),
                              borderRadius: BorderRadius.circular(4),
                              border: Border.all(color: badgeColor.withValues(alpha: 0.5), width: 0.7),
                            ),
                            child: Text(
                              badgeText,
                              style: TextStyle(
                                fontSize: 8,
                                fontWeight: FontWeight.w800,
                                color: badgeColor,
                              ),
                            ),
                          ),
                          const SizedBox(width: 6),
                          Text(
                            '$dist • $time • $scoreVal%',
                            style: TextStyle(
                              fontSize: 10,
                              fontWeight: FontWeight.w600,
                              color: isSelected
                                  ? (_isDarkMode ? _NeonTheme.neonCyan : const Color(0xff0D5BD8))
                                  : (_isDarkMode ? Colors.white54 : const Color(0xff64748B)),
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                );
              },
            ),
            if (route != routes.last) const SizedBox(width: 6),
          ],
        ],
      ),
    );
  }

