  Widget _buildMapDashboard(BuildContext context, {required bool compact}) {
    return LayoutBuilder(
      builder: (context, constraints) {
        // Desktop layout (width >= 1050):
        // Balanced 2-column dashboard:
        // Left Column (flex 63): Plan Card + Hero Map + Cockpit Row (Smart Route Insights & Route Facilities)
        // Right Column (flex 37): Route Recommendation / Summary + Personal Safety Profile & Platform Features
        if (constraints.maxWidth >= 1050) {
          return SingleChildScrollView(
            padding: const EdgeInsets.fromLTRB(18, 14, 18, 28),
            child: Center(
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 1650),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    // Top: Plan Your Safe Journey with Cinematic Road Background
                    _StaggeredEntrance(
                      delayMs: 0,
                      slideOffset: const Offset(0, 16.0),
                      child: _buildPlanYourSafeJourneyCard(),
                    ),
                    const SizedBox(height: 14),
                    // MAIN CONTENT ROW: Left Map (flex 62) + Right Route Summary (flex 38)
                    Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Expanded(
                          flex: 62,
                          child: SizedBox(
                            height: 520,
                            child: _StaggeredEntrance(
                              trigger: _routeSearchGeneration,
                              delayMs: 70,
                              animateScale: true,
                              child: _buildDashboardMapCard(),
                            ),
                          ),
                        ),
                        const SizedBox(width: 14),
                        Expanded(
                          flex: 38,
                          child: _StaggeredEntrance(
                            trigger: _routeSearchGeneration,
                            delayMs: 120,
                            slideOffset: const Offset(0, 16.0),
                            child: _buildRouteSummaryCard(),
                          ),
