              } else if (_personalProfile.safetyMode == 'Senior Friendly') {
                whyPoint1 = accessibilitySafety != null
                    ? 'Higher accessibility confidence'
                    : 'Senior-Friendly smooth corridor';
              } else if (_personalProfile.safetyMode == 'Family Safety') {
                whyPoint1 = 'Stronger family safety margin';
              } else if (_effectivePriority == 'Fastest') {
