                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  ConstrainedBox(
                    constraints: const BoxConstraints(maxHeight: 290),
                    child: LayoutBuilder(
                      builder: (context, constraints) {
                        final isWide = constraints.maxWidth >= 720;
                        final isMedium = constraints.maxWidth >= 480;
                        final crossAxisCount = isWide ? 3 : (isMedium ? 2 : 1);

                        if (crossAxisCount == 1) {
                          return ListView.separated(
                            shrinkWrap: true,
                            itemCount: displayed.length,
                            separatorBuilder: (_, _) =>
                                const SizedBox(height: 8),
                            itemBuilder: (context, index) =>
                                _StaggeredEntrance(
                                  key: ValueKey('fac_${displayed[index].id}_$_facilitySearchGeneration'),
                                  delayMs: (index.clamp(0, 6)) * 50,
                                  animateScale: true,
                                  trigger: _facilitySearchGeneration,
                                  child: _buildFacilityRowCard(displayed[index]),
                                ),
