                              _StaggeredEntrance(
                                key: ValueKey('fac_grid_${displayed[index].id}_$_facilitySearchGeneration'),
                                delayMs: (index.clamp(0, 6)) * 50,
                                animateScale: true,
                                trigger: _facilitySearchGeneration,
                                child: _buildFacilityGridCard(displayed[index]),
