  // ignore: unused_element
  Widget _buildPersonalSafetyProfileSummaryCard() {
    final eval = routeEvaluations[selectedRouteIndex];
    final hasEval = eval != null;
    final match = hasEval && _personalProfile.isConfigured
        ? PreferenceMatchEvaluator.evaluate(
            evaluation: eval,
            profile: _personalProfile,
            isDay: _isDaytimeTravel(currentTravelTime),
          )
        : null;

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: _isDarkMode ? _NeonTheme.cardDark : _NeonTheme.cardLight,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(
          color: _isDarkMode ? _NeonTheme.cyanBorder : const Color(0x350284C7),
          width: 1.2,
        ),
        boxShadow: _NeonTheme.cardShadow(_isDarkMode),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              const Icon(
                Icons.person_pin_rounded,
                color: _NeonTheme.neonCyan,
                size: 18,
              ),
              const SizedBox(width: 8),
              Text(
                'PERSONAL SAFETY PROFILE',
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 0.8,
                  color: _isDarkMode
                      ? _NeonTheme.neonCyan
                      : _NeonTheme.electricBlue,
                ),
              ),
              const Spacer(),
              if (match != null)
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 6,
                    vertical: 2,
                  ),
                  decoration: BoxDecoration(
                    color: match.matchColor.withValues(alpha: 0.18),
                    borderRadius: BorderRadius.circular(4),
                  ),
                  child: Text(
                    '${match.matchPercentage.round()}% MATCH',
                    style: TextStyle(
                      fontSize: 8.5,
                      fontWeight: FontWeight.w800,
                      color: match.matchColor,
                    ),
                  ),
                ),
            ],
          ),
          const SizedBox(height: 8),
          Row(
            children: [
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
                decoration: BoxDecoration(
                  color: _NeonTheme.neonCyan.withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(6),
                ),
                child: Text(
                  '$currentVehicle · $currentTravelTime · $_effectivePriority',
                  style: const TextStyle(
                    fontSize: 10.5,
                    fontWeight: FontWeight.w700,
                    color: _NeonTheme.neonCyan,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 6),
          Text(
            _personalProfile.isConfigured
                ? 'Route safety weights dynamically personalized to your preferences.'
                : 'Default safety weights applied. Configure your personal profile for custom weighting.',
            style: TextStyle(
              fontSize: 10.5,
              color: _isDarkMode
                  ? _NeonTheme.textSecondaryDark
                  : _NeonTheme.textSecondaryLight,
            ),
          ),
          const SizedBox(height: 10),
          Align(
            alignment: Alignment.centerLeft,
            child: OutlinedButton.icon(
              onPressed: _openSafetyProfileDialog,
              icon: const Icon(Icons.tune_rounded, size: 14),
              label: Text(
                _personalProfile.isConfigured
                    ? (_isTamil ? 'சுயவிவரத்தை மாற்றுக' : 'Manage Preferences')
                    : (_isTamil ? 'சுயவிவரத்தை அமைக்கவும்' : 'Setup Profile'),
                style: const TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w700,
                ),
              ),
              style: OutlinedButton.styleFrom(
                foregroundColor: _NeonTheme.neonCyan,
                side: const BorderSide(color: _NeonTheme.neonCyan, width: 1),
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 6,
                ),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(8),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  void _showSafetyEvidenceDialog() {
    final eval = routeEvaluations[selectedRouteIndex];
    final factors = eval?.safety.factors ?? [];

    showDialog<void>(
      context: context,
      barrierDismissible: true,
      builder: (dialogContext) {
        return AlertDialog(
          backgroundColor: _isDarkMode ? const Color(0xff0B1930) : Colors.white,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(18),
            side: BorderSide(
              color: _isDarkMode ? const Color(0x3500D9FF) : const Color(0x350284C7),
              width: 1.2,
            ),
          ),
          title: Row(
            children: [
              Container(
                padding: const EdgeInsets.all(6),
                decoration: BoxDecoration(
                  gradient: const LinearGradient(
                    colors: [Color(0xff00D9FF), Color(0xff168BFF)],
                  ),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: const Icon(Icons.verified_user_rounded, color: Colors.white, size: 18),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      'Verified Safety Evidence',
                      style: TextStyle(
                        fontSize: 15,
                        fontWeight: FontWeight.w800,
                        color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                      ),
                    ),
                    Text(
                      'Deterministic audit of route telemetry',
                      style: TextStyle(
                        fontSize: 9.5,
                        color: _isDarkMode ? const Color(0xff91A4BD) : const Color(0xff64748B),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          content: SizedBox(
            width: 580,
            child: SingleChildScrollView(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
                    decoration: BoxDecoration(
                      color: _isDarkMode ? const Color(0xff08152B) : const Color(0xffF1F5F9),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(color: const Color(0x2500D9FF)),
                    ),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Text(
                          'Personalized: ${_personalProfile.safetyMode}',
                          style: const TextStyle(fontSize: 10, fontWeight: FontWeight.w800, color: Color(0xff00D9FF)),
                        ),
                        Text(
                          eval?.safety.evidenceSummary ?? 'Verified live data',
                          style: TextStyle(
                            fontSize: 9.5,
                            color: _isDarkMode ? const Color(0xff91A4BD) : const Color(0xff475569),
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 12),
                  for (final f in factors) ...[
                    Container(
                      margin: const EdgeInsets.only(bottom: 8),
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                        color: _isDarkMode ? const Color(0xff10223D) : const Color(0xffF8FAFC),
                        borderRadius: BorderRadius.circular(10),
                        border: Border.all(
                          color: _isDarkMode ? const Color(0x2000D9FF) : const Color(0x200284C7),
                        ),
                      ),
                      child: Row(
                        crossAxisAlignment: CrossAxisAlignment.center,
                        children: [
                          Icon(f.icon, size: 20, color: f.score != null ? const Color(0xff00D9FF) : const Color(0xff91A4BD)),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Row(
                                  children: [
                                    Text(
                                      f.title,
                                      style: TextStyle(
                                        fontSize: 12,
                                        fontWeight: FontWeight.w800,
                                        color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                                      ),
                                    ),
                                    const SizedBox(width: 6),
