  Marker _buildFacilityMarker(_Facility facility) {
    final category = _resolveCategoryForFacility(facility);
    final isSelected = _selectedFacility?.id == facility.id;
    final size = isSelected ? 36.0 : 28.0;
    final iconSize = isSelected ? 18.0 : 13.0;

    return Marker(
      key: ValueKey('facility_poi_${facility.id}'),
      point: LatLng(facility.lat, facility.lon),
      width: size + 8.0,
      height: size + 8.0,
      alignment: Alignment.center,
      child: MouseRegion(
        cursor: SystemMouseCursors.click,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () {
            setState(() => _selectedFacility = facility);
            if (_mapReady) {
              mapController.move(
                LatLng(facility.lat, facility.lon),
                mapController.camera.zoom.clamp(12.5, 16.0),
              );
            }
            _showFacilityDetails(facility);
          },
          child: Tooltip(
            message: _facilityMarkerTooltip(facility, category),
            waitDuration: const Duration(milliseconds: 300),
            child: Center(
              child: TweenAnimationBuilder<double>(
                key: ValueKey('fac_marker_${facility.id}_$_facilitySearchGeneration'),
                tween: Tween<double>(begin: 0.6, end: 1.0),
                duration: const Duration(milliseconds: 250),
                curve: Curves.easeOutBack,
                builder: (context, scale, child) {
                  return Transform.scale(
                    scale: scale,
                    child: child,
                  );
                },
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 200),
                  width: size,
                  height: size,
                  decoration: BoxDecoration(
                    color: category.color,
                    shape: BoxShape.circle,
                    border: Border.all(
                      color: isSelected ? _NeonTheme.neonCyan : Colors.white,
                      width: isSelected ? 2.6 : 2.0,
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: isSelected
                            ? _NeonTheme.neonCyan.withValues(alpha: 0.90)
                            : category.color.withValues(alpha: 0.65),
                        blurRadius: isSelected ? 12 : 6,
                        spreadRadius: isSelected ? 2 : 0.5,
                        offset: const Offset(0, 1.5),
                      ),
                    ],
                  ),
                  child: Center(
                    child: Icon(
                      category.icon,
                      color: Colors.white,
                      size: iconSize,
                    ),
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _mapView({
    bool isDashboardView = false,
    bool isLiveNavigation = false,
  }) {
    final displayedFacilities = _displayedFacilities;
    final facilityMarkers = [
      for (final facility in displayedFacilities)
        _buildFacilityMarker(facility),
      if (_focusedNearbyPlace != null)
        Marker(
          point: LatLng(
            _focusedNearbyPlace!.latitude,
            _focusedNearbyPlace!.longitude,
          ),
          width: 46,
          height: 46,
          child: Tooltip(
            message: _focusedNearbyPlace!.name,
            child: Container(
              decoration: BoxDecoration(
                color: _focusedNearbyPlace!.categoryColor,
                shape: BoxShape.circle,
                border: Border.all(color: Colors.white, width: 2.8),
                boxShadow: [
                  BoxShadow(
                    color: _focusedNearbyPlace!.categoryColor.withValues(
                      alpha: 0.8,
                    ),
                    blurRadius: 14,
                    spreadRadius: 2,
                  ),
                ],
              ),
              child: Center(
                child: Icon(
                  _focusedNearbyPlace!.categoryIcon,
                  color: Colors.white,
                  size: 22,
                ),
              ),
            ),
          ),
        ),
    ];

    return Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(22),
        border: Border.all(
          color: _isDarkMode ? _NeonTheme.cyanBorder : const Color(0x350284C7),
          width: 1.2,
        ),
        boxShadow: _NeonTheme.cardShadow(_isDarkMode),
      ),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(22),
        child: Stack(
          fit: StackFit.expand,
          children: [
            FlutterMap(
              mapController: mapController,
              options: MapOptions(
                initialCenter: (isLiveNavigation && currentPosition != null)
                    ? LatLng(
                        currentPosition!.latitude,
                        currentPosition!.longitude,
                      )
                    : (routePoints.isNotEmpty
                        ? routePoints.first
                        : const LatLng(11.0168, 76.9558)),
                initialZoom: isLiveNavigation ? 15.5 : 10,
                onMapReady: () {
                  _mapReady = true;
                  final position = currentPosition;
                  if (isLiveNavigation && position != null) {
                    _centerMapOnPosition(position);
                  } else if (routePoints.isNotEmpty) {
                    WidgetsBinding.instance.addPostFrameCallback((_) {
                      if (mounted && _mapReady && routePoints.isNotEmpty) {
                        _fitRoute(routePoints);
                      }
                    });
                  }
                  if (_followMe && position != null) {
                    _centerMapOnPosition(position);
                  }
                },
                onMapEvent: (event) {
                  if (_followMe &&
                      event is MapEventMoveStart &&
                      event.source == MapEventSource.dragStart) {
                    setState(() => _followMe = false);
                  }
                },
                onTap: (tapPosition, point) {
                  // Check if user tapped near an alternative route to switch to it
                  if (availableRoutes.length > 1) {
                    for (final route in availableRoutes) {
                      if (route.routeIndex != selectedRouteIndex) {
                        final d = _distanceFromCoordinatesToRoute(point, route.points);
                        if (d != null && d <= 500.0) {
                          _selectRoute(route);
                          return;
                        }
                      }
                    }
                  }

                  if (_routeRiskSections.isEmpty) return;
                  _RouteRiskSection? tapped;
                  var minD = double.infinity;
                  for (final sec in _routeRiskSections) {
                    final d =
                        _distanceFromCoordinatesToRoute(point, sec.points);
                    if (d != null && d < minD) {
                      minD = d;
                      tapped = sec;
                    }
                  }
                  if (minD <= 350.0 && tapped != null) {
                    setState(() {
                      _selectedRiskSection = tapped;
                    });
                  } else if (_selectedRiskSection != null) {
                    setState(() {
                      _selectedRiskSection = null;
                    });
                  }
                },
              ),
              children: [
                TileLayer(
                  urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
                  userAgentPackageName: 'saferoute_tn',
                ),
                // Clean road-like solid route visualization with progressive entrance drawing
                if (availableRoutes.length > 1)
                  TweenAnimationBuilder<double>(
                    key: ValueKey('route_draw_${selectedRouteIndex}_${availableRoutes.length}_${routePoints.length}_$_routeSearchGeneration'),
                    tween: Tween<double>(begin: 0.0, end: 1.0),
                    duration: const Duration(milliseconds: 800),
                    curve: Curves.easeOutCubic,
                    builder: (context, drawProgress, _) {
                      final bool isDone = isLiveNavigation || drawProgress >= 0.99;
                      List<LatLng> slice(List<LatLng> pts, double progress) {
                        if (isDone || pts.length < 2) return pts;
                        final count = ((pts.length - 1) * progress).round() + 1;
                        return pts.sublist(0, count.clamp(2, pts.length));
                      }

                      // Selected route drawn according to drawProgress
                      final selRoute = availableRoutes.firstWhere(
                        (r) => r.routeIndex == selectedRouteIndex,
                        orElse: () => availableRoutes.first,
                      );
                      final selPoints = slice(selRoute.points, drawProgress);

                      // Alternative routes (delayed entrance - starts at 30% progress)
                      final altProgress = drawProgress <= 0.30
                          ? 0.0
                          : ((drawProgress - 0.30) / 0.70).clamp(0.0, 1.0);

                      return PolylineLayer(
                        polylines: [
                          // 1. Unselected routes rendered first (underneath, fading in)
                          if (altProgress > 0.0 || isDone)
                            for (final route in availableRoutes)
                              if (route.routeIndex != selectedRouteIndex) ...[
                                // Dark underlay casing fading in
                                Polyline(
                                  points: isDone ? route.points : slice(route.points, altProgress),
                                  strokeWidth: 6.0,
                                  color: const Color(0xff0F172A).withValues(alpha: isDone ? 0.45 : (0.45 * altProgress)),
                                ),
                                // Solid core line fading from 0 -> 1, visually subordinate
                                Polyline(
                                  points: isDone ? route.points : slice(route.points, altProgress),
                                  strokeWidth: 4.0,
                                  color: _getRouteUnselectedColor(route.routeIndex)
                                      .withValues(alpha: isDone ? 0.65 : (0.65 * altProgress)),
                                ),
                              ],
                          // 2. Selected route rendered on top (thicker, brighter)
                          if (availableRoutes.any(
                            (r) => r.routeIndex == selectedRouteIndex,
                          )) ...[
                            if (_routeRiskSections.isNotEmpty) ...[
                              if (_selectedRiskSection != null)
                                Polyline(
                                  points: _selectedRiskSection!.points,
                                  strokeWidth: 12,
                                  color: Colors.white.withValues(alpha: 0.45),
                                ),
                              for (final sec in _routeRiskSections) ...[
                                Polyline(
                                  points: sec.points,
                                  strokeWidth: 8.5,
                                  color: sec.riskLevel.color.withValues(
                                    alpha: 0.28,
                                  ),
                                ),
                                Polyline(
                                  points: sec.points,
                                  strokeWidth: 5.5,
                                  color: sec.riskLevel.color,
                                ),
                              ],
                            ] else ...[
                              // Subtle ambient cyan glow underlay for selected route
                              Polyline(
                                points: selPoints,
                                strokeWidth: 12.0,
                                color: const Color(0xff00F2FE).withValues(alpha: 0.20 * drawProgress),
                              ),
                              // Underlay casing for selected route
                              Polyline(
                                points: selPoints,
                                strokeWidth: 8.5,
                                color: const Color(0xff0B132B).withValues(alpha: 0.85),
                              ),
                              // Vibrant solid core with distinct route color
                              Polyline(
                                points: selPoints,
                                strokeWidth: 5.5,
                                color: _getRouteCoreColor(selectedRouteIndex),
                              ),
                              // Subtle moving light pulse at drawing head
                              if (!isDone && selPoints.length >= 2)
                                Polyline(
                                  points: [selPoints[selPoints.length - 2], selPoints.last],
                                  strokeWidth: 8.5,
                                  color: Colors.white.withValues(alpha: 0.85),
                                ),
                            ],
                          ],
                        ],
                      );
                    },
                  )
                else if (routePoints.isNotEmpty)
                  TweenAnimationBuilder<double>(
                    key: ValueKey('single_route_draw_${routePoints.length}_$_routeSearchGeneration'),
                    tween: Tween<double>(begin: 0.0, end: 1.0),
                    duration: const Duration(milliseconds: 800),
                    curve: Curves.easeOutCubic,
                    builder: (context, drawProgress, _) {
                      final bool isDone = isLiveNavigation || drawProgress >= 0.99;
                      List<LatLng> slice(List<LatLng> pts) {
                        if (isDone || pts.length < 2) return pts;
                        final count = ((pts.length - 1) * drawProgress).round() + 1;
                        return pts.sublist(0, count.clamp(2, pts.length));
                      }
                      final animatedPoints = slice(routePoints);

                      return PolylineLayer(
                        polylines: [
                          if (_routeRiskSections.isNotEmpty) ...[
                            if (_selectedRiskSection != null)
                              Polyline(
                                points: _selectedRiskSection!.points,
                                strokeWidth: 12,
                                color: Colors.white.withValues(alpha: 0.45),
                              ),
                            for (final sec in _routeRiskSections) ...[
                              Polyline(
                                points: sec.points,
                                strokeWidth: 8.5,
                                color: sec.riskLevel.color.withValues(alpha: 0.28),
                              ),
                              Polyline(
                                points: sec.points,
                                strokeWidth: 5.5,
                                color: sec.riskLevel.color,
                              ),
                            ],
                          ] else ...[
                            // Subtle ambient cyber-glow underlay
                            Polyline(
                              points: animatedPoints,
                              strokeWidth: 12.0,
                              color: const Color(0xff00E5FF).withValues(alpha: 0.22),
                            ),
                            Polyline(
                              points: animatedPoints,
                              strokeWidth: 8.5,
                              color: const Color(0xff0B132B).withValues(alpha: 0.85),
                            ),
                            Polyline(
                              points: animatedPoints,
                              strokeWidth: 5.5,
                              color: const Color(0xff00E5FF),
                            ),
                            // Subtle moving light pulse at drawing head
                            if (!isDone && animatedPoints.length >= 2)
                              Polyline(
                                points: [animatedPoints[animatedPoints.length - 2], animatedPoints.last],
                                strokeWidth: 8.5,
                                color: Colors.white.withValues(alpha: 0.85),
                              ),
                          ],
                        ],
                      );
                    },
                  ),
                // Real OSM Facility markers
                if ((_selectedFacilityCategories.isNotEmpty || _selectedFacilityGroups.isNotEmpty) &&
                    facilityMarkers.isNotEmpty)
                  MarkerLayer(markers: facilityMarkers),
                // Current position marker
                if (currentPosition != null)
                  MarkerLayer(
                    markers: [
                      Marker(
                        point: LatLng(
                          currentPosition!.latitude,
                          currentPosition!.longitude,
                        ),
                        width: 48,
                        height: 48,
                        child: _navigationActive
                            ? _buildNavigationVehicleMarker(currentPosition!)
                            : _PulsingGpsMarker(isDarkMode: _isDarkMode),
                      ),
                    ],
                  ),
                // Start & End markers
                if (startLocation != null && endLocation != null)
                  MarkerLayer(
                    markers: [
                      Marker(
                        point: LatLng(startLocation!.lat, startLocation!.lon),
                        width: 175,
                        height: 42,
                        alignment: const Alignment(-0.817, 0.0),
                        child: TweenAnimationBuilder<double>(
                          key: ValueKey('start_marker_pop_$_routeSearchGeneration'),
                          tween: Tween<double>(begin: 0.65, end: 1.0),
                          duration: const Duration(milliseconds: 360),
                          curve: Curves.easeOutBack,
                          builder: (context, scale, child) => Transform.scale(
                            scale: scale,
                            child: child,
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Container(
                                width: 32,
