  void _openSafetyProfileDialog() {
    RouteEvaluation? activeEval;
    if (_hasSearchedRoute) {
      activeEval = routeEvaluations[selectedRouteIndex];
    }
    final isDay = _isDaytimeTravel(currentTravelTime);

    showDialog<void>(
      context: context,
      barrierDismissible: true,
      builder: (dialogContext) {
        return PersonalSafetyProfileDialog(
          isDarkMode: _isDarkMode,
          activeRouteEvaluation: activeEval,
          isDay: isDay,
          onProfileSaved: () async {
            await _loadPersonalSafetyProfile();
          },
          onApplyVehicleMode: (appliedVehicle) {
            if (mounted) {
              setState(() {
                currentVehicle = appliedVehicle;
              });
            }
          },
        );
      },
    );
  }

  void _openEmergencyDialog() {
    final routeOrigin = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : (currentFrom.trim().isNotEmpty ? currentFrom.trim() : null);
    final routeDestination = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : (currentTo.trim().isNotEmpty ? currentTo.trim() : null);

    showDialog<void>(
      context: context,
      barrierDismissible: true,
      builder: (dialogContext) {
        return EmergencyAssistanceDialog(
          isDarkMode: _isDarkMode,
          routeOrigin: routeOrigin,
          routeDestination: routeDestination,
          vehicleMode: currentVehicle,
          travelTimeMode: currentTravelTime,
          distanceKm: _hasSearchedRoute ? distanceKm : null,
          durationMinutes: _hasSearchedRoute ? durationMinutes : null,
          safetyScore: _hasSearchedRoute ? safetyScore : null,
          personalizedSafetyResult: _hasSearchedRoute
              ? personalizedSafetyResult
              : null,
          nearbyFacilities: facilities,
          onOpenNearbyPlaces: () => _openNearbyPlacesTab(emergencyMode: true),
          formatDurationFn: (mins) {
            final totalMinutes = mins.round();
            final hours = totalMinutes ~/ 60;
            final remainingMinutes = totalMinutes % 60;
            if (hours > 0) {
              return '${hours}h ${remainingMinutes}m';
            }
            return '${remainingMinutes}m';
          },
        );
      },
    );
  }

  void _openRiskForecastDialog({int? routeIndex}) {
    final targetIndex = routeIndex ?? selectedRouteIndex;

    final fromText = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : (currentFrom.trim().isNotEmpty ? currentFrom.trim() : null);
    final toText = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : (currentTo.trim().isNotEmpty ? currentTo.trim() : null);

    RouteEvaluation? eval;
    if (_hasSearchedRoute) {
      if (routeEvaluations.containsKey(targetIndex)) {
        eval = routeEvaluations[targetIndex];
      } else {
        final selectedRoute = (targetIndex < availableRoutes.length)
            ? availableRoutes[targetIndex]
            : RouteResult(
                points: routePoints,
                distance: distanceKm,
                duration: durationMinutes * 60,
                routeIndex: targetIndex,
              );
        eval = RouteEvaluation(
          route: selectedRoute,
          roadSegments: selectedOsmRoadSegments,
          safety: personalizedSafetyResult,
          weather: weather,
          blackspots: BlackspotRouteAssessment(
            clearSampleScore: null,
            detectedBlackspots: blackspotDetails != null ? 1 : 0,
            successfulSamples: 0,
            segmentsChecked: 0,
            verifiedRecordCount: 0,
            segmentResults: const [],
            unavailableReason: null,
          ),
          traffic: routeEvaluations[selectedRouteIndex]?.traffic,
        );
      }
    }

    showDialog<void>(
      context: context,
      barrierDismissible: true,
      builder: (dialogContext) {
        return SmartRouteRiskForecastDialog(
          isDarkMode: _isDarkMode,
          routeOrigin: fromText,
          routeDestination: toText,
          vehicleMode: currentVehicle,
          travelTimeMode: currentTravelTime,
          distanceKm: _hasSearchedRoute ? distanceKm : null,
          durationMinutes: _hasSearchedRoute ? durationMinutes : null,
          safetyScore: _hasSearchedRoute
              ? (safetyScore ?? eval?.safety.score)
              : null,
          routeEvaluation: eval,
          personalProfile: _personalProfile,
          formatDurationFn: (mins) {
            final totalMinutes = mins.round();
            final hours = totalMinutes ~/ 60;
            final remainingMinutes = totalMinutes % 60;
            if (hours > 0) {
              return '${hours}h ${remainingMinutes}m';
            }
            return '${remainingMinutes}m';
          },
        );
      },
    );
  }

