  void _showWhyThisRouteDialog({int? routeIndex}) {
    final targetIndex = routeIndex ?? selectedRouteIndex;

    if (routeEvaluations.isEmpty &&
        personalizedSafetyResult.factors.isEmpty &&
        !_hasSearchedRoute) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please calculate a route first to view safety explanations.',
          ),
          backgroundColor: _NeonTheme.electricBlue,
        ),
      );
      return;
    }

    final fromText = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : (currentFrom.trim().isNotEmpty ? currentFrom.trim() : 'Origin');
    final toText = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : (currentTo.trim().isNotEmpty ? currentTo.trim() : 'Destination');

    var evals = Map<int, _RouteEvaluation>.from(routeEvaluations);
    if (!evals.containsKey(targetIndex)) {
      final selectedRoute = (targetIndex < availableRoutes.length)
          ? availableRoutes[targetIndex]
          : _RouteResult(
              points: routePoints,
              distance: distanceKm,
              duration: durationMinutes * 60,
              routeIndex: targetIndex,
            );
      evals[targetIndex] = _RouteEvaluation(
        route: selectedRoute,
        roadSegments: selectedOsmRoadSegments,
        safety: personalizedSafetyResult,
        weather: weather,
        blackspots: _BlackspotRouteAssessment(
          clearSampleScore: null,
          detectedBlackspots: blackspotDetails != null ? 1 : 0,
          successfulSamples: 0,
          segmentsChecked: 0,
          verifiedRecordCount: 0,
          segmentResults: const [],
          unavailableReason: null,
        ),
        traffic: routeEvaluations[selectedRouteIndex]?.traffic,
      );
    }

    showDialog<void>(
      context: context,
      barrierDismissible: true,
      builder: (dialogContext) {
        return WhyThisRouteDialog(
          initialRouteIndex: targetIndex,
          allEvaluations: evals,
          origin: fromText,
          destination: toText,
          vehicle: currentVehicle,
          travelTime: currentTravelTime,
          priority: _effectivePriority,
          service: service,
          isDarkMode: _isDarkMode,
          formatDurationFn: formatDuration,
          personalProfile: _personalProfile,
        );
      },
    );
  }

