  Widget _buildMapStatusIndicators() {
    final traffic =
        routeEvaluations[selectedRouteIndex]?.traffic ??
        (routeEvaluations.isNotEmpty
            ? routeEvaluations.values.first.traffic
            : null);
    final trafficStatus = traffic?.status ?? 'Traffic offline';
    final trafficColor = switch (traffic?.status) {
      'Low Traffic' => _NeonTheme.safeGreen,
      'Moderate Traffic' => _NeonTheme.warningGold,
      'High Traffic' => _NeonTheme.dangerRed,
      _ => _NeonTheme.textSecondaryDark,
    };

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      decoration: BoxDecoration(
        color: _isDarkMode
            ? _NeonTheme.cardDark.withValues(alpha: 0.88)
            : Colors.white.withValues(alpha: 0.92),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: _isDarkMode ? _NeonTheme.cyanBorder : const Color(0x350284C7),
          width: 1,
        ),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          // GPS Pill
          Container(
            width: 6,
            height: 6,
            decoration: const BoxDecoration(
              color: _NeonTheme.safeGreen,
              shape: BoxShape.circle,
            ),
          ),
          const SizedBox(width: 5),
          const Text(
            'GPS',
            style: TextStyle(
              fontSize: 10,
              fontWeight: FontWeight.w800,
              color: _NeonTheme.safeGreen,
            ),
          ),
          const SizedBox(width: 10),
          // Traffic Pill
          Container(
            width: 6,
            height: 6,
            decoration: BoxDecoration(
              color: trafficColor,
              shape: BoxShape.circle,
            ),
          ),
          const SizedBox(width: 5),
          Text(
            trafficStatus.toUpperCase(),
            style: TextStyle(
              fontSize: 9.5,
              fontWeight: FontWeight.w700,
              color: trafficColor,
            ),
          ),
          if (selectedOsmRoadSegments != null) ...[
            const SizedBox(width: 10),
            Container(
              width: 6,
              height: 6,
              decoration: const BoxDecoration(
                color: _NeonTheme.neonCyan,
                shape: BoxShape.circle,
              ),
            ),
            const SizedBox(width: 5),
            Text(
              '${selectedOsmRoadSegments!.length} OSM SEGS',
              style: const TextStyle(
                fontSize: 9.5,
                fontWeight: FontWeight.w700,
                color: _NeonTheme.neonCyan,
              ),
            ),
          ],
        ],
      ),
    );
