  Widget _buildNavigationHud() {
    if (!_navigationActive && _navigationError != null) {
      return Container(
        constraints: const BoxConstraints(maxWidth: 460),
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
        decoration: BoxDecoration(
          color: _isDarkMode
              ? _NeonTheme.cardDark.withValues(alpha: 0.95)
              : Colors.white.withValues(alpha: 0.97),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: _NeonTheme.dangerRed, width: 1.2),
          boxShadow: [
            BoxShadow(
              color: _NeonTheme.dangerRed.withValues(alpha: 0.25),
              blurRadius: 10,
              offset: const Offset(0, 2),
            ),
          ],
        ),
        child: Row(
          children: [
            const Icon(
              Icons.error_outline_rounded,
              color: _NeonTheme.dangerRed,
              size: 20,
            ),
            const SizedBox(width: 10),
            Expanded(
              child: Text(
                _navigationError!,
                style: const TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w600,
                  color: _NeonTheme.dangerRed,
                ),
              ),
            ),
            IconButton(
              icon: const Icon(Icons.close_rounded, size: 18),
              onPressed: () => setState(() => _navigationError = null),
            ),
          ],
        ),
      );
    }

    if (!_navigationActive) {
      if (_navigationStartInProgress) {
        return Container(
          constraints: const BoxConstraints(maxWidth: 460),
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
          decoration: BoxDecoration(
            color: _isDarkMode
                ? _NeonTheme.cardDark.withValues(alpha: 0.95)
                : Colors.white.withValues(alpha: 0.97),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: _NeonTheme.cyanBorder, width: 1.2),
            boxShadow: [
              BoxShadow(
                color: _NeonTheme.cyanBorder.withValues(alpha: 0.25),
                blurRadius: 10,
                offset: const Offset(0, 2),
              ),
            ],
          ),
          child: const Row(
            children: [
              SizedBox(
                width: 16,
                height: 16,
                child: CircularProgressIndicator(
                  strokeWidth: 2.0,
                  valueColor: AlwaysStoppedAnimation<Color>(_NeonTheme.neonCyan),
                ),
              ),
              SizedBox(width: 10),
              Expanded(
                child: Text(
                  'Waiting for device GPS signal...',
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    color: _NeonTheme.neonCyan,
                  ),
                ),
              ),
            ],
          ),
        );
      }
      return const SizedBox.shrink();
    }

    final totalMeters = _calculateTotalRouteMeters(routePoints);
    final totalKm = totalMeters > 0
        ? totalMeters / 1000.0
        : (distanceKm > 0 ? distanceKm : 1.0);
    final currentProgress =
        _getCurrentUserRouteProgressMeters().clamp(0.0, totalMeters);
    final traveledKm = currentProgress / 1000.0;
    final remainingMeters = math.max(0.0, totalMeters - currentProgress);
    final remainingKm = remainingMeters / 1000.0;
    final progressFraction = totalMeters > 0
        ? (currentProgress / totalMeters).clamp(0.0, 1.0)
        : 0.0;
    final progressPercent = (progressFraction * 100).round();
    final remainingMinutes =
        service.calculateVehicleTime(remainingKm, currentVehicle).round();

    final nextStep = _getNextStepInfo();
    final isOffRoute = _isOffRoute;
    final isReached =
        _destinationStage == _DestinationProximityStage.reached;

    final borderColor = isOffRoute
        ? _NeonTheme.dangerRed
        : (isReached ? _NeonTheme.safeGreen : _NeonTheme.neonCyan);

    return Container(
      constraints: const BoxConstraints(maxWidth: 460),
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
      decoration: BoxDecoration(
        color: _isDarkMode
            ? _NeonTheme.cardDark.withValues(alpha: 0.95)
            : Colors.white.withValues(alpha: 0.97),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: borderColor, width: 1.2),
        boxShadow: [
          BoxShadow(
            color: borderColor.withValues(alpha: 0.25),
            blurRadius: 10,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // Top Row: Instruction, Voice Toggle, Stop Button
          Row(
            children: [
              Container(
                width: 28,
                height: 28,
                decoration: BoxDecoration(
                  color: (isOffRoute
                          ? _NeonTheme.dangerRed
                          : (isReached
                              ? _NeonTheme.safeGreen
                              : _NeonTheme.neonCyan))
                      .withValues(alpha: 0.16),
                  shape: BoxShape.circle,
                ),
                child: Icon(
                  isOffRoute
                      ? Icons.warning_rounded
                      : (isReached
                          ? Icons.check_circle_rounded
                          : nextStep.icon),
                  size: 16,
                  color: isOffRoute
                      ? _NeonTheme.dangerRed
                      : (isReached
                          ? _NeonTheme.safeGreen
                          : _NeonTheme.neonCyan),
                ),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  isOffRoute
                      ? 'Off Route'
                      : (isReached
                          ? 'Destination reached'
                          : nextStep.instruction),
                  style: TextStyle(
                    fontWeight: FontWeight.w800,
                    fontSize: 12.5,
                    color: isOffRoute
                        ? _NeonTheme.dangerRed
                        : (isReached
                            ? _NeonTheme.safeGreen
                            : (_isDarkMode ? Colors.white : Colors.black87)),
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              IconButton(
                icon: Icon(
                  _voiceAlertsEnabled
                      ? Icons.volume_up_rounded
                      : Icons.volume_off_rounded,
                  size: 18,
                  color: _voiceAlertsEnabled
                      ? _NeonTheme.neonCyan
                      : (_isDarkMode ? Colors.white54 : Colors.black45),
                ),
                tooltip: _voiceAlertsEnabled
                    ? 'Voice alerts active (Click to mute)'
                    : 'Voice alerts muted (Click to enable)',
                onPressed: () {
                  setState(() {
                    _voiceAlertsEnabled = !_voiceAlertsEnabled;
                    if (!_voiceAlertsEnabled) {
                      WebSpeechHelper.stop();
                    } else {
                      _speakAlert('Voice alerts enabled');
                    }
                  });
                },
                visualDensity: VisualDensity.compact,
                padding: const EdgeInsets.symmetric(horizontal: 4),
                constraints: const BoxConstraints(),
              ),
              const SizedBox(width: 6),
              OutlinedButton(
                style: OutlinedButton.styleFrom(
                  foregroundColor: _NeonTheme.dangerRed,
                  side: const BorderSide(color: _NeonTheme.dangerRed, width: 1),
                  padding:
                      const EdgeInsets.symmetric(horizontal: 9, vertical: 4),
                  visualDensity: VisualDensity.compact,
                  minimumSize: Size.zero,
                ),
                onPressed: _stopNavigation,
                child: const Text(
                  'Stop',
                  style: TextStyle(fontWeight: FontWeight.w800, fontSize: 11),
                ),
              ),
            ],
          ),

          // Off-Route Warning Alert
          if (isOffRoute) ...[
            const SizedBox(height: 6),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
              decoration: BoxDecoration(
                color: _NeonTheme.dangerRed.withValues(alpha: 0.12),
                borderRadius: BorderRadius.circular(6),
                border: Border.all(
                  color: _NeonTheme.dangerRed.withValues(alpha: 0.35),
                  width: 1,
                ),
              ),
              child: Row(
                children: [
                  const Icon(
                    Icons.warning_amber_rounded,
                    size: 14,
                    color: _NeonTheme.dangerRed,
                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      'You are off the selected route (${_distanceFromRouteMeters?.round() ?? 50} m away from route)',
                      style: const TextStyle(
                        fontSize: 10.5,
                        fontWeight: FontWeight.w700,
                        color: _NeonTheme.dangerRed,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],

          // Destination Proximity Alert
          if (!isReached && _destinationAlertText != null) ...[
            const SizedBox(height: 6),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
              decoration: BoxDecoration(
                color: _NeonTheme.neonAmber.withValues(alpha: 0.14),
                borderRadius: BorderRadius.circular(6),
                border: Border.all(
                  color: _NeonTheme.neonAmber.withValues(alpha: 0.4),
                  width: 1,
                ),
              ),
              child: Row(
                children: [
                  const Icon(
                    Icons.flag_rounded,
                    size: 14,
                    color: _NeonTheme.neonAmber,
                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      _destinationAlertText!,
                      style: const TextStyle(
                        fontSize: 10.5,
                        fontWeight: FontWeight.w700,
                        color: _NeonTheme.neonAmber,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],

          const SizedBox(height: 7),

          // Traveled vs Total distance ratio & percent
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                '🚗 ${traveledKm.toStringAsFixed(1)} km / ${totalKm.toStringAsFixed(1)} km',
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w700,
                  color: _isDarkMode ? Colors.white70 : Colors.black87,
                ),
              ),
              Text(
                '$progressPercent%',
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w800,
                  color: isOffRoute
                      ? _NeonTheme.dangerRed
                      : (isReached
                          ? _NeonTheme.safeGreen
                          : _NeonTheme.neonCyan),
                ),
              ),
            ],
          ),

          const SizedBox(height: 4),

          // Linear Progress Bar
          ClipRRect(
            borderRadius: BorderRadius.circular(3),
            child: LinearProgressIndicator(
              value: progressFraction,
              minHeight: 5,
              backgroundColor: _isDarkMode ? Colors.white12 : Colors.black12,
              valueColor: AlwaysStoppedAnimation<Color>(
                isOffRoute
                    ? _NeonTheme.dangerRed
                    : (isReached ? _NeonTheme.safeGreen : _NeonTheme.neonCyan),
              ),
            ),
          ),

          const SizedBox(height: 5),

          // Remaining Distance & Travel Time Row
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Expanded(
                child: Text(
                '${remainingKm.toStringAsFixed(1)} km remaining • approximately $remainingMinutes min',
                style: TextStyle(
                  fontSize: 10.5,
                  fontWeight: FontWeight.w600,
                  color: _isDarkMode
                      ? _NeonTheme.textSecondaryDark
                      : _NeonTheme.textSecondaryLight,
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              const SizedBox(width: 8),
              Text(
                _routeProximityStatus ??
                    (isOffRoute
                        ? 'Off route'
                        : (isReached ? 'Arrived' : 'On route')),
                style: TextStyle(
                  fontSize: 10,
                  fontWeight: FontWeight.w700,
                  color: isOffRoute
                      ? _NeonTheme.dangerRed
                      : (isReached
                          ? _NeonTheme.safeGreen
                          : _NeonTheme.neonCyan),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

