  // ignore: unused_element
  Widget _buildRouteOptionsBar() {
    final preferences = [
      'Safety First',
      'Fastest Route',
      'Shortest Route',
      'Accessibility Friendly',
      'Less Traffic',
    ];

    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: Row(
        children: [
          for (final pref in preferences) ...[
            _buildPreferencePill(pref),
            const SizedBox(width: 8),
          ],
        ],
      ),
    );
  }

  Widget _buildPreferencePill(String pref) {
    final isSelected = currentPreference == pref || currentMainPriority == pref;
    final icon = switch (pref) {
      'Fastest Route' => Icons.speed_rounded,
      'Shortest Route' => Icons.route_rounded,
      'Accessibility Friendly' => Icons.accessible_rounded,
      'Less Traffic' => Icons.traffic_rounded,
      _ => Icons.shield_rounded,
    };

    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: () {
          setState(() {
            currentPreference = pref;
            currentMainPriority = pref;
            final eval = routeEvaluations[selectedRouteIndex];
            if (eval != null) {
              personalizedSafetyResult = calculatePersonalizedSafetyScore(
                accidentScore: _factorScore(eval.safety, 'Verified blackspots'),
                roadConditionScore: _factorScore(eval.safety, 'Road condition'),
                trafficScore: _calculateTrafficSafetyScore(eval.traffic),
                weatherScore: _calculateWeatherSafetyScore(eval.weather),
                lightingScore: _factorScore(eval.safety, 'Lighting'),
                accessibilityScore: _factorScore(eval.safety, 'Accessibility'),
                accidentSegmentsWithMatches:
                    eval.blackspots.detectedBlackspots ?? 0,
                accidentVerifiedRecordCount:
                    eval.blackspots.verifiedRecordCount,
                accidentUnavailableReason: eval.blackspots.unavailableReason,
                roadConditionSegments: eval.roadSegments?.length ?? 0,
                lightingSegments: eval.roadSegments?.length ?? 0,
                accessibilitySegments: eval.roadSegments?.length ?? 0,
                traffic: eval.traffic,
                weather: eval.weather,
                priority: _effectivePriority,
              );
              safetyScore = personalizedSafetyResult.score;
            }
            if (availableRoutes.length > 1) {
              final evals = routeEvaluations.values.toList();
              if (evals.isNotEmpty) {
                routeRecommendation = _recommendRoutes(evals);
              }
            }
          });
        },
        borderRadius: BorderRadius.circular(12),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 7),
          decoration: BoxDecoration(
            color: isSelected
                ? _NeonTheme.neonCyan.withValues(alpha: 0.15)
                : (_isDarkMode ? _NeonTheme.cardDark : _NeonTheme.cardLight),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(
              color: isSelected
                  ? _NeonTheme.neonCyan
                  : (_isDarkMode
                        ? _NeonTheme.cyanBorder
                        : const Color(0x350284C7)),
              width: isSelected ? 1.4 : 1,
            ),
            boxShadow: isSelected && _isDarkMode
                ? _NeonTheme.cyanGlow(6)
                : null,
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                icon,
                size: 14,
                color: isSelected
                    ? _NeonTheme.neonCyan
                    : (_isDarkMode
                          ? _NeonTheme.textSecondaryDark
                          : _NeonTheme.textSecondaryLight),
              ),
              const SizedBox(width: 6),
              Text(
                pref,
                style: TextStyle(
                  fontSize: 11.5,
                  fontWeight: isSelected ? FontWeight.w800 : FontWeight.w600,
                  color: isSelected
                      ? _NeonTheme.neonCyan
                      : (_isDarkMode
                            ? _NeonTheme.textPrimaryDark
                            : _NeonTheme.textPrimaryLight),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

