    final score = safetyScore;
    final scoreColor = score != null && score >= 70
        ? _NeonTheme.safeGreen
        : score != null && score >= 40
        ? _NeonTheme.warningGold
        : _NeonTheme.dangerRed;

    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: _isDarkMode ? _NeonTheme.cardDark : _NeonTheme.cardLight,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(
          color: _isDarkMode ? _NeonTheme.cyanBorder : const Color(0x350284C7),
          width: 1.2,
        ),
        boxShadow: _NeonTheme.cardShadow(_isDarkMode),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // Header
          Row(
            children: [
              const Icon(
                Icons.shield_rounded,
                color: _NeonTheme.neonCyan,
                size: 20,
              ),
              const SizedBox(width: 8),
              Flexible(
                child: Text(
                  'PERSONALIZED SAFETY SCORE',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w800,
                    letterSpacing: 0.8,
                    color: _isDarkMode
                        ? _NeonTheme.neonCyan
                        : _NeonTheme.electricBlue,
                  ),
                ),
              ),
              const Spacer(),
              _buildScoreCardWhyRouteButton(),
            ],
          ),
          const SizedBox(height: 16),
          // Circular Score Ring & Info
