  Widget _buildTransparencyTableRow(SafetyFactor factor) {
    final isUsed = factor.score != null && factor.relevant && factor.weight > 0;
    final statusText = factor.status ??
        (factor.score != null ? 'Available' : 'Unavailable');
    final statusColor = switch (statusText) {
      'Clear' || 'Available' || 'Daylight' => _NeonTheme.safeGreen,
      'Caution' => _NeonTheme.warningGold,
      _ => _isDarkMode ? Colors.white38 : Colors.black38,
    };

    final evidenceText = factor.score != null
        ? '${factor.score!.toStringAsFixed(0)}% · ${factor.scoreLabel.isNotEmpty ? factor.scoreLabel : 'Verified factor'}'
        : (factor.unavailableReason ?? 'Data unavailable · excluded');

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
      child: Row(
        children: [
          // Factor Title + Icon
          Expanded(
            flex: 3,
            child: Row(
              children: [
                Icon(
                  factor.icon,
                  size: 14,
                  color: isUsed
                      ? _NeonTheme.neonCyan
                      : (_isDarkMode ? Colors.white38 : Colors.black38),
                ),
                const SizedBox(width: 6),
                Expanded(
                  child: Text(
                    factor.title,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w700,
                      color: _isDarkMode
                          ? _NeonTheme.textPrimaryDark
                          : _NeonTheme.textPrimaryLight,
                    ),
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
              ],
            ),
          ),
          // Status
          Expanded(
            flex: 2,
            child: Container(
              alignment: Alignment.centerLeft,
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                decoration: BoxDecoration(
                  color: statusColor.withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Text(
                  statusText,
                  style: TextStyle(
                    fontSize: 9,
                    fontWeight: FontWeight.w700,
                    color: statusColor,
                  ),
                ),
              ),
            ),
          ),
          // Evidence / Value
          Expanded(
            flex: 4,
            child: Text(
              evidenceText,
              style: TextStyle(
                fontSize: 10,
                color: isUsed
                    ? (_isDarkMode
                          ? _NeonTheme.textPrimaryDark
                          : _NeonTheme.textPrimaryLight)
                    : (_isDarkMode
                          ? _NeonTheme.textSecondaryDark
                          : _NeonTheme.textSecondaryLight),
              ),
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
            ),
          ),
          // Used in Score
          Expanded(
            flex: 2,
            child: Align(
              alignment: Alignment.centerRight,
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                decoration: BoxDecoration(
                  color: isUsed
                      ? _NeonTheme.safeGreen.withValues(alpha: 0.15)
                      : (_isDarkMode
                            ? Colors.white.withValues(alpha: 0.05)
                            : Colors.black.withValues(alpha: 0.05)),
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Text(
                  isUsed
                      ? 'Yes (${(factor.weight * 100).toStringAsFixed(0)}%)'
                      : 'No',
                  style: TextStyle(
                    fontSize: 9,
                    fontWeight: FontWeight.w800,
                    color: isUsed
                        ? _NeonTheme.safeGreen
                        : (_isDarkMode ? Colors.white38 : Colors.black38),
                  ),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

