  Widget _buildTripsHistoryView() {
    if (!_savedTripsLoaded) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.all(48.0),
          child: CircularProgressIndicator(color: _NeonTheme.neonCyan),
        ),
      );
    }

    var displayedTrips = List<_SavedTrip>.from(_savedTrips);

    // Filter by search query
    if (_tripsSearchQuery.trim().isNotEmpty) {
      final q = _tripsSearchQuery.trim().toLowerCase();
      displayedTrips = displayedTrips
          .where(
            (t) =>
                t.origin.toLowerCase().contains(q) ||
                t.destination.toLowerCase().contains(q),
          )
          .toList();
    }

    // Sort by filter mode
    if (_tripsFilterMode == 'Safest') {
      displayedTrips.sort(
        (a, b) => (b.safetyScore ?? 0).compareTo(a.safetyScore ?? 0),
      );
    } else {
      // 'All' or 'Recent' -> newest first
      displayedTrips.sort((a, b) => b.createdAt.compareTo(a.createdAt));
    }

    return Center(
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 1100),
        child: SingleChildScrollView(
          padding: const EdgeInsets.all(24),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              // Header Row: Icon, Title, Subtitle, Clear All
              Row(
                children: [
                  Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: _NeonTheme.neonCyan.withValues(alpha: 0.14),
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: const Icon(
                      Icons.bookmark_rounded,
                      color: _NeonTheme.neonCyan,
                      size: 24,
                    ),
                  ),
                  const SizedBox(width: 14),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'My Trips',
                        style: TextStyle(
                          fontSize: 22,
                          fontWeight: FontWeight.w900,
                          color: _isDarkMode
                              ? _NeonTheme.textPrimaryDark
                              : _NeonTheme.textPrimaryLight,
                        ),
                      ),
                      Text(
                        'Your saved routes in one place',
                        style: TextStyle(
                          fontSize: 12,
                          color: _isDarkMode
                              ? _NeonTheme.textSecondaryDark
                              : _NeonTheme.textSecondaryLight,
                        ),
                      ),
                    ],
                  ),
                  const Spacer(),
                  if (_savedTrips.isNotEmpty)
                    TextButton.icon(
                      onPressed: _confirmClearAllTrips,
                      icon: const Icon(
                        Icons.delete_sweep_rounded,
                        size: 16,
                        color: _NeonTheme.dangerRed,
                      ),
                      label: const Text(
                        'Clear All',
                        style: TextStyle(
                          color: _NeonTheme.dangerRed,
                          fontWeight: FontWeight.w700,
                          fontSize: 12,
                        ),
                      ),
                    ),
                ],
              ),
              const SizedBox(height: 20),

              if (_savedTrips.isEmpty)
                _buildEmptyTripsState()
              else ...[
                // Search and Filter Bar
                _buildTripsFilterBar(),
                const SizedBox(height: 18),

                if (displayedTrips.isEmpty)
                  Container(
                    padding: const EdgeInsets.all(32),
                    decoration: BoxDecoration(
                      color: _isDarkMode
                          ? _NeonTheme.cardDark
                          : _NeonTheme.cardLight,
                      borderRadius: BorderRadius.circular(18),
                      border: Border.all(
                        color: _isDarkMode
                            ? _NeonTheme.cyanBorder
                            : const Color(0x350284C7),
                      ),
                    ),
                    child: Center(
                      child: Column(
                        children: [
                          Icon(
                            Icons.search_off_rounded,
                            size: 40,
                            color: _isDarkMode
                                ? _NeonTheme.textSecondaryDark
                                : _NeonTheme.textSecondaryLight,
                          ),
                          const SizedBox(height: 10),
                          Text(
                            'No trips match your search',
                            style: TextStyle(
                              fontSize: 14,
                              fontWeight: FontWeight.w700,
                              color: _isDarkMode
                                  ? _NeonTheme.textPrimaryDark
                                  : _NeonTheme.textPrimaryLight,
                            ),
                          ),
                        ],
                      ),
                    ),
                  )
                else
                  // Responsive Cards Layout (Desktop: 2-3 col, Tablet: 2 col, Mobile: 1 col)
                  LayoutBuilder(
                    builder: (context, constraints) {
                      final width = constraints.maxWidth;
                      int crossAxisCount = 1;
                      if (width >= 1000) {
                        crossAxisCount = 3;
                      } else if (width >= 620) {
                        crossAxisCount = 2;
                      }

                      if (crossAxisCount == 1) {
                        return Column(
                          children: [
                            for (final trip in displayedTrips) ...[
                              _buildSavedTripCard(trip),
                              const SizedBox(height: 14),
                            ],
                          ],
                        );
                      }

                      return GridView.builder(
                        shrinkWrap: true,
                        physics: const NeverScrollableScrollPhysics(),
                        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: crossAxisCount,
                          crossAxisSpacing: 14,
                          mainAxisSpacing: 14,
                          mainAxisExtent: 228,
                        ),
                        itemCount: displayedTrips.length,
                        itemBuilder: (context, index) =>
                            _buildSavedTripCard(displayedTrips[index]),
                      );
                    },
                  ),
              ],
            ],
          ),
        ),
      ),
    );
  }

