  Widget _buildTripsFilterChip(String filter) {
    final isSelected = _tripsFilterMode == filter;
    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: () => setState(() => _tripsFilterMode = filter),
        borderRadius: BorderRadius.circular(8),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
          decoration: BoxDecoration(
            color: isSelected
                ? _NeonTheme.neonCyan.withValues(alpha: 0.16)
                : (_isDarkMode
                      ? _NeonTheme.cardElevatedDark
                      : const Color(0xffF1F5F9)),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: isSelected
                  ? _NeonTheme.neonCyan
                  : (_isDarkMode ? Colors.white10 : Colors.black12),
              width: isSelected ? 1.4 : 1,
            ),
          ),

          child: Text(
            filter,
            style: TextStyle(
              fontSize: 11,
              fontWeight: isSelected ? FontWeight.w800 : FontWeight.w600,
              color: isSelected
                  ? _NeonTheme.neonCyan
                  : (_isDarkMode
                        ? _NeonTheme.textSecondaryDark
                        : _NeonTheme.textSecondaryLight),
            ),
          ),
        ),
      ),
    );
  }

  Future<void> _confirmClearAllTrips() async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogCtx) => AlertDialog(
        backgroundColor: _isDarkMode
            ? _NeonTheme.cardDark
            : _NeonTheme.cardLight,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(18),
          side: BorderSide(
            color: _isDarkMode
                ? _NeonTheme.cyanBorder
                : const Color(0x350284C7),
          ),
        ),
        title: Text(
          'Clear all saved trips?',
          style: TextStyle(
            fontSize: 16,
            fontWeight: FontWeight.w800,
            color: _isDarkMode
                ? _NeonTheme.textPrimaryDark
                : _NeonTheme.textPrimaryLight,
          ),
        ),
        content: Text(
          'This will remove all saved trips from your browser storage.',
          style: TextStyle(
            fontSize: 13,
            color: _isDarkMode
                ? _NeonTheme.textSecondaryDark
                : _NeonTheme.textSecondaryLight,
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogCtx).pop(false),
            child: Text(
              'Cancel',
              style: TextStyle(
                color: _isDarkMode
                    ? _NeonTheme.textSecondaryDark
                    : _NeonTheme.textSecondaryLight,
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: _NeonTheme.dangerRed,
              foregroundColor: Colors.white,
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(10),
              ),
            ),
            onPressed: () => Navigator.of(dialogCtx).pop(true),
            child: const Text(
              'Clear All',
              style: TextStyle(fontWeight: FontWeight.w800),
            ),
          ),
        ],
      ),
    );

    if (confirmed == true) {
      setState(() {
        _savedTrips.clear();
      });
      await _persistSavedTrips();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('All trips cleared'),
            backgroundColor: _NeonTheme.electricBlue,
          ),
        );
      }
    }
  }

  Widget _buildSavedTripCard(_SavedTrip trip) {
    final score = trip.safetyScore;
    final scoreColor = score != null && score >= 70
        ? _NeonTheme.safeGreen
        : score != null && score >= 40
        ? _NeonTheme.warningGold
        : _NeonTheme.dangerRed;

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: _isDarkMode ? _NeonTheme.cardDark : _NeonTheme.cardLight,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(
          color: _isDarkMode ? _NeonTheme.cyanBorder : const Color(0x350284C7),
          width: 1.2,
        ),
        boxShadow: _NeonTheme.cardShadow(_isDarkMode),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          // Header: Origin -> Destination & Vehicle Tag
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: _NeonTheme.neonCyan.withValues(alpha: 0.15),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: const Icon(
                  Icons.alt_route_rounded,
                  color: _NeonTheme.neonCyan,
                  size: 18,
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      '${trip.origin} → ${trip.destination}',
                      style: TextStyle(
                        fontSize: 14.5,
                        fontWeight: FontWeight.w800,
                        color: _isDarkMode
                            ? _NeonTheme.textPrimaryDark
                            : _NeonTheme.textPrimaryLight,
                      ),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                    ),
                    const SizedBox(height: 3),
                    Row(
                      children: [
                        Icon(
                          _vehicleIcon(trip.vehicleMode),
                          size: 13,
                          color: _isDarkMode
                              ? _NeonTheme.textSecondaryDark
                              : _NeonTheme.textSecondaryLight,
                        ),
                        const SizedBox(width: 4),
                        Text(
                          '${trip.vehicleMode} · ${trip.travelTimeMode}',
                          style: TextStyle(
                            fontSize: 11,
                            color: _isDarkMode
                                ? _NeonTheme.textSecondaryDark
                                : _NeonTheme.textSecondaryLight,
                          ),
                        ),
                        const SizedBox(width: 6),
                        Text(
                          '· ${_formatTripDate(trip.createdAt)}',
                          style: TextStyle(
                            fontSize: 10.5,
                            color: _isDarkMode
                                ? _NeonTheme.textSecondaryDark
                                : _NeonTheme.textSecondaryLight,
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 6),
              // Safety Score Ring / Badge
