  Future<void> _retryFacilitySearch() async {
    final route =
        availableRoutes.isNotEmpty &&
            selectedRouteIndex < availableRoutes.length
        ? availableRoutes[selectedRouteIndex]
        : routeEvaluations[selectedRouteIndex]?.route;
    if (route == null) return;
    for (final category in _facilityCategories) {
      if (_selectedFacilityCategories.contains(category.selectorLabel)) {
        _globalFacilityCache.remove(_facilityCacheKey(route, category.id));
      }
    }
    await _loadFacilitiesForRoute(route);
  }

  Widget _facilityNavigationCard() {
    final category = _facilityCategoryForId(_selectedFacility?.categoryId);
    final facility = _selectedFacility;
    if (category == null || facility == null) return const SizedBox.shrink();
    final reached = _selectedFacilityReached;
    final remaining = _facilityRemainingAlongRoute(facility);

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
      decoration: BoxDecoration(
        color: _isDarkMode ? _NeonTheme.cardDark : _NeonTheme.cardLight,
