  Future<Position> _getFreshPositionForReroute() async {
    if (!await Geolocator.isLocationServiceEnabled()) {
      throw const _NavigationLocationException(
        'Location services are disabled. Enable them to route from your position.',
      );
    }
    var permission = await Geolocator.checkPermission();
    if (permission == LocationPermission.denied) {
      permission = await Geolocator.requestPermission();
    }
    if (permission == LocationPermission.denied ||
        permission == LocationPermission.deniedForever) {
      throw const _NavigationLocationException(
        'Location permission is required to route to a facility.',
      );
    }
    return Geolocator.getCurrentPosition(
      locationSettings: const LocationSettings(accuracy: LocationAccuracy.high),
    );
  }

  Future<void> _routeViaFacility(
    _Facility facility, {
    required bool addToDestination,
  }) async {
    final destination = endLocation;
    if (addToDestination && destination == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('The original destination is unavailable.'),
        ),
      );
      return;
    }

    setState(() => _facilityRerouteLoading = true);
    try {
      final position = await _getFreshPositionForReroute();
      final origin = _Location(
        lat: position.latitude,
        lon: position.longitude,
        name: 'Current Location',
      );
      final facilityLocation = _Location(
        lat: facility.lat,
        lon: facility.lon,
        name:
            facility.name ?? _facilityCategoryForId(facility.categoryId)!.label,
      );
      final toFacility = await service.getRoutes(origin, facilityLocation);
      if (toFacility == null || toFacility.isEmpty) {
        throw StateError('OSRM did not return a route to the facility.');
      }

      List<_RouteResult> directRoutes = [];
      late final _RouteResult facilityRoute;
      if (addToDestination) {
        final toDestination = await service.getRoutes(origin, destination!);
        final facilityToDestination = await service.getRoutes(
          facilityLocation,
          destination,
        );
        if (toDestination == null ||
            toDestination.isEmpty ||
            facilityToDestination == null ||
            facilityToDestination.isEmpty) {
          throw StateError(
            'OSRM did not return all route legs through the facility.',
          );
        }
        final nextIndex = availableRoutes.isEmpty
            ? 0
            : availableRoutes
                      .map((route) => route.routeIndex)
                      .reduce(math.max) +
                  1;
        directRoutes = [
          for (var index = 0; index < toDestination.length; index++)
            _RouteResult(
              points: toDestination[index].points,
              distance: toDestination[index].distance,
              duration: toDestination[index].duration,
              routeIndex: nextIndex + index,
            ),
        ];
        final firstLeg = toFacility.first;
        final secondLeg = facilityToDestination.first;
        final joinedPoints = [
          ...firstLeg.points,
          ...secondLeg.points.skip(
            firstLeg.points.isNotEmpty &&
                    secondLeg.points.isNotEmpty &&
                    service._distanceBetweenMeters(
                          firstLeg.points.last,
                          secondLeg.points.first,
                        ) <
                        10
                ? 1
                : 0,
          ),
        ];
        facilityRoute = _RouteResult(
          points: joinedPoints,
          distance: firstLeg.distance + secondLeg.distance,
          duration: firstLeg.duration + secondLeg.duration,
          routeIndex: nextIndex + directRoutes.length,
        );
      } else {
        final nextIndex = availableRoutes.isEmpty
            ? 0
            : availableRoutes
                      .map((route) => route.routeIndex)
                      .reduce(math.max) +
                  1;
        facilityRoute = _RouteResult(
          points: toFacility.first.points,
          distance: toFacility.first.distance,
          duration: toFacility.first.duration,
          routeIndex: nextIndex,
        );
      }

      final routes = addToDestination
          ? [...directRoutes, facilityRoute]
          : [facilityRoute];
      final evaluations = await Future.wait(
        routes.map(
          (route) => _evaluateRoute(route, _loadRouteRoadSegments(route)),
        ),
      );
      if (!mounted) return;
      final selectedEvaluation = evaluations.firstWhere(
        (evaluation) => evaluation.route.routeIndex == facilityRoute.routeIndex,
      );
      final end = addToDestination ? destination! : facilityLocation;

      setState(() {
        currentPosition = position;
        startLocation = origin;
        endLocation = end;
        _routeViaFacilityName = addToDestination
            ? facility.name ??
                  _facilityCategoryForId(facility.categoryId)!.label
            : null;
        availableRoutes = routes;
        routeEvaluations = {
          for (final evaluation in evaluations)
            evaluation.route.routeIndex: evaluation,
        };
        selectedRouteIndex = facilityRoute.routeIndex;
        routePoints = facilityRoute.points;
        distanceKm = facilityRoute.distance;
        durationMinutes = service.calculateVehicleTime(
          facilityRoute.distance,
          currentVehicle,
        );
        weather = selectedEvaluation.weather;
        accidentSafety = _factorScore(
          selectedEvaluation.safety,
          'Verified blackspots',
        );
        roadSafety = _factorScore(selectedEvaluation.safety, 'Road condition');
        trafficSafety = _factorScore(selectedEvaluation.safety, 'Traffic');
        lightingSafety = _factorScore(selectedEvaluation.safety, 'Lighting');
        accessibilitySafety = _factorScore(
          selectedEvaluation.safety,
          'Accessibility',
        );
        personalizedSafetyResult = selectedEvaluation.safety;
        safetyScore = selectedEvaluation.safety.score;
        selectedOsmRoadSegments = selectedEvaluation.roadSegments;
        _osmRoadDataStatus = selectedEvaluation.roadSegments == null
            ? 'Real road data unavailable for this route'
            : 'Real OSM road segments found: '
                  '${selectedEvaluation.roadSegments!.length}';
        recommendationReasons = _buildRecommendationReasons(selectedEvaluation);
        routeWarnings = _buildRouteWarnings(selectedEvaluation);
        routeRecommendation = const _RouteRecommendation(
          recommendedRouteIndex: null,
          rankedRouteIndexes: [],
          reason: 'Facility route built using real OSRM directions',
        );
        _facilitySearchGeneration++;
        facilities = [];
        _selectedFacilityCategories.clear();
        _facilityFailedCategoryIds.clear();
        _facilitiesUnavailable = false;
        _facilityResultsIncomplete = false;
        _facilityRerouteLoading = false;
        _selectedFacility = facility;
        _selectedFacilityReached = false;
        _updateRouteProximity(position);
        _updateSelectedFacilityProgress(position);
      });
      if (!addToDestination) unawaited(_startNavigation());
    } catch (error) {
      if (!mounted) return;
      setState(() => _facilityRerouteLoading = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            error is _NavigationLocationException
                ? error.message
                : 'Unable to build a real OSRM route to the selected facility.',
          ),
        ),
      );
      debugPrint('FACILITY ROUTE ERROR: $error');
    }
  }
}

