  Widget _buildProblemTypeChip(String type) {
    final isSelected = _selectedProblemType == type;
    final isDark = widget.isDarkMode;
    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: _isSubmitting
            ? null
            : () => setState(() => _selectedProblemType = type),
        borderRadius: BorderRadius.circular(8),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
          decoration: BoxDecoration(
            color: isSelected
                ? _NeonTheme.neonAmber.withValues(alpha: 0.16)
                : (isDark
                      ? _NeonTheme.cardElevatedDark
                      : const Color(0xffF1F5F9)),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: isSelected
                  ? _NeonTheme.neonAmber
                  : (isDark ? Colors.white10 : Colors.black12),
              width: isSelected ? 1.4 : 1,
            ),
            boxShadow: isSelected && isDark
                ? [
                    BoxShadow(
                      color: _NeonTheme.neonAmber.withValues(alpha: 0.25),
                      blurRadius: 6,
                    ),
                  ]
                : null,
          ),
          child: Text(
            type,
            style: TextStyle(
              fontSize: 11,
              fontWeight: isSelected ? FontWeight.w700 : FontWeight.w500,
              color: isSelected
                  ? (isDark ? _NeonTheme.neonAmber : const Color(0xffD97706))
                  : (isDark
                        ? _NeonTheme.textSecondaryDark
                        : _NeonTheme.textSecondaryLight),
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildSeverityOption(String severity) {
    final isSelected = _selectedSeverity == severity;
    final isDark = widget.isDarkMode;

    Color badgeColor;
    if (severity == 'High') {
      badgeColor = _NeonTheme.dangerRed;
    } else if (severity == 'Medium') {
      badgeColor = _NeonTheme.warningGold;
    } else {
      badgeColor = _NeonTheme.safeGreen;
    }

    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: _isSubmitting
            ? null
            : () => setState(() => _selectedSeverity = severity),
        borderRadius: BorderRadius.circular(10),
        child: Container(
          padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 8),
          decoration: BoxDecoration(
            color: isSelected
                ? badgeColor.withValues(alpha: 0.16)
                : (isDark
                      ? _NeonTheme.cardElevatedDark
                      : const Color(0xffF1F5F9)),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(
              color: isSelected
                  ? badgeColor
                  : (isDark ? Colors.white10 : Colors.black12),
              width: isSelected ? 1.4 : 1,
            ),
          ),
          child: Center(
            child: Text(
              severity,
              style: TextStyle(
                fontSize: 11.5,
                fontWeight: isSelected ? FontWeight.w800 : FontWeight.w600,
                color: isSelected
                    ? badgeColor
                    : (isDark
                          ? _NeonTheme.textSecondaryDark
                          : _NeonTheme.textSecondaryLight),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

