class WhyThisRouteLocalization {
  static String title(bool isTamil) =>
      isTamil ? 'இந்த வழி ஏன்?' : 'Why This Route?';

  static String subtitle(bool isTamil) => isTamil
      ? 'செயற்கை நுண்ணறிவு பாதுகாப்பு விளக்கம்'
      : 'AI-powered safety explanation';

  static String safetyScoreLabel(bool isTamil) =>
      isTamil ? 'பாதுகாப்பு மதிப்பெண்' : 'Safety Score';

  static String safetyFactorsHeading(bool isTamil) =>
      isTamil ? 'பாதுகாப்பு காரணிகள் விபரம்' : 'Safety Factor Breakdown';

  static String safetyFactorsSub(bool isTamil) => isTamil
      ? 'உண்மை தரவு: விபத்துப் பகுதிகள், OSM, TomTom & Open-Meteo'
      : 'Real calculated metrics from verified blackspots, OSM tags & live sources';

  static String comparisonHeading(int routeNum, bool isTamil) => isTamil
      ? 'வழி $routeNum ஏன் தேர்ந்தெடுக்கப்பட்டது?'
      : 'Why Route $routeNum?';

  static String safetyVsTimeHeading(bool isTamil) =>
      isTamil ? 'பாதுகாப்பு vs பயண நேரம்' : 'Safety vs Time';

  static String safetyFirstRoute(bool isTamil) =>
      isTamil ? 'அதிக பாதுகாப்பு வழி' : 'Safety-first route';

  static String fastestRoute(bool isTamil) =>
      isTamil ? 'வேகமான வழி' : 'Fastest route';

  static String dataUnavailable(bool isTamil) =>
      isTamil ? 'தரவு கிடைக்கவில்லை' : 'Data unavailable';

  static String recommendedForSafety(bool isTamil) => isTamil
      ? 'பாதுகாப்பிற்கு பரிந்துரைக்கப்படுகிறது'
      : 'Recommended for safety';

  static String considerRoute(int routeNum, bool isTamil) => isTamil
      ? 'அதிக பாதுகாப்பிற்கு வழி $routeNum-ஐ பரிசீலிக்கவும்'
      : 'Consider Route $routeNum for better safety';

  static String similarSafety(bool isTamil) => isTamil
      ? 'இரு வழிகளிலும் ஒத்த பாதுகாப்பு நிலைகள்'
      : 'Both routes have similar safety levels';

  static String done(bool isTamil) => isTamil ? 'சரி' : 'Done';

  static String factorTitle(String factorKey, bool isTamil) {
    if (!isTamil) {
      return switch (factorKey) {
        'accident' => 'Accident Risk',
        'road' => 'Road Condition',
        'traffic' => 'Traffic',
        'weather' => 'Weather',
        'lighting' => 'Lighting',
        'accessibility' => 'Accessibility',
        _ => factorKey,
      };
    }
    return switch (factorKey) {
      'accident' => 'விபத்து அபாயம்',
      'road' => 'சாலை நிலை',
      'traffic' => 'போக்குவரத்து',
      'weather' => 'வானிலை',
      'lighting' => 'வெளிச்சம்',
      'accessibility' => 'அணுகல்தன்மை',
      _ => factorKey,
    };
  }
}

