  Widget _buildPersonalPreferencesCard(
    WhyThisRouteAnalysis analysis,
    bool isDark,
  ) {
    final eval = widget.allEvaluations[_currentRouteIndex];
    final profile = widget.personalProfile;
    if (eval == null || profile == null || (!profile.isConfigured && profile.safetyMode == 'General')) {
      return const SizedBox.shrink();
    }

    final matchResult = PreferenceMatchEvaluator.evaluate(
      evaluation: eval,
      profile: profile,
      isDay: widget.travelTime != 'Night',
    );

    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: isDark
            ? _NeonTheme.cardElevatedDark.withValues(alpha: 0.95)
            : const Color(0xffF0FDF4),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: _NeonTheme.safeGreen.withValues(alpha: 0.5),
          width: 1.2,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(5),
                decoration: BoxDecoration(
                  color: _NeonTheme.safeGreen.withValues(alpha: 0.2),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: const Icon(
                  Icons.person_pin_rounded,
                  color: _NeonTheme.safeGreen,
                  size: 16,
                ),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  _isTamil
                      ? 'உங்கள் விருப்பங்களின் அடிப்படையில்'
                      : 'Based on your preferences',
                  style: TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w800,
                    color: isDark ? Colors.white : Colors.black87,
                  ),
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                decoration: BoxDecoration(
                  color: matchResult.matchColor.withValues(alpha: 0.2),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                    color: matchResult.matchColor.withValues(alpha: 0.6),
                    width: 1,
                  ),
                ),
                child: Text(
                  '${matchResult.matchPercentage.round()}% ${_isTamil ? matchResult.tamilMatchLabel : matchResult.matchLabel}',
                  style: TextStyle(
                    fontSize: 10,
                    fontWeight: FontWeight.w800,
                    color: matchResult.matchColor,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          Text(
            _isTamil ? matchResult.tamilNarrative : matchResult.narrative,
            style: TextStyle(
              fontSize: 12,
              height: 1.45,
              color: isDark
                  ? _NeonTheme.textSecondaryDark
                  : _NeonTheme.textSecondaryLight,
            ),
          ),
          if (matchResult.matchFactors.isNotEmpty) ...[
            const SizedBox(height: 8),
            for (int i = 0; i < matchResult.matchFactors.length; i++)
              Padding(
                padding: const EdgeInsets.only(bottom: 4),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      '✓ ',
                      style: TextStyle(
                        color: _NeonTheme.safeGreen,
                        fontWeight: FontWeight.bold,
                        fontSize: 12,
                      ),
                    ),
                    Expanded(
                      child: Text(
                        _isTamil
                            ? matchResult.tamilMatchFactors[i]
                            : matchResult.matchFactors[i],
                        style: TextStyle(
                          fontSize: 11.5,
                          color: isDark ? Colors.white70 : Colors.black87,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
          ],
        ],
      ),
    );
  }

  Widget _buildComparisonCard(WhyThisRouteAnalysis analysis, bool isDark) {
    final title = WhyThisRouteLocalization.comparisonHeading(
      analysis.targetRouteIndex + 1,
      _isTamil,
    );
    final posHighlights = _isTamil
        ? analysis.tamilPositiveHighlights
        : analysis.positiveHighlights;
    final tradeHighlights = _isTamil
        ? analysis.tamilTradeOffHighlights
        : analysis.tradeOffHighlights;
    final narrative = _isTamil
        ? analysis.tamilComparativeNarrative
        : analysis.comparativeNarrative;

    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: isDark
            ? _NeonTheme.bgDark.withValues(alpha: 0.6)
            : const Color(0xffF8FAFC),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: isDark ? Colors.white10 : Colors.black12,
          width: 0.8,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text(
            title,
            style: TextStyle(
              fontSize: 13,
              fontWeight: FontWeight.w800,
              color: isDark ? Colors.white : Colors.black87,
            ),
          ),
          const SizedBox(height: 8),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: [
              for (final h in posHighlights)
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: _NeonTheme.safeGreen.withValues(alpha: 0.15),
                    borderRadius: BorderRadius.circular(6),
                    border: Border.all(
                      color: _NeonTheme.safeGreen.withValues(alpha: 0.4),
                      width: 0.8,
                    ),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const Icon(
                        Icons.check_rounded,
                        size: 11,
                        color: _NeonTheme.safeGreen,
                      ),
                      const SizedBox(width: 4),
                      Text(
                        h,
                        style: const TextStyle(
                          fontSize: 10,
                          fontWeight: FontWeight.w700,
                          color: _NeonTheme.safeGreen,
                        ),
                      ),
                    ],
                  ),
                ),
              for (final h in tradeHighlights)
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: _NeonTheme.warningGold.withValues(alpha: 0.15),
                    borderRadius: BorderRadius.circular(6),
                    border: Border.all(
                      color: _NeonTheme.warningGold.withValues(alpha: 0.4),
                      width: 0.8,
                    ),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const Icon(
                        Icons.warning_amber_rounded,
                        size: 11,
                        color: _NeonTheme.warningGold,
                      ),
                      const SizedBox(width: 4),
                      Text(
                        h,
                        style: const TextStyle(
                          fontSize: 10,
                          fontWeight: FontWeight.w700,
                          color: _NeonTheme.warningGold,
                        ),
                      ),
                    ],
                  ),
                ),
            ],
          ),
          const SizedBox(height: 10),
          Container(
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: isDark
                  ? _NeonTheme.cardElevatedDark.withValues(alpha: 0.7)
                  : Colors.white,
              borderRadius: BorderRadius.circular(8),
              border: Border.all(
                color: isDark
                    ? Colors.white10
                    : Colors.black.withValues(alpha: 0.06),
                width: 0.8,
              ),
            ),
            child: Text(
              narrative,
              style: TextStyle(
                fontSize: 11,
                height: 1.4,
                color: isDark ? Colors.white70 : Colors.black87,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildFactorsBreakdown(WhyThisRouteAnalysis analysis, bool isDark) {
    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: isDark
            ? _NeonTheme.bgDark.withValues(alpha: 0.6)
            : const Color(0xffF8FAFC),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: isDark ? Colors.white10 : Colors.black12,
          width: 0.8,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              const Icon(
                Icons.analytics_rounded,
                size: 16,
                color: _NeonTheme.neonCyan,
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  WhyThisRouteLocalization.safetyFactorsHeading(_isTamil),
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w800,
                    letterSpacing: 0.5,
                    color: isDark
                        ? _NeonTheme.neonCyan
                        : _NeonTheme.electricBlue,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 4),
          Text(
            WhyThisRouteLocalization.safetyFactorsSub(_isTamil),
            style: TextStyle(
              fontSize: 10,
              color: isDark
                  ? _NeonTheme.textSecondaryDark
                  : _NeonTheme.textSecondaryLight,
            ),
          ),
          const SizedBox(height: 12),
          for (final factor in analysis.factors) ...[
            _buildFactorRow(factor, isDark),
            const SizedBox(height: 10),
          ],
        ],
      ),
    );
  }

  Widget _buildFactorRow(RouteFactorAnalysis factor, bool isDark) {
    final title = WhyThisRouteLocalization.factorTitle(factor.key, _isTamil);
    final commentary = _isTamil ? factor.tamilCommentary : factor.commentary;
    final isAvail = factor.isAvailable;
    final score = factor.score;
    final color = score != null && score >= 70
        ? _NeonTheme.safeGreen
        : score != null && score >= 40
        ? _NeonTheme.warningGold
        : _NeonTheme.dangerRed;

    return Container(
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: isDark
            ? _NeonTheme.cardElevatedDark.withValues(alpha: 0.7)
            : Colors.white,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
          color: isDark ? Colors.white10 : Colors.black.withValues(alpha: 0.06),
          width: 0.8,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              Icon(
                factor.icon,
                size: 15,
                color: isAvail
                    ? (isDark ? _NeonTheme.neonCyan : _NeonTheme.electricBlue)
                    : (isDark ? _NeonTheme.textSecondaryDark : Colors.grey),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  title,
                  style: TextStyle(
                    fontSize: 11.5,
                    fontWeight: FontWeight.w700,
                    color: isDark ? Colors.white : Colors.black87,
                  ),
                ),
              ),
              if (isAvail && score != null) ...[
                Text(
                  '${score.round()}%',
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w800,
                    color: color,
                  ),
                ),
              ] else ...[
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 6,
                    vertical: 2,
                  ),
                  decoration: BoxDecoration(
                    color: isDark
                        ? Colors.white10
                        : Colors.black.withValues(alpha: 0.05),
                    borderRadius: BorderRadius.circular(4),
                  ),
                  child: Text(
                    WhyThisRouteLocalization.dataUnavailable(_isTamil),
                    style: TextStyle(
                      fontSize: 9.5,
                      fontWeight: FontWeight.w600,
                      color: isDark
                          ? _NeonTheme.textSecondaryDark
                          : _NeonTheme.textSecondaryLight,
                    ),
                  ),
                ),
              ],
            ],
          ),
          const SizedBox(height: 6),
          // Visual Progress Bar
          Container(
            height: 6,
            width: double.infinity,
            decoration: BoxDecoration(
              color: isDark ? Colors.white10 : Colors.black12,
              borderRadius: BorderRadius.circular(3),
            ),
            child: isAvail && score != null
                ? FractionallySizedBox(
                    alignment: Alignment.centerLeft,
                    widthFactor: (score / 100.0).clamp(0.0, 1.0),
                    child: Container(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          colors: [color.withValues(alpha: 0.7), color],
                        ),
                        borderRadius: BorderRadius.circular(3),
                      ),
                    ),
                  )
                : null,
          ),
          const SizedBox(height: 6),
          // Deterministic commentary
          Text(
            commentary,
            style: TextStyle(
              fontSize: 10.5,
              height: 1.35,
              color: isAvail
                  ? (isDark ? Colors.white70 : Colors.black87)
                  : (isDark
                        ? _NeonTheme.textSecondaryDark
                        : _NeonTheme.textSecondaryLight),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildSafetyVsTimeSection(WhyThisRouteAnalysis analysis, bool isDark) {
    final safestNum = analysis.safestRouteIndex + 1;
    final fastestNum = analysis.fastestRouteIndex + 1;
    final safestScore = analysis.safestRouteScore != null
        ? '${analysis.safestRouteScore!.round()}/100'
        : '--/100';
    final fastestScore = analysis.fastestRouteScore != null
        ? '${analysis.fastestRouteScore!.round()}/100'
        : '--/100';
    final safestDuration = widget.formatDurationFn(
      analysis.safestRouteDurationMinutes,
    );
    final fastestDuration = widget.formatDurationFn(
      analysis.fastestRouteDurationMinutes,
    );

    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: isDark
            ? _NeonTheme.bgDark.withValues(alpha: 0.6)
            : const Color(0xffF8FAFC),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: isDark ? Colors.white10 : Colors.black12,
          width: 0.8,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              const Icon(
                Icons.balance_rounded,
                size: 16,
                color: _NeonTheme.neonAmber,
              ),
              const SizedBox(width: 8),
              Text(
                WhyThisRouteLocalization.safetyVsTimeHeading(_isTamil),
                style: TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 0.5,
                  color: isDark
                      ? _NeonTheme.neonAmber
                      : const Color(0xffD97706),
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          Row(
            children: [
              Expanded(
                child: Container(
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(
                    color: _NeonTheme.safeGreen.withValues(alpha: 0.1),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                      color: _NeonTheme.safeGreen.withValues(alpha: 0.35),
                      width: 1,
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          const Icon(
                            Icons.shield_rounded,
                            size: 13,
                            color: _NeonTheme.safeGreen,
                          ),
                          const SizedBox(width: 4),
                          Flexible(
                            child: Text(
                              WhyThisRouteLocalization.safetyFirstRoute(
                                _isTamil,
                              ),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                fontSize: 10,
                                fontWeight: FontWeight.w700,
                                color: _NeonTheme.safeGreen,
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 4),
                      Text(
                        'Route $safestNum — $safestScore — $safestDuration',
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w800,
                          color: isDark ? Colors.white : Colors.black87,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Container(
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(
                    color: _NeonTheme.electricBlue.withValues(alpha: 0.1),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                      color: _NeonTheme.electricBlue.withValues(alpha: 0.35),
                      width: 1,
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          const Icon(
                            Icons.speed_rounded,
                            size: 13,
                            color: _NeonTheme.electricBlue,
                          ),
                          const SizedBox(width: 4),
                          Flexible(
                            child: Text(
                              WhyThisRouteLocalization.fastestRoute(_isTamil),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                fontSize: 10,
                                fontWeight: FontWeight.w700,
                                color: _NeonTheme.electricBlue,
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 4),
                      Text(
                        'Route $fastestNum — $fastestScore — $fastestDuration',
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w800,
                          color: isDark ? Colors.white : Colors.black87,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Text(
            _isTamil
                ? analysis.tamilSafetyVsTimeNarrative
                : analysis.safetyVsTimeNarrative,
            style: TextStyle(
              fontSize: 10.5,
              height: 1.35,
              color: isDark
                  ? _NeonTheme.textSecondaryDark
                  : _NeonTheme.textSecondaryLight,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildRecommendationBanner(
    WhyThisRouteAnalysis analysis,
    bool isDark,
  ) {
    final badgeText = _isTamil
        ? analysis.tamilRecommendationBadge
        : analysis.recommendationBadge;
    final color = analysis.recommendationBadgeColor;

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.14),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: color.withValues(alpha: 0.6), width: 1.2),
        boxShadow: isDark
            ? [
                BoxShadow(
                  color: color.withValues(alpha: 0.25),
                  blurRadius: 10,
                  spreadRadius: 1,
                ),
              ]
            : null,
      ),
      child: Row(
        children: [
          Icon(analysis.recommendationBadgeIcon, size: 20, color: color),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  badgeText,
                  style: TextStyle(
                    fontSize: 12.5,
                    fontWeight: FontWeight.w900,
                    letterSpacing: 0.4,
                    color: color,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  _isTamil ? 'உண்மை தரவு அடிப்படையிலான பரிந்துரை' : 'Recommendation based strictly on evaluated safety scores & road data',
                  style: TextStyle(
                    fontSize: 9.5,
                    color: isDark
                        ? _NeonTheme.textSecondaryDark
                        : _NeonTheme.textSecondaryLight,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildDialogFooter(bool isDark) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(18, 0, 18, 14),
      child: SizedBox(
        width: double.infinity,
        child: ElevatedButton(
          onPressed: () => Navigator.of(context).pop(),
          style: ElevatedButton.styleFrom(
            backgroundColor: _NeonTheme.neonCyan,
            foregroundColor: Colors.black,
            padding: const EdgeInsets.symmetric(vertical: 11),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(10),
            ),
          ),
          child: Text(
            WhyThisRouteLocalization.done(_isTamil).toUpperCase(),
            style: const TextStyle(
              fontWeight: FontWeight.w800,
              letterSpacing: 0.8,
            ),
          ),
        ),
      ),
    );
  }
}